import sys

ESCAPES = (("&", "&amp;"), ("<", "&lt;"), (">", "&gt;"))


def escape(text):
    """Replace the characters that would otherwise be read as markup."""
    for raw, entity in ESCAPES:
        text = text.replace(raw, entity)
    return text


def header_level(line):
    """Count the leading hash symbols, clamped to the deepest legal header."""
    level = 0
    while level < len(line) and line[level] == "#":
        level += 1
    if level > 6:
        level = 6
    return level


def parse(document):
    """Turn raw text lines into a single HTML-ish document string."""
    parts = []
    in_list = False
    for raw in document:
        line = raw.strip()
        if not line:
            continue
        if line.startswith("#"):
            if in_list:
                parts.append("</ul>")
                in_list = False
            level = header_level(line)
            text = escape(line[level:].strip())
            parts.append("<h{0}>{1}</h{0}>".format(level, text))
        elif line.startswith("-"):
            if not in_list:
                parts.append("<ul>")
                in_list = True
            parts.append("<li>{0}</li>".format(escape(line[1:].strip())))
        else:
            if in_list:
                parts.append("</ul>")
                in_list = False
            parts.append("<p>{0}</p>".format(escape(line)))
    if in_list:
        parts.append("</ul>")
    return "\n".join(parts)


def read_lines(path):
    with open(path, encoding="utf-8") as handle:
        return handle.read().splitlines()


def main(argv):
    if len(argv) > 1:
        try:
            document = read_lines(argv[1])
        except OSError as exc:
            print("cannot read {0}: {1}".format(argv[1], exc), file=sys.stderr)
            return 1
    else:
        document = sys.stdin.read().splitlines()
    rendered = parse(document)
    if rendered:
        print(rendered)
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

