import sys


def aggregate(records):
    totals = {}
    for region, product, amount in records:
        if amount < 0:
            continue
        key = (region, product)
        totals[key] = totals.get(key, 0) + amount
    region_totals = {}
    for (region, _product), amount in totals.items():
        region_totals[region] = region_totals.get(region, 0) + amount
    result = []
    for (region, product), amount in sorted(totals.items()):
        base = region_totals[region]
        if base:
            percentage = round(amount * 100.0 / base, 2)
        else:
            percentage = 0.0
        result.append((region, product, amount, percentage))
    return result


def parse_line(line, lineno):
    fields = [field.strip() for field in line.split(',')]
    if len(fields) != 3:
        raise ValueError("line %d: expected 3 fields, got %d" % (lineno, len(fields)))
    region, product, raw_amount = fields
    try:
        amount = int(raw_amount)
    except ValueError:
        raise ValueError("line %d: amount %r is not an integer" % (lineno, raw_amount))
    return (region, product, amount)


def read_records(path):
    records = []
    with open(path) as handle:
        for lineno, line in enumerate(handle, 1):
            stripped = line.strip()
            if not stripped or stripped.startswith('#'):
                continue
            records.append(parse_line(line, lineno))
    return records


def format_report(rows):
    width = 0
    for region, product, _total, _percentage in rows:
        label = region + '/' + product
        if len(label) > width:
            width = len(label)
    lines = []
    for region, product, total, percentage in rows:
        label = (region + '/' + product).ljust(width)
        lines.append("%s %8d %7.2f%%" % (label, total, percentage))
    return "\n".join(lines)


def main(argv):
    paths = []
    index = 0
    while index < len(argv):
        argument = argv[index]
        if argument == '--':
            paths.extend(argv[index + 1:])
            break
        paths.append(argument)
        index += 1
    if not paths:
        print("usage: sales.py FILE [FILE ...]")
        return 2
    records = []
    for path in paths:
        try:
            records.extend(read_records(path))
        except (OSError, ValueError) as exc:
            print("error: %s" % exc)
            return 1
    print(format_report(aggregate(records)))
    return 0


if __name__ == '__main__':
    sys.exit(main(sys.argv[1:]))

