import sys


class CycleError(Exception):
    """Raised when the dependency graph cannot be linearised."""


def parse_dependencies(text):
    """Turn lines of the form 'first -> second' into pairs of task names."""
    pairs = []
    for lineno, raw in enumerate(text.splitlines(), start=1):
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        if "->" not in line:
            raise ValueError("line %d: expected 'first -> second'" % lineno)
        first, second = line.split("->", 1)
        pairs.append((first.strip(), second.strip()))
    return pairs


def build_graph(dependencies):
    """Build an adjacency map where an edge a -> b means 'a before b'."""
    graph = {}
    for pair in dependencies:
        first, second = pair
        for task in (first, second):
            if not isinstance(task, str) or not task:
                raise ValueError("task names must be non-empty strings")
            graph.setdefault(task, set())
        graph[first].add(second)
    return graph


def schedule(dependencies):
    """Return a safe execution order, or [] when a cycle is present."""
    graph = build_graph(dependencies)
    state = {}
    order = []
    try:
        for root in sorted(graph):
            if state.get(root) == "done":
                continue
            stack = [(root, False)]
            while stack:
                task, finished = stack.pop()
                if finished:
                    state[task] = "done"
                    order.append(task)
                    continue
                if state.get(task) == "done":
                    continue
                if state.get(task) == "visiting":
                    raise CycleError(task)
                state[task] = "visiting"
                stack.append((task, True))
                for nxt in sorted(graph[task], reverse=True):
                    if state.get(nxt) != "done":
                        stack.append((nxt, False))
    except CycleError:
        return []
    order.reverse()
    return order


def format_report(order):
    if not order:
        return "Circular dependency detected: no safe order exists."
    lines = ["Execution order:"]
    for step, task in enumerate(order, start=1):
        lines.append("  %2d. %s" % (step, task))
    return "\n".join(lines)


def main(argv):
    default_text = """
    design -> implement
    implement -> test
    test -> release
    design -> docs
    docs -> release
    """
    if len(argv) > 1:
        with open(argv[1], encoding="utf-8") as handle:
            text = handle.read()
    else:
        text = default_text
    dependencies = parse_dependencies(text)
    print(format_report(schedule(dependencies)))


main(sys.argv)

