        for nxt in sorted(graph[task], reverse=True):
          if state.get(nxt) != "done":
            stack.append((nxt, False))
  except CycleError:
    return []
  order.reverse()
  return order


def format_report(order):
  if not order:
    return "Circular dependency detected: no safe order exists."
  lines = ["Execution order:"]
  for step, task in enumerate(order, start=1):
    lines.append("  %2d. %s" % (step, task))
  return "\n".join(lines)


def main(argv):
