            digit = 0
        else:
            digit = int(token)
        if digit < 0 or digit > 9:
            raise ValueError(f"cell out of range: {token}")
        row.append(digit)
    if len(row) != 9:
        raise ValueError(f"expected nine cells, found {len(row)}")
    return row


def parse_board(lines):
    rows = []
    position = 0
    while len(rows) < 9:
        if position >= len(lines):
            raise ValueError(f"expected nine rows, found {len(rows)}")
        line = lines[position].strip()
        position += 1
        if line and not line.startswith("-"):
            rows.append(parse_row(line))
    return rows


def has_duplicates(values):
    seen = set()
    for value in values:
        if value != 0:
            if value in seen:
                return True
            seen.add(value)
    return False


def validate(board):
    for row in board:
        if has_duplicates(row):
            return False
    for column in range(9):
        if has_duplicates([board[row][column] for row in range(9)]):
            return False
    for top in (0, 3, 6):
        for left in (0, 3, 6):
            block = [board[top + r][left + c] for r in range(3) for c in range(3)]
            if has_duplicates(block):
                return False
    return True


def format_board(board):
