import sys

OPERATORS = ("+", "-", "*", "/")


def apply_operator(op, left, right):
    """Combine two integers with one of the four basic operators."""
    if op == "+":
        return left + right
    elif op == "-":
        return left - right
    elif op == "*":
        return left * right
    else:
        return int(left / right)


def calculate(expression):
    """Evaluate a space separated reverse polish notation expression."""
    stack = []
    for token in expression.split():
        if token in OPERATORS:
            if len(stack) < 2:
                return 0
            right = stack.pop()
            left = stack.pop()
            try:
                stack.append(apply_operator(token, left, right))
            except ZeroDivisionError:
                return 0
        else:
            try:
                stack.append(int(token))
            except ValueError:
                return 0
    if len(stack) != 1:
        return 0
    return stack[0]


def format_report(expression, value):
    """Render one evaluated expression as a single output line."""
    return "{0} => {1}".format(expression, value)


def run_stream(stream):
    """Evaluate every non-empty line of an already opened text stream."""
    handled = 0
    for line in stream:
        text = line.strip()
        if not text:
            continue
        print(format_report(text, calculate(text)))
        handled += 1
    return handled


def repl(stream):
    """Read and evaluate expressions typed one per line until end of input."""
    handled = 0
    while True:
        line = stream.readline()
        if not line:
            break
        text = line.strip()
        if text:
            print(format_report(text, calculate(text)))
            handled += 1
    return handled


def main(argv):
    if len(argv) > 1:
        with open(argv[1], "r", encoding="utf-8") as handle:
            handled = run_stream(handle)
    else:
        handled = repl(sys.stdin)
    print("evaluated {0} expression(s)".format(handled))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

