def parse_transactions(tokens):
    """Turn "inserted:price" strings into (inserted, price) integer pairs."""
    parsed = []
    for token in tokens:
        try:
            inserted_text, price_text = token.split(":")
            inserted = int(inserted_text)
            price = int(price_text)
        except ValueError:
            print(f"ignoring malformed entry: {token!r}")
            continue
        parsed.append((inserted, price))
    return parsed


def make_change(amount, pool):
    """Greedily pick coins from pool summing to amount, or None if impossible."""
    candidates = sorted(pool, reverse=True)
    remaining = amount
    used = []
    index = 0
    while remaining > 0 and index < len(candidates):
        coin = candidates[index]
        if coin <= remaining:
            remaining -= coin
            used.append(coin)
        index += 1
    if remaining > 0:
        return None
    return used


def dispense(transactions, coins):
    """Process transactions, returning (successes, remaining machine coins)."""
    pool = list(coins)
    successes = 0
    for inserted, price in transactions:
        if inserted < price:
            print(f"insufficient payment: {inserted} for an item costing {price}")
            continue
        change = inserted - price
        if change == 0:
            successes += 1
            continue
        payout = make_change(change, pool)
        if payout is None:
            print(f"cannot make change of {change}; transaction skipped")
            continue
        for coin in payout:
            pool.remove(coin)
        successes += 1
    return successes, pool


