import sys


def tokenize(expression):
    """Split an expression string into integers and operator/paren symbols."""
    tokens = []
    index = 0
    while index < len(expression):
        char = expression[index]
        if char.isspace():
            index += 1
        elif char.isdigit():
            start = index
            while index < len(expression) and expression[index].isdigit():
                index += 1
            tokens.append(int(expression[start:index]))
        elif char in "+-*()":
            tokens.append(char)
            index += 1
        else:
            raise ValueError("unexpected character %r at position %d" % (char, index))
    return tokens


class Parser:
    """Recursive-descent parser over a token list."""

    def __init__(self, tokens):
        self.tokens = tokens
        self.position = 0

    def peek(self):
        if self.position < len(self.tokens):
            return self.tokens[self.position]
        return None

    def take(self):
        token = self.peek()
        if token is None:
            raise ValueError("unexpected end of expression")
        self.position += 1
        return token

    def parse_sum(self):
        value = self.parse_product()
        while self.peek() in ("+", "-"):
            operator = self.take()
            right = self.parse_product()
            if operator == "+":
                value += right
            else:
                value -= right
        return value

    def parse_product(self):
        value = self.parse_atom()
        while self.peek() == "*":
            self.take()
            value *= self.parse_atom()
        return value

    def parse_atom(self):
        token = self.take()
        if token == "(":
            value = self.parse_sum()
            if self.take() != ")":
                raise ValueError("missing closing parenthesis")
            return value
        if token == "-":
            return -self.parse_atom()
        if isinstance(token, int):
            return token
        raise ValueError("unexpected token %r" % (token,))


def evaluate(expression):
    parser = Parser(tokenize(expression))
    result = parser.parse_sum()
    leftover = parser.peek()
    if leftover is not None:
        raise ValueError("trailing token %r" % (leftover,))
    return result


def report(lines):
    for line in lines:
        text = line.strip()
        if not text:
            continue
        try:
            print("%s = %d" % (text, evaluate(text)))
        except ValueError as error:
            print("%s -> error: %s" % (text, error))


def main(argv):
    if len(argv) > 1:
        for path in argv[1:]:
            with open(path) as handle:
                report(handle)
    else:
        report(sys.stdin)


if __name__ == "__main__":
