import re

TAG_PATTERN = re.compile(r"<(/?)([A-Za-z][A-Za-z0-9]*)>")


def tokenize(document):
    """Yield (is_closing, name) pairs for every tag found in the document."""
    tokens = []
    for match in TAG_PATTERN.finditer(document):
        slash, name = match.group(1), match.group(2)
        tokens.append((slash == "/", name))
    return tokens


def verify(document):
    """Return True when every tag in the document is properly nested and closed."""
    if not isinstance(document, str):
        raise TypeError("document must be a string")
    stack = []
    for is_closing, name in tokenize(document):
        if is_closing:
            if not stack:
                return False
            if stack.pop() != name:
                return False
        else:
            stack.append(name)
    return not stack


def describe(document):
    """Build a human readable report about the nesting structure of a document."""
    lines = []
    depth = 0
    for is_closing, name in tokenize(document):
        if is_closing:
            depth -= 1
            if depth < 0:
                lines.append("!! stray closing tag </%s>" % name)
                depth = 0
            else:
                lines.append("%s</%s>" % ("  " * depth, name))
        else:
            lines.append("%s<%s>" % ("  " * depth, name))
            depth += 1
    while depth > 0:
        depth -= 1
        lines.append("!! tag left unclosed at depth %d" % depth)
    return "\n".join(lines)


def main():
    documents = [
        "<a><b></b></a>",
        "<html><body><p>text</p></body></html>",
        "<a><b></a></b>",
        "<a><b></b>",
        "</a>",
    ]
    for document in documents:
        try:
            balanced = verify(document)
        except TypeError as error:
            print("skipped: %s" % error)
            continue
        print("%-40s -> %s" % (document, balanced))
        if not balanced:
            for line in describe(document).splitlines():
                print("    %s" % line)


if __name__ == "__main__":
    main()

