import sys


def parse_grid(text):
    """Turn text such as '110\n100' or '1 1 0' rows into a matrix of ints."""
    matrix = []
    for line in text.splitlines():
        stripped = line.strip()
        if not stripped:
            continue
        tokens = stripped.replace(",", " ").split()
        if len(tokens) == 1:
            tokens = list(tokens[0])
        matrix.append([int(token) for token in tokens])
    return matrix


def validate(matrix):
    """Reject grids that are empty, ragged, or hold values other than 0 and 1."""
    if not matrix:
        raise ValueError("grid must contain at least one row")
    width = len(matrix[0])
    for index, row in enumerate(matrix):
        if len(row) != width:
            raise ValueError("row %d has %d cells, expected %d" % (index, len(row), width))
        for value in row:
            if value not in (0, 1):
                raise ValueError("cell value %r is neither wall (1) nor space (0)" % value)


def region_size(matrix, start, visited):
    """Flood fill from start, marking every reachable zero as visited."""
    queue = [start]
    visited.add(start)
    size = 0
    while queue:
        row, col = queue.pop()
        size += 1
        for delta_row, delta_col in ((-1, 0), (1, 0), (0, -1), (0, 1)):
            next_row, next_col = row + delta_row, col + delta_col
            if 0 <= next_row < len(matrix) and 0 <= next_col < len(matrix[0]):
                if matrix[next_row][next_col] == 0 and (next_row, next_col) not in visited:
                    visited.add((next_row, next_col))
                    queue.append((next_row, next_col))
    return size


def fill(matrix):
    validate(matrix)
    visited = set()
    sizes = []
    for row_index, row in enumerate(matrix):
        for col_index, value in enumerate(row):
            if value == 0 and (row_index, col_index) not in visited:
                sizes.append(region_size(matrix, (row_index, col_index), visited))
    return sorted(sizes, reverse=True)


def format_report(sizes):
    lines = []
    if not sizes:
        lines.append("no empty regions found")
    else:
        lines.append("regions: %d" % len(sizes))
        for rank, size in enumerate(sizes, 1):
            lines.append("  #%d: %d cell%s" % (rank, size, "" if size == 1 else "s"))
        lines.append("total empty cells: %d" % sum(sizes))
    return "\n".join(lines)


def main(argv):
    if len(argv) > 1:
        with open(argv[1], encoding="utf-8") as handle:
            text = handle.read()
    else:
        text = sys.stdin.read()
    try:
        sizes = fill(parse_grid(text))
    except ValueError as exc:
        print("error: %s" % exc, file=sys.stderr)
        return 1
    print(format_report(sizes))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

