import re
import sys

TIMESTAMP = re.compile(r"(\d{2}):(\d{2}):(\d{2})[,:.](\d{3})")


def parse_time(stamp):
    """Convert a single timestamp into a whole number of milliseconds."""
    match = TIMESTAMP.fullmatch(stamp.strip())
    if match is None:
        raise ValueError("malformed timestamp: %r" % stamp)
    hours, minutes, seconds, millis = (int(group) for group in match.groups())
    if minutes > 59 or seconds > 59:
        raise ValueError("timestamp outside standard bounds: %r" % stamp)
    return (((hours * 60) + minutes) * 60 + seconds) * 1000 + millis


def format_time(total):
    """Render milliseconds as hh:mm:ss,mmm, rolling seconds/minutes/hours over."""
    if total < 0:
        total = 0
    seconds, millis = divmod(total, 1000)
    minutes, seconds = divmod(seconds, 60)
    hours, minutes = divmod(minutes, 60)
    return "%02d:%02d:%02d,%03d" % (hours % 24, minutes, seconds, millis)


def shift(subtitles, offset):
    """Return the subtitle entries with both times moved by offset milliseconds."""
    shifted = []
    for entry in subtitles:
        lines = []
        for line in entry.splitlines():
            if "-->" in line:
                start, end = line.split("-->")
                lines.append("%s --> %s" % (
                    format_time(parse_time(start) + offset),
                    format_time(parse_time(end) + offset),
                ))
            else:
                lines.append(line.rstrip())
        shifted.append("\n".join(lines))
    return shifted


def parse_blocks(lines):
    """Group raw file lines into one string per subtitle entry."""
    blocks = []
    index = 0
    while index < len(lines):
        block = []
        while index < len(lines) and lines[index].strip():
            block.append(lines[index].rstrip("\r\n"))
            index += 1
        while index < len(lines) and not lines[index].strip():
            index += 1
        if block:
            blocks.append("\n".join(block))
    return blocks


def main(argv):
    if len(argv) < 2:
        print("usage: %s OFFSET_MS [FILE]" % argv[0])
        return 1
    try:
        offset = int(argv[1])
    except ValueError:
        print("offset must be an integer number of milliseconds")
        return 2
    if len(argv) > 2:
        with open(argv[2], encoding="utf-8") as handle:
            entries = parse_blocks(handle.readlines())
    else:
        entries = parse_blocks(sys.stdin.readlines())
    try:
        adjusted = shift(entries, offset)
    except ValueError as error:
        print("error: %s" % error)
        return 3
    for entry in adjusted:
        print(entry)
        print()
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

