def maximize(numbers, size):
    """Return the maximum of every contiguous sublist of length `size`."""
    if size <= 0 or not numbers:
        return []
    if size > len(numbers):
        return []
    window = deque()
    maxima = []
    for index, value in enumerate(numbers):
        while window and numbers[window[-1]] <= value:
            window.pop()
