def parse_color(text):
    """Turn '#rrggbb' into an (r, g, b) tuple of integers."""
    if not isinstance(text, str):
        raise TypeError(f"color must be a string, got {type(text).__name__}")
    cleaned = text.strip()
    if not cleaned.startswith("#") or len(cleaned) != 7:
        raise ValueError(f"expected '#' followed by six hex digits, got {text!r}")
    components = []
    for offset in (1, 3, 5):
        chunk = cleaned[offset:offset + 2]
        try:
            components.append(int(chunk, 16))
        except ValueError:
            raise ValueError(f"invalid hex pair {chunk!r} in {text!r}") from None
    return tuple(components)


def format_color(components):
    """Turn an iterable of three numbers into a '#rrggbb' string."""
    parts = []
    for value in components:
        clamped = max(0, min(255, int(value)))
        parts.append(f"{clamped:02x}")
    return "#" + "".join(parts)


def interpolate(start, end, steps):
    """Return a list of `steps` hex colors running from `start` to `end`."""
    if steps < 1:
        raise ValueError(f"steps must be at least 1, got {steps}")
    first = parse_color(start)
    last = parse_color(end)
    if steps == 1:
        return [format_color(first)]
    gradient = [format_color(first)]
    index = 1
    while index < steps - 1:
        ratio = index / (steps - 1)
        blended = []
        for low, high in zip(first, last):
            blended.append(round(low + (high - low) * ratio))
        gradient.append(format_color(blended))
        index += 1
    gradient.append(format_color(last))
    return gradient


def render_table(colors):
    """Describe each color of a gradient as an aligned text row."""
    rows = []
    for position, color in enumerate(colors):
        red, green, blue = parse_color(color)
        rows.append(f"{position:>3}  {color}  rgb({red:3d}, {green:3d}, {blue:3d})")
    return rows


def write_report(path, colors):
    with open(path, "w", encoding="utf-8") as handle:
        for row in render_table(colors):
            handle.write(row + "\n")


def main(argv):
    if len(argv) >= 3:
        start, end, steps = argv[0], argv[1], int(argv[2])
    else:
        start, end, steps = "#000000", "#ffffff", 3
    colors = interpolate(start, end, steps)
    for row in render_table(colors):
        print(row)
    if len(argv) >= 4:
        write_report(argv[3], colors)
        print(f"gradient written to {argv[3]}")


