import os
import sys


def split_pairs(text):
    """Split text on the commas that are not inside square brackets."""
    pairs = []
    current = []
    depth = 0
    index = 0
    while index < len(text):
        char = text[index]
        if char == '[':
            depth += 1
        elif char == ']':
            if depth > 0:
                depth -= 1
        if char == ',' and depth == 0:
            pairs.append(''.join(current))
            current = []
        else:
            current.append(char)
        index += 1
    pairs.append(''.join(current))
    return pairs


def parse_value(raw):
    """Return a trimmed string, or a list of words for bracketed values."""
    value = raw.strip()
    if value.startswith('[') and value.endswith(']'):
        return value[1:-1].split()
    return value


def parse(text):
    result = []
    for chunk in split_pairs(text):
        if not chunk.strip():
            continue
        key, separator, raw_value = chunk.partition(':')
        if separator:
            result.append((key.strip(), parse_value(raw_value)))
        else:
            result.append((key.strip(), ''))
    return result


def format_pairs(pairs):
    lines = []
    for key, value in pairs:
        if isinstance(value, list):
            shown = '[' + ', '.join(value) + ']'
        else:
            shown = value
        lines.append('{0:<12} -> {1}'.format(key, shown))
    return '\n'.join(lines)


def read_text(arguments):
    if arguments:
        candidate = arguments[0]
        if os.path.isfile(candidate):
            with open(candidate, encoding='utf-8') as handle:
                return handle.read()
        return ', '.join(arguments)
    return sys.stdin.read()


