def normalize_items(items):
    normalized = []
    for price, weight, category in items:
        normalized.append((float(price), float(weight), category.strip().lower()))
    return normalized


def subtotal(items):
    total = 0.0
    for price, _weight, _category in items:
        total += price
    return total


def total_weight(items):
    pounds = 0.0
    for _price, weight, _category in items:
        pounds += weight
    return pounds


def category_subtotals(items):
    buckets = {}
    for price, _weight, category in items:
        buckets[category] = buckets.get(category, 0.0) + price
    return buckets


def discount_amount(coupon, cart_subtotal, buckets):
    kind = coupon.get("type", "")
    if kind == "flat":
        minimum = float(coupon.get("min_subtotal", 0.0))
        if cart_subtotal >= minimum:
            return min(float(coupon["amount"]), cart_subtotal)
        return 0.0
    elif kind == "percent":
        category = coupon["category"].strip().lower()
        return buckets.get(category, 0.0) * float(coupon["percent"]) / 100.0
    else:
        return 0.0


def best_coupon(coupons, cart_subtotal, buckets):
    winner, winning_value = None, 0.0
    for coupon in coupons:
        value = discount_amount(coupon, cart_subtotal, buckets)
        if value > winning_value:
            winner, winning_value = coupon, value
    return winner, winning_value


def shipping_fee(pounds):
    fee = 0.0
    remaining = pounds - 10.0
    while remaining > 0:
        fee += 5.0
        remaining -= 1.0
    return fee


def checkout(items, coupons):
