import sys

MULTIPLIERS = {"single": 1, "double": 2, "triple": 3}
MULTIPLIER_NAMES = {value: name for name, value in MULTIPLIERS.items()}
VALID_BASES = set(range(0, 21)) | {25}
STARTING_SCORE = 501


def parse_throw(raw):
    if isinstance(raw, str):
        parts = raw.split()
        if len(parts) != 2:
            raise ValueError("a throw must be a multiplier and a base value: %r" % (raw,))
        name, value = parts
    else:
        name, value = raw
    multiplier = MULTIPLIERS.get(str(name).strip().lower())
    if multiplier is None:
        raise ValueError("unknown multiplier: %r" % (name,))
    try:
        base = int(value)
    except (TypeError, ValueError):
        raise ValueError("base value must be an integer: %r" % (value,))
    if base not in VALID_BASES:
        raise ValueError("base value is not on a dartboard: %d" % base)
    return multiplier, base


def score(throws):
    parsed = [parse_throw(throw) for throw in throws]
    remaining = STARTING_SCORE
    index = 0
    while index < len(parsed):
        turn_start = remaining
        for multiplier, base in parsed[index:index + 3]:
            candidate = remaining - multiplier * base
            if candidate < 0 or candidate == 1:
                remaining = turn_start
                break
            remaining = candidate
            if remaining == 0:
                return 0
        index += 3
    return remaining


def describe(raw):
    multiplier, base = parse_throw(raw)
    return "%s %d (%d)" % (MULTIPLIER_NAMES[multiplier], base, multiplier * base)


def format_report(throws):
    lines = []
    for start in range(0, len(throws), 3):
        before = score(throws[:start])
        after = score(throws[:start + 3])
        darts = ", ".join(describe(raw) for raw in throws[start:start + 3])
        if after == before:
            lines.append("Turn %d: %s -> BUST, back to %d" % (start // 3 + 1, darts, before))
        else:
            lines.append("Turn %d: %s -> %d left" % (start // 3 + 1, darts, after))
    return lines


def load_throws(path):
    throws = []
    with open(path) as handle:
        for line in handle:
            text = line.strip()
            if text and not text.startswith("#"):
                throws.append(text)
    return throws


def main():
    if len(sys.argv) > 1:
        throws = load_throws(sys.argv[1])
    else:
        throws = [("triple", 20), ("triple", 20), ("triple", 20),
                  "triple 19", "triple 19", "triple 19",
                  "triple 20", "triple 20", "triple 15",
                  "triple 20", "single 20", "double 10"]
    for line in format_report(throws):
        print(line)
    print("Final score: %d" % score(throws))


if __name__ == "__main__":
    main()

