BASE_RATE = 2.00
ZONE_RATE = 0.50
PEAK_SURCHARGE = 1.00
DAILY_CAP = 20.00
PEAK_START = 7
PEAK_END = 9


def parse_trip(trip):
    """Normalise a trip into (start_zone, end_zone, hour)."""
    if isinstance(trip, dict):
        try:
            values = (trip["start"], trip["end"], trip["hour"])
        except KeyError as missing:
            raise ValueError("trip is missing field %s" % missing) from None
    else:
        values = tuple(trip)
        if len(values) != 3:
            raise ValueError("a trip needs exactly three fields")
    start, end, hour = (int(value) for value in values)
    if start < 1 or end < 1:
        raise ValueError("zone numbers start at 1")
    if not 0 <= hour <= 23:
        raise ValueError("hour must be between 0 and 23")
    return start, end, hour


def is_peak(hour):
    return PEAK_START <= hour < PEAK_END


def trip_cost(start, end, hour):
    cost = BASE_RATE + ZONE_RATE * abs(end - start)
    if is_peak(hour):
        cost += PEAK_SURCHARGE
    return cost


def fare(trips):
    """Total cost of a day of travel, capped at the daily maximum."""
    total = 0.0
    for trip in trips:
        start, end, hour = parse_trip(trip)
        total += trip_cost(start, end, hour)
        if total >= DAILY_CAP:
            return DAILY_CAP
    return round(total, 2)


def describe(trips):
    """Yield a human readable line for each trip, plus a summary line."""
    running = 0.0
    for index, trip in enumerate(trips, start=1):
        start, end, hour = parse_trip(trip)
        cost = trip_cost(start, end, hour)
        running = min(running + cost, DAILY_CAP)
        label = "peak" if is_peak(hour) else "off-peak"
        yield "%d. zone %d -> %d at %02d:00 (%s) $%.2f  running $%.2f" % (
            index, start, end, hour, label, cost, running)
    yield "Total due: $%.2f" % fare(trips)


def main():
    commute = [
        (1, 3, 8),
        (3, 1, 18),
        {"start": 1, "end": 1, "hour": 7},
        (2, 5, 23),
    ]
    for line in describe(commute):
        print(line)
    bad = [(1, 2, 25)]
    try:
        fare(bad)
    except ValueError as error:
        print("rejected trip: %s" % error)


if __name__ == "__main__":
    main()

