def parse_expense_line(line):
    """Turn 'Alice 60.00 Alice,Bob,Carol' into ('Alice', 60.0, ['Alice','Bob','Carol'])."""
    parts = line.split()
    if len(parts) != 3:
        raise ValueError("expected 'payer amount shares', got: %r" % line)
    payer, amount_text, share_text = parts
    try:
        amount = float(amount_text)
    except ValueError:
        raise ValueError("amount is not a number: %r" % amount_text)
    return (payer, amount, [name for name in share_text.split(",") if name])


def compute_balances(expenses):
    """Net balance in cents per person: positive means the group owes them."""
    balances = {}
    for payer, amount, participants in expenses:
        if not participants:
            raise ValueError("expense paid by %s has no participants" % payer)
        if amount < 0:
            raise ValueError("expense paid by %s has a negative amount" % payer)
        total = int(round(amount * 100))
        share, extra = divmod(total, len(participants))
        balances[payer] = balances.get(payer, 0) + total
        for index, person in enumerate(participants):
            owed = share
            if index < extra:
                owed += 1
            balances[person] = balances.get(person, 0) - owed
    return balances


def _search(names, amounts, start):
    while start < len(amounts) and amounts[start] == 0:
        start += 1
    if start == len(amounts):
        return []
    best = None
    for other in range(start + 1, len(amounts)):
        if amounts[other] * amounts[start] < 0:
            debt = amounts[start]
            amounts[other] += debt
            amounts[start] = 0
            rest = _search(names, amounts, start + 1)
            amounts[start] = debt
            amounts[other] -= debt
            if debt < 0:
                move = (names[start], names[other], -debt)
            else:
                move = (names[other], names[start], debt)
            candidate = [move] + rest
            if best is None or len(candidate) < len(best):
                best = candidate
    return best


def settle(expenses):
    """Return the minimal list of (debtor, creditor, amount) transfers."""
    balances = compute_balances(expenses)
    names, amounts = [], []
    for person, cents in sorted(balances.items()):
        if cents != 0:
            names.append(person)
            amounts.append(cents)
    transfers = _search(names, amounts, 0)
    return [(debtor, creditor, cents / 100.0) for debtor, creditor, cents in transfers]


def format_report(transfers):
    lines = []
    if not transfers:
        lines.append("Everyone is square.")
    for debtor, creditor, amount in transfers:
        lines.append("%s pays %s %.2f" % (debtor, creditor, amount))
    return "\n".join(lines)


def main():
    records = [
        "Alice 60.00 Alice,Bob,Carol",
        "Bob 30.00 Bob,Carol",
        "Carol 15.50 Alice,Carol",
        "Dave 90.00 Alice,Bob,Carol,Dave",
    ]
    expenses = []
    for line in records:
        try:
            expenses.append(parse_expense_line(line))
        except ValueError as error:
            print("skipping record (%s)" % error)
    report = format_report(settle(expenses))
    print(report)
    with open("settlement.txt", "w") as handle:
        handle.write(report + "\n")


if __name__ == "__main__":
    main()

