import sys

VOWELS = "aeiou"
IRREGULARS = {
    "child": "children",
    "mouse": "mice",
    "man": "men",
    "woman": "women",
    "tooth": "teeth",
    "goose": "geese",
}
DEFAULT_WORDS = ["child", "mouse", "box", "church", "city", "boy", "dog", "bus"]


def pluralize(words):
    plurals = []
    for word in words:
        if not isinstance(word, str):
            raise TypeError("pluralize expects strings, got %r" % (word,))
        lowered = word.lower()
        if lowered in IRREGULARS:
            plurals.append(IRREGULARS[lowered])
        elif ends_with_sibilant(lowered):
            plurals.append(lowered + "es")
        elif lowered.endswith("y") and len(lowered) > 1 and lowered[-2] not in VOWELS:
            plurals.append(lowered[:-1] + "ies")
        else:
            plurals.append(lowered + "s")
    return plurals


def format_report(singulars, plurals):
    width = 0
    for word in singulars:
        if len(word) > width:
            width = len(word)
    lines = []
    index = 0
    while index < len(singulars):
        lines.append("%-*s -> %s" % (width, singulars[index], plurals[index]))
        index += 1
    return "\n".join(lines)


def read_words(path):
    words = []
    with open(path, encoding="utf-8") as handle:
        for line in handle:
            stripped = line.strip()
            if stripped:
                words.append(stripped)
    return words


def main(argv):
    if len(argv) > 1:
        try:
            words = read_words(argv[1])
        except OSError as error:
            print("cannot read %s: %s" % (argv[1], error), file=sys.stderr)
            return 1
    else:
        words = DEFAULT_WORDS
    if not words:
        print("no words to pluralize", file=sys.stderr)
        return 1
    print(format_report(words, pluralize(words)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

