    """Gregorian leap year rule."""
    if year % 400 == 0:
        return True
    if year % 100 == 0:
        return False
    return year % 4 == 0


def days_in_month(year, month):
    """Number of days in the given month, February adjusted for leap years."""
    if month < 1 or month > 12:
        raise ValueError("month must be between 1 and 12")
    if month == 2:
        if is_leap_year(year):
            return 29
        return 28
    if month in (4, 6, 9, 11):
        return 30
    return 31


def first_weekday(year, month):
    """Weekday of the first of the month via Zeller's congruence (0 = Monday)."""
    m = month
    y = year
    if m < 3:
        m += 12
        y -= 1
    k = y % 100
    j = y // 100
    h = (1 + (13 * (m + 1)) // 5 + k + k // 4 + j // 4 + 5 * j) % 7
    return (h + 5) % 7


def calendar(year, month):
    """Return the month as a list of weeks of seven day numbers (0 = empty)."""
    total = days_in_month(year, month)
    weeks = []
    week = [0] * first_weekday(year, month)
    for day in range(1, total + 1):
        week.append(day)
        if len(week) == 7:
            weeks.append(week)
            week = []
    if week:
