import sys

POINT_NAMES = ("love", "fifteen", "thirty", "forty")
PLAYERS = {"A": "Player A", "B": "Player B"}
ALIASES = {"A": "A", "a": "A", "1": "A", "B": "B", "b": "B", "2": "B"}


def normalise(points):
    winners = []
    for token in points:
        key = str(token).strip()
        if key in ALIASES:
            winners.append(ALIASES[key])
        else:
            raise ValueError("unknown point winner: {0!r}".format(token))
    return winners


def game_winner(a, b):
    if a >= 4 or b >= 4:
        if a - b >= 2:
            return PLAYERS["A"]
        if b - a >= 2:
            return PLAYERS["B"]
    return None


def running_score(a, b):
    if a >= 3 and b >= 3:
        if a == b:
            return "deuce"
        if a > b:
            return "advantage " + PLAYERS["A"]
        return "advantage " + PLAYERS["B"]
    if a == b:
        return POINT_NAMES[a] + "-all"
    return POINT_NAMES[a] + "-" + POINT_NAMES[b]


def referee(points):
    winners = normalise(points)
    a, b, index = 0, 0, 0
    while index < len(winners):
        if winners[index] == "A":
            a += 1
        else:
            b += 1
        index += 1
        champion = game_winner(a, b)
        if champion is not None:
            if index < len(winners):
                raise ValueError("points played after the game was decided")
            return champion
    return running_score(a, b)


def load_games(path):
    games = []
    with open(path) as handle:
        for line in handle:
            entry = line.strip()
            if entry and not entry.startswith("#"):
                games.append(entry)
    return games


def main():
    if len(sys.argv) > 1:
        games = load_games(sys.argv[1])
    else:
        games = ["", "AAAA", "ABABAB", "ABABABAB", "ABABABABBB", "AAABBBBB", "AAX"]
    for game in games:
        label = game or "(no points)"
        try:
            print("{0:<12} -> {1}".format(label, referee(game)))
        except ValueError as exc:
            print("{0:<12} -> invalid game: {1}".format(label, exc))


if __name__ == "__main__":
    main()

