import sys


def validate(items, capacity):
    """Reject inputs that cannot describe a packing problem."""
    if capacity <= 0:
        raise ValueError("capacity must be a positive number")
    for weight in items:
        if weight <= 0:
            raise ValueError("item weights must be positive: %r" % (weight,))
        if weight > capacity:
            raise ValueError("item of weight %g exceeds capacity %g" % (weight, capacity))


def pack(items, capacity):
    """First-fit-decreasing packing of weights into containers of given capacity."""
    validate(items, capacity)
    containers = []
    remaining = []
    for item in sorted(items, reverse=True):
        index = 0
        while index < len(containers):
            if remaining[index] >= item:
                containers[index].append(item)
                remaining[index] -= item
                break
            index += 1
        else:
            containers.append([item])
            remaining.append(capacity - item)
    return containers


def parse_weights(text):
    """Read whitespace- or comma-separated numbers out of a chunk of text."""
    weights = []
    for token in text.replace(",", " ").split():
        try:
            weights.append(float(token))
        except ValueError:
            raise ValueError("not a number: %r" % (token,))
    return weights


def load_weights(path):
    with open(path, "r", encoding="utf-8") as handle:
        return parse_weights(handle.read())


def format_report(containers, capacity):
    lines = ["Packed %d item(s) into %d container(s):"
             % (sum(len(box) for box in containers), len(containers))]
    for number, box in enumerate(containers, start=1):
        load = sum(box)
        contents = " + ".join("%g" % weight for weight in box)
        lines.append("  #%d [%s] load %g/%g (%.1f%%)"
                     % (number, contents, load, capacity, 100.0 * load / capacity))
    return "\n".join(lines)


def main(argv):
    capacity = 10.0
    if len(argv) > 1:
        try:
            items = load_weights(argv[1])
        except (OSError, ValueError) as error:
            print("cannot read weights: %s" % (error,), file=sys.stderr)
            return 1
    else:
        items = [4, 8, 1, 4, 2, 1, 9, 5, 3, 7, 6, 2]
    try:
        containers = pack(items, capacity)
    except ValueError as error:
        print("invalid problem: %s" % (error,), file=sys.stderr)
        return 1
    print(format_report(containers, capacity))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

