import ast
import sys


def escape(text):
    """Return the body of a quoted string with quotes and backslashes escaped."""
    pieces = []
    for char in text:
        if char in ('"', '\\'):
            pieces.append('\\' + char)
        else:
            pieces.append(char)
    return ''.join(pieces)


def stringify(data):
    """Render nested lists, strings, integers and booleans as a raw string."""
    if isinstance(data, bool):
        if data:
            return 'true'
        return 'false'
    if isinstance(data, int):
        return str(data)
    if isinstance(data, str):
        return '"' + escape(data) + '"'
    if isinstance(data, list):
        items = []
        for element in data:
            items.append(stringify(element))
        return '[' + ','.join(items) + ']'
    raise TypeError('unsupported type: ' + type(data).__name__)


def max_depth(data):
    """Nesting depth of a value: 0 for scalars, 1 for a flat list, and so on."""
    if not isinstance(data, list):
        return 0
    deepest = 0
    for element in data:
        inner = max_depth(element)
        if inner > deepest:
            deepest = inner
    return deepest + 1


def read_literals(path):
    """Read Python literals from a file, allowing one literal to span lines."""
    literals = []
    buffer = ''
    with open(path, encoding='utf-8') as handle:
        for line in handle:
            stripped = line.strip()
            if not stripped:
                continue
            buffer += stripped
            try:
                literals.append(ast.literal_eval(buffer))
            except (SyntaxError, ValueError):
                continue
            buffer = ''
    if buffer:
        raise ValueError('incomplete literal at end of file')
    return literals


def main():
    pending = list(sys.argv[1:])
    if not pending:
        print('usage: stringify.py FILE [FILE ...]', file=sys.stderr)
        return 2
    status = 0
    while pending:
        path = pending.pop(0)
        try:
            literals = read_literals(path)
        except (OSError, ValueError) as exc:
            print('%s: %s' % (path, exc), file=sys.stderr)
            status = 1
            continue
        for index, data in enumerate(literals):
            try:
                text = stringify(data)
            except TypeError as exc:
                print('%s[%d]: %s' % (path, index, exc), file=sys.stderr)
                status = 1
            else:
                print(text)
                print('%s[%d] depth=%d' % (path, index, max_depth(data)), file=sys.stderr)
    return status


if __name__ == '__main__':
    sys.exit(main())

