  """Drop every completely filled row and refill the top with empty rows."""
  if not grid:
    return [], 0
  width = len(grid[0])
  kept = []
  removed = 0
  for row in grid:
    if width and all(cell == 1 for cell in row):
      removed += 1
    else:
      kept.append(list(row))
  while len(kept) < len(grid):
    kept.insert(0, [0] * width)
  return kept, removed


def format_grid(grid, title):
  """Render a board as a small ASCII picture under a heading."""
  with io.StringIO() as buf:
    buf.write(title + "\n")
    for row in grid:
      buf.write(" ".join("#" if cell else "." for cell in row) + "\n")
    return buf.getvalue()


def main():
  text = ""
  if not sys.stdin.isatty():
    text = sys.stdin.read()
  if not text.strip():
    text = DEFAULT_BOARD
  try:
    grid = parse_grid(text)
  except ValueError as exc:
    print("invalid board: %s" % exc, file=sys.stderr)
    return 1
  result, removed = clear(grid)
  print(format_grid(grid, "before:"), end="")
  print(format_grid(result, "after:"), end="")
  if removed:
    print("cleared %d row(s)" % removed)
  else:
    print("no full rows found")
  return 0


if __name__ == "__main__":
  sys.exit(main())

