def normalize_action(action):
    """Map a raw action label onto one of deposit / withdrawal / interest."""
    aliases = {
        "deposit": "deposit",
        "credit": "deposit",
        "withdrawal": "withdrawal",
        "withdraw": "withdrawal",
        "debit": "withdrawal",
        "interest": "interest",
    }
    key = str(action).strip().lower()
    if key not in aliases:
        raise ValueError("unknown action type: {!r}".format(action))
    return aliases[key]


def process(transactions):
    """Return the final balance and the number of overdraft penalties applied."""
    balance = 0.0
    penalties = 0
    for action, amount in transactions:
        kind = normalize_action(action)
        try:
            value = float(amount)
        except (TypeError, ValueError):
            raise ValueError("invalid amount for {}: {!r}".format(kind, amount))
        if value < 0:
            raise ValueError("amounts must be non-negative, got {}".format(value))
        if kind == "deposit":
            balance += value
        elif kind == "withdrawal":
            balance -= value
            if balance < 0:
                balance *= 1.05
                penalties += 1
        else:
            if balance > 0:
                balance += balance * value / 100.0
    return round(balance, 2), penalties


def parse_transactions(text):
    """Read 'action amount' lines, ignoring blanks and # comments."""
    lines = text.splitlines()
    parsed = []
    index = 0
    while index < len(lines):
        line = lines[index].strip()
        index += 1
        if not line or line.startswith("#"):
            continue
        parts = line.split()
        if len(parts) != 2:
            raise ValueError("malformed transaction on line {}: {!r}".format(index, line))
        parsed.append((parts[0], parts[1]))
    return parsed


def format_report(transactions):
    balance, penalties = process(transactions)
    lines = ["Transaction report", "-" * 34]
    for position, (action, amount) in enumerate(transactions, 1):
        kind = normalize_action(action)
        value = float(amount)
        if kind == "interest":
            lines.append("{:>3}. {:<12} {:>10.2f}%".format(position, kind, value))
        else:
            lines.append("{:>3}. {:<12} {:>10.2f} ".format(position, kind, value))
    lines.append("-" * 34)
    lines.append("Final balance:     {:.2f}".format(balance))
    lines.append("Penalties applied: {}".format(penalties))
    return "\n".join(lines)


def main():
    ledger = """
    # opening month
    deposit 500
    withdraw 120.50
    interest 2.5
    debit 600
    credit 75
    """
    transactions = parse_transactions(ledger)
    report = format_report(transactions)
    with open("statement.txt", "w", encoding="utf-8") as handle:
        handle.write(report + "\n")
    print(report)


if __name__ == "__main__":
    main()

