import sys


def normalize_pattern(pattern):
    """Collapse runs of '*' since they are equivalent to a single '*'."""
    cleaned = []
    for char in pattern:
        if char == '*' and cleaned and cleaned[-1] == '*':
            continue
        cleaned.append(char)
    return ''.join(cleaned)


def strip_literal_prefix(pattern, filename):
    """Consume the leading wildcard-free part of the pattern, or fail."""
    index = 0
    while index < len(pattern) and pattern[index] not in '*?':
        if index >= len(filename) or pattern[index] != filename[index]:
            return None
        index += 1
    return pattern[index:], filename[index:]


def match(pattern, filename):
    head = strip_literal_prefix(normalize_pattern(pattern), filename)
    if head is None:
        return False
    pat, name = head
    rows, cols = len(pat), len(name)
    table = [[False] * (cols + 1) for _ in range(rows + 1)]
    table[0][0] = True
    for i in range(1, rows + 1):
        if pat[i - 1] == '*':
            table[i][0] = table[i - 1][0]
    for i in range(1, rows + 1):
        for j in range(1, cols + 1):
            symbol = pat[i - 1]
            if symbol == '*':
                table[i][j] = table[i - 1][j] or table[i][j - 1]
            elif symbol == '?':
                table[i][j] = table[i - 1][j - 1]
            else:
                table[i][j] = table[i - 1][j - 1] and symbol == name[j - 1]
    return table[rows][cols]


def parse_case(text):
    """Turn 'pattern filename' into a pair; the filename may be empty."""
    fields = text.split()
    if len(fields) > 2:
        raise ValueError("expected at most two fields, got %d" % len(fields))
    if len(fields) == 2:
        return fields[0], fields[1]
    return fields[0], ''


def read_lines(path):
    if path is None:
        return sys.stdin.read().splitlines()
    with open(path, encoding='utf-8') as handle:
        return handle.read().splitlines()


def main():
    path = sys.argv[1] if len(sys.argv) > 1 else None
    cases = []
    for number, line in enumerate(read_lines(path), 1):
        text = line.strip()
        if not text or text.startswith('#'):
            continue
        try:
            cases.append(parse_case(text))
        except ValueError as exc:
            print("line %d: %s" % (number, exc), file=sys.stderr)
    if not cases:
        print("no cases to evaluate", file=sys.stderr)
        return 1
    width = max(len(pattern) for pattern, _ in cases)
    matched = 0
    for pattern, filename in cases:
        verdict = match(pattern, filename)
        if verdict:
            matched += 1
        print("%-*s  %-20r  %s" % (width, pattern, filename,
                                   "MATCH" if verdict else "no match"))
    print("%d of %d patterns matched" % (matched, len(cases)))
    return 0


if __name__ == '__main__':
    sys.exit(main())

