import sys
from io import StringIO

GREEN_PHASE = 5
CAPACITY = 3


def light_is_green(step):
    return (step // GREEN_PHASE) % 2 == 0


def validate_arrivals(arrivals):
    for index, count in enumerate(arrivals):
        if not isinstance(count, int):
            raise TypeError(f"arrivals[{index}] is not an integer: {count!r}")
        if count < 0:
            raise ValueError(f"arrivals[{index}] is negative: {count}")


def run_steps(arrivals, ticks):
    validate_arrivals(arrivals)
    queue = 0
    for step in range(ticks):
        if step < len(arrivals):
            queue += arrivals[step]
        passed = 0
        if light_is_green(step):
            while queue > 0 and passed < CAPACITY:
                queue -= 1
                passed += 1
        yield step, passed, queue


def simulate(arrivals, ticks):
    total = 0
    for record in run_steps(arrivals, ticks):
        total += record[1]
    return total


def format_report(arrivals, ticks):
    with StringIO() as buf:
        buf.write("step  light  arrived  passed  queue\n")
        for step, passed, queue in run_steps(arrivals, ticks):
            if step < len(arrivals):
                arrived = arrivals[step]
            else:
                arrived = 0
            if light_is_green(step):
                light = "green"
            else:
                light = "red"
            buf.write(f"{step:>4}  {light:>5}  {arrived:>7}  {passed:>6}  {queue:>5}\n")
        return buf.getvalue()


def parse_args(argv):
    values = []
    for token in argv:
        try:
            values.append(int(token))
        except ValueError:
            raise SystemExit(f"not an integer: {token}")
    if not values:
        return [4, 2, 0, 6, 1, 3, 0, 0, 5, 2, 1, 4], 20
    return values[1:], values[0]


def main(argv):
    arrivals, ticks = parse_args(argv)
    try:
        report = format_report(arrivals, ticks)
    except (TypeError, ValueError) as exc:
        raise SystemExit(f"invalid arrivals: {exc}")
    print(report, end="")
    total = simulate(arrivals, ticks)
    waiting = sum(arrivals[:ticks]) - total
    print(f"cars through in {ticks} ticks: {total}")
    print(f"cars still waiting or yet to arrive: {waiting + sum(arrivals[ticks:])}")


if __name__ == "__main__":
    main(sys.argv[1:])

