import sys


def paginate(current, total):
    """Return page numbers with ellipses for a navigation component."""
    if total < 1:
        raise ValueError(f"total must be at least 1, got {total}")
    if current < 1 or current > total:
        raise ValueError(f"current {current} outside 1..{total}")
    required = {1, total, current}
    for offset in (-1, 1):
        neighbour = current + offset
        if 1 <= neighbour <= total:
            required.add(neighbour)
    pages = sorted(required)
    sequence = []
    index = 0
    while index < len(pages):
        page = pages[index]
        if index > 0 and page - pages[index - 1] > 1:
            sequence.append("...")
        sequence.append(page)
        index += 1
    return sequence


def render(sequence, current):
    """Format a paginated sequence, highlighting the current page."""
    parts = []
    for item in sequence:
        if item == current:
            parts.append(f"[{item}]")
        else:
            parts.append(str(item))
    return " ".join(parts)


def parse_request(text):
    """Turn a 'current/total' string into a pair of integers."""
    fields = text.split("/")
    if len(fields) != 2:
        raise ValueError(f"expected 'current/total', got {text!r}")
    numbers = []
    for field in fields:
        try:
            numbers.append(int(field.strip()))
        except ValueError:
            raise ValueError(f"{field.strip()!r} is not an integer")
    return numbers[0], numbers[1]


def collect_requests(arguments):
    """Expand command line arguments, reading '@file' entries line by line."""
    requests = []
    for argument in arguments:
        if argument.startswith("@"):
