    collected = {}
    for number, words in pages:
        for word in words:
            if len(word) < 4:
                continue
            key = word.lower()
            collected.setdefault(key, set()).add(number)
    return sorted((word, sorted(numbers)) for word, numbers in collected.items())


def parse_page(text):
    """Turn a line such as '12: the quick brown fox' into (12, [...])."""
    label, separator, rest = text.partition(":")
    if not separator:
        raise ValueError("missing ':' in line %r" % text)
    try:
        number = int(label.strip())
    except ValueError:
        raise ValueError("bad page number %r" % label.strip())
    return number, rest.split()


def parse_pages(lines):
    pages = []
    for line in lines:
        text = line.strip()
        if text:
            pages.append(parse_page(text))
    return pages


def wrap_numbers(numbers, width):
    """Split page numbers into comma separated lines no longer than width."""
    remaining = [str(number) for number in numbers]
    chunks = []
    while remaining:
        chunk = remaining.pop(0)
        while remaining and len(chunk) + 2 + len(remaining[0]) <= width:
            chunk += ", " + remaining.pop(0)
        chunks.append(chunk)
    return chunks


def format_index(entries, label_width=16, width=40):
