DAYS = ("Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday")


def shift_duration(start, end):
    """Hours between two military-time hours, allowing a shift to cross midnight."""
    for label, hour in (("start", start), ("end", end)):
        if not 0 <= hour <= 24:
            raise ValueError(f"{label} hour {hour} is outside 0..24")
    if end < start:
        end += 24
    return end - start


def parse_shift_line(line):
    """Turn 'Name, Day, start, end' into a shift tuple."""
    parts = [piece.strip() for piece in line.split(",")]
    if len(parts) != 4:
        raise ValueError(f"expected 4 fields, found {len(parts)}")
    name, day, start, end = parts
    day = day.capitalize()
    if day not in DAYS:
        raise ValueError(f"unknown day of week {day!r}")
    return (name, day, int(start), int(end))


def parse_roster(text):
    """Read shift records from text, returning the shifts and any rejected lines."""
    shifts = []
    errors = []
    for number, raw in enumerate(text.splitlines(), start=1):
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        try:
            shifts.append(parse_shift_line(line))
        except ValueError as exc:
            errors.append(f"line {number}: {exc}")
    return shifts, errors


def roster(shifts):
    """Total the hours each worker was on shift during the week."""
    totals = {}
    for name, day, start, end in shifts:
        totals[name] = totals.get(name, 0) + shift_duration(start, end)
    return sorted(totals.items(), key=lambda item: (-item[1], item[0]))


def format_report(totals):
    """Lay the weekly totals out as an aligned text table."""
    width = max((len(name) for name, _ in totals), default=4)
    lines = []
    for name, hours in totals:
        if hours > 40:
            note = "  (overtime)"
        else:
            note = ""
        lines.append(f"{name:<{width}}  {hours:>3} h{note}")
    return "\n".join(lines)


def main():
    text = """
    # worker, day, start, end
    Ada, Monday, 22, 6
    Ada, Tuesday, 22, 6
    Ada, Wednesday, 22, 6
    Ada, Thursday, 22, 6
    Ada, Friday, 22, 6
    Grace, Monday, 8, 17
    Grace, Tuesday, 8, 17
    Grace, Funday, 8, 17
    Linus, Saturday, 6, 18
    Linus, Sunday, 6, 18
    Edsger, Monday, 9, 18
    """
    shifts, errors = parse_roster(text)
    for problem in errors:
        print("rejected", problem)
    totals = roster(shifts)
    report = format_report(totals)
    print(report)
    with open("roster_report.txt", "w") as handle:
        handle.write(report + "\n")


if __name__ == "__main__":
    main()

