import sys

ALLERGENS = frozenset({"peanuts", "dairy", "shellfish"})

DEFAULT_MENU = """\
# dish: ingredient, ingredient, ...
Garden Salad: lettuce, tomato, olive oil
Peanut Noodles: wheat noodles, peanut butter, soy sauce
Shrimp Scampi: shellfish, garlic, butter (dairy)
Steamed Rice: rice, water
Cheese Pizza: flour, tomato, dairy
Grilled Chicken: chicken, rosemary, salt
"""


def normalize(ingredient):
    text = ingredient.strip().lower()
    while "(" in text and ")" in text:
        start = text.index("(")
        end = text.index(")", start)
        text = text[:start] + text[end + 1:]
    return " ".join(text.split())


def is_unsafe(ingredient):
    name = normalize(ingredient)
    if name in ALLERGENS:
        return True
    return "peanut" in name


def filter(menu):
    safe = []
    for dish, ingredients in menu:
        triggers = [normalize(item) for item in ingredients if is_unsafe(item)]
        if not triggers:
            safe.append(dish)
    return sorted(safe)


def parse_menu(text):
    menu = []
    for lineno, line in enumerate(text.splitlines(), start=1):
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        try:
            dish, raw = stripped.split(":", 1)
        except ValueError:
            raise ValueError("line %d: expected 'dish: ingredients'" % lineno)
        ingredients = [part.strip() for part in raw.split(",") if part.strip()]
        menu.append((dish.strip(), ingredients))
    return menu


def save_report(path, menu):
    with open(path, "w") as out:
        out.write("Allergen report for: %s\n" % ", ".join(sorted(ALLERGENS)))
        for dish, ingredients in menu:
            triggers = [normalize(item) for item in ingredients if is_unsafe(item)]
            if triggers:
                out.write("UNSAFE %s -> %s\n" % (dish, "; ".join(triggers)))
            else:
                out.write("SAFE   %s\n" % dish)


def main(argv):
    if len(argv) > 1:
        with open(argv[1]) as handle:
            text = handle.read()
    else:
        text = DEFAULT_MENU
    menu = parse_menu(text)
    for name in filter(menu):
        print(name)
    if len(argv) > 2:
        save_report(argv[2], menu)
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

