import sys

DEFAULT_DATA = """
# day: hourly temperatures (degrees Celsius)
1: 12, 14, 17, 21, 24, 23, 19, 15
2: 9, 11, 13, 16, 18, 17, 14, 10
3: 15, 18, 22, 26, 29, 28, 24, 20
4: 4, 3, 5, 8, 11, 10, 7, 5
"""


def parse_reports(lines):
  """Turn text lines of the form 'day: t1, t2, ...' into reading tuples."""
  readings = []
  for raw in lines:
    line = raw.strip()
    if not line or line.startswith("#"):
      continue
    if ":" not in line:
      raise ValueError("missing ':' in report %r" % line)
    head, tail = line.split(":", 1)
    try:
      day = int(head)
      temps = [int(part) for part in tail.split(",")]
    except ValueError:
      raise ValueError("malformed report %r" % line)
    readings.append((day, temps))
  return readings


def analyze(readings):
  """Return (hottest day, coldest day, daily averages sorted by day)."""
  if not readings:
    raise ValueError("no readings supplied")
  hottest = coldest = None
  highest = lowest = None
  averages = []
  for day, temps in sorted(readings):
    if not temps:
      raise ValueError("day %d has no temperatures" % day)
    day_max = max(temps)
    day_min = min(temps)
    averages.append(sum(temps) / len(temps))
    if highest is None or day_max > highest:
      highest = day_max
      hottest = day
    if lowest is None or day_min < lowest:
      lowest = day_min
      coldest = day
  return hottest, coldest, averages


def format_report(readings, hottest, coldest, averages):
  temps_by_day = dict(readings)
  days = sorted(temps_by_day)
  lines = []
  for day, average in zip(days, averages):
    labels = []
    if day == hottest:
      labels.append("hottest")
    if day == coldest:
      labels.append("coldest")
    if labels:
      tag = " (%s)" % ", ".join(labels)
    else:
      tag = ""
    lines.append("Day %d: average %.2f%s" % (day, average, tag))
    temps = temps_by_day[day]
    index = 0
    while index < len(temps):
      chunk = temps[index:index + 6]
      lines.append("    " + " ".join("%4d" % t for t in chunk))
      index += 6
  lines.append("Hottest day: %d   Coldest day: %d" % (hottest, coldest))
  return "\n".join(lines)


def main(argv):
  if len(argv) > 1:
    with open(argv[1]) as handle:
      lines = handle.readlines()
  else:
    lines = DEFAULT_DATA.splitlines()
  try:
    readings = parse_reports(lines)
    hottest, coldest, averages = analyze(readings)
  except (OSError, ValueError) as exc:
    print("error: %s" % exc, file=sys.stderr)
    return 1
  print(format_report(readings, hottest, coldest, averages))
  return 0


if __name__ == "__main__":
  sys.exit(main(sys.argv))

