import sys

CONDITIONS = ("excellent", "good", "poor")


def parse_listing(line):
    """Turn one comma separated text record into a property tuple."""
    fields = [field.strip() for field in line.split(",")]
    if len(fields) != 4:
        raise ValueError("expected 4 fields, got %d" % len(fields))
    address, raw_price, raw_bedrooms, raw_condition = fields
    try:
        price = int(raw_price)
        bedrooms = int(raw_bedrooms)
    except ValueError:
        raise ValueError("price and bedrooms must be whole numbers")
    condition = raw_condition.lower()
    if condition not in CONDITIONS:
        raise ValueError("unknown condition %r" % raw_condition)
    return (address, price, bedrooms, condition)


def load_listings(stream):
    """Read listings from a text stream, reporting unusable records."""
    listings = []
    for number, line in enumerate(stream, 1):
        text = line.strip()
        if not text:
            continue
        try:
            listings.append(parse_listing(text))
        except ValueError as err:
            print("line %d skipped: %s" % (number, err), file=sys.stderr)
    return listings


def score_listings(properties):
    """Score the acceptable properties, best deal first."""
    scored = []
    for address, price, bedrooms, condition in properties:
        if condition == "poor":
            continue
        score = bedrooms * 50 - price
        if condition == "excellent":
            score += 20
        if score < 0:
            continue
        scored.append((address, score))
    scored.sort(key=lambda pair: (-pair[1], pair[0]))
    return scored


def appraise(properties):
    """Return the addresses of the best deals, highest score first."""
    return [address for address, _score in score_listings(properties)]


def format_report(deals, scores):
    """Render a ranked table, giving equally scored addresses one rank."""
    if not deals:
        return "No properties qualify as deals."
    lines = ["Rank  Score  Address"]
    index = 0
    rank = 1
    while index < len(deals):
        group = index
        while group < len(deals) and scores[deals[group]] == scores[deals[index]]:
            group += 1
        for address in deals[index:group]:
            lines.append("%4d  %5d  %s" % (rank, scores[address], address))
        rank += group - index
        index = group
    return "\n".join(lines)


def main(argv):
    if len(argv) > 1:
        with open(argv[1], encoding="utf-8") as handle:
            listings = load_listings(handle)
    else:
        listings = load_listings(sys.stdin)
    scores = dict(score_listings(listings))
    print(format_report(appraise(listings), scores))


if __name__ == "__main__":
    main(sys.argv)

