import sys

FARES = {"city": 2.0, "suburb": 3.0}
DAILY_CAP = 8.0


def fare(zone):
    if zone not in FARES:
        raise ValueError(f"unknown zone {zone!r}")
    return FARES[zone]


def cap(trips):
    charges = []
    total = 0.0
    for hour, zone in trips:
        cost = fare(zone)
        if total >= DAILY_CAP:
            charged = 0.0
        elif total + cost > DAILY_CAP:
            charged = DAILY_CAP - total
        else:
            charged = cost
        total += charged
        charges.append(charged)
    return charges


def parse_trips(lines):
    trips = []
    for lineno, line in enumerate(lines, start=1):
        text = line.strip()
        if not text or text.startswith("#"):
            continue
        parts = text.split()
        if len(parts) != 2:
            raise ValueError(f"line {lineno}: expected 'hour zone', got {text!r}")
        try:
            hour = float(parts[0])
        except ValueError:
            raise ValueError(f"line {lineno}: bad boarding hour {parts[0]!r}")
        if not 0.0 <= hour < 24.0:
            raise ValueError(f"line {lineno}: hour {hour} outside a single day")
        zone = parts[1].lower()
        if zone not in FARES:
            raise ValueError(f"line {lineno}: unknown zone {parts[1]!r}")
        trips.append((hour, zone))
    return trips


def format_report(trips, charges):
    report = []
    total = 0.0
    for (hour, zone), charged in zip(trips, charges):
        total += charged
        if charged < fare(zone):
            note = "capped"
        else:
            note = "full fare"
        report.append(f"{hour:05.2f}  {zone:<6}  {charged:5.2f}  {note}")
    report.append(f"total charged: {total:.2f}")
    if total >= DAILY_CAP:
        report.append("daily cap reached")
    return "\n".join(report)


def main():
    args = sys.argv[1:]
    if args:
        with open(args[0], encoding="utf-8") as handle:
            lines = handle.readlines()
    else:
        lines = sys.stdin.readlines()
    try:
        trips = parse_trips(lines)
    except ValueError as err:
        print(f"error: {err}", file=sys.stderr)
        return 1
    print(format_report(trips, cap(trips)))
    return 0


if __name__ == "__main__":
    sys.exit(main())

