def rank(results):
    tally = {}
    for white, black, outcome in results:
        for name in (white, black):
            if name not in tally:
                tally[name] = 0
        if outcome == "white":
            tally[white] += 3
        elif outcome == "black":
            tally[black] += 3
        elif outcome == "draw":
            tally[white] += 1
            tally[black] += 1
        else:
            raise ValueError("unknown outcome: {!r}".format(outcome))
    standings = [(name, points) for name, points in tally.items()]
    standings.sort(key=lambda entry: (-entry[1], entry[0]))
    return standings


def parse_results(stream):
    results = []
    while True:
        line = stream.readline()
        if not line:
            break
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        fields = [field.strip() for field in line.split(",")]
        if len(fields) != 3:
            raise ValueError("expected 'white,black,outcome' but got: " + line)
        results.append(tuple(fields))
    return results


