import sys


def parse_turn(text, lineno=None):
    """Turn one line of text such as '3, 4 5' into a tuple of three dice."""
    where = "line %d: " % lineno if lineno else ""
    parts = text.replace(",", " ").split()
    try:
        dice = tuple(int(part) for part in parts)
    except ValueError:
        raise ValueError("%snon-integer die result: %r" % (where, text.strip()))
    if len(dice) != 3:
        raise ValueError("%sexpected 3 dice, got %d" % (where, len(dice)))
    for die in dice:
        if not 1 <= die <= 6:
            raise ValueError("%sdie outside 1..6: %d" % (where, die))
    return dice


def parse_turns(text):
    turns = []
    for lineno, line in enumerate(text.splitlines(), start=1):
        stripped = line.strip()
        if stripped and not stripped.startswith("#"):
            turns.append(parse_turn(stripped, lineno))
    return turns


def score_turn(dice):
    if any(die == 1 for die in dice):
        return 0
    total = sum(dice)
    if len(set(dice)) == 1:
        total *= 2
    return total


def running_scores(turns):
    """Yield (dice, turn score, capped total) until the cap ends the game."""
    total = 0
    for turn in turns:
        score = score_turn(turn)
        total += score
        if total > 100:
            yield turn, score, 100
            return
        yield turn, score, total


def roll(turns):
    total = 0
    for entry in running_scores(turns):
        total = entry[2]
    return total


def format_report(turns):
    lines = []
    for dice, score, total in running_scores(turns):
        if score == 0:
            label = "fumble"
        elif len(set(dice)) == 1:
            label = "critical hit"
        else:
            label = "normal"
        lines.append("%-10s %-13s %3d -> %3d" % (" ".join(map(str, dice)), label, score, total))
    lines.append("final score: %d" % roll(turns))
    return "\n".join(lines)


def play_interactive(stream):
    turns = []
    total = 0
    while total < 100:
        line = stream.readline()
        if not line:
            break
        try:
            turns.append(parse_turn(line))
        except ValueError as exc:
            print("ignored: %s" % exc)
            continue
        total = roll(turns)
    return turns


def main(argv):
    if len(argv) > 1:
        with open(argv[1]) as handle:
            text = handle.read()
        try:
            turns = parse_turns(text)
        except ValueError as exc:
            print("bad dice log: %s" % exc)
            return 1
    else:
        turns = play_interactive(sys.stdin)
    print(format_report(turns))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

