def parse_record(record):
    """Normalise one raw file record into (name, size, age)."""
    name, size, age = record
    if not isinstance(name, str) or not name.strip():
        raise ValueError("file name must be a non-empty string")
    size = float(size)
    age = int(age)
    if size < 0:
        raise ValueError("file size cannot be negative for %r" % name)
    if age < 0:
        raise ValueError("last-access age cannot be negative for %r" % name)
    return name.strip(), size, age


def candidates(files):
    """Keep only files untouched for more than thirty days."""
    selected = []
    for record in files:
        name, size, age = parse_record(record)
        if age > 30:
            selected.append((name, size, age))
    return selected


def cleanup(files, target):
    pool = candidates(files)
    pool.sort(key=lambda item: (item[1], item[2]), reverse=True)
    freed = 0.0
    chosen = []
    for name, size, _age in pool:
        if freed >= target:
            break
        chosen.append(name)
        freed += size
    return chosen


def load_records(path):
    """Read 'name,size,days' lines, ignoring blanks and comments."""
    records = []
    with open(path) as handle:
        for line in handle:
            line = line.strip()
            if not line or line.startswith("#"):
                continue
            parts = line.split(",")
            if len(parts) != 3:
                raise ValueError("malformed line: %r" % line)
            records.append((parts[0], parts[1], parts[2]))
    return records


def report(files, target):
    """Build a human-readable summary of a cleanup plan."""
