import sys

DAYS_PER_WEEK = 7
WEEKDAYS = 5
DAILY_REGULAR_CAP = 8.0


def validate_timesheet(name, hours):
    if not name.strip():
        raise ValueError("employee name must not be empty")
    if len(hours) != DAYS_PER_WEEK:
        raise ValueError(f"{name}: expected {DAYS_PER_WEEK} daily values, got {len(hours)}")
    for index, worked in enumerate(hours, start=1):
        if worked < 0:
            raise ValueError(f"{name}: negative hours on day {index}")
        if worked > 24:
            raise ValueError(f"{name}: more than 24 hours on day {index}")


def classify_day(index, worked):
    if index >= WEEKDAYS:
        return 0.0, 0.0, worked
    regular = min(worked, DAILY_REGULAR_CAP)
    return regular, worked - regular, 0.0


def employee_pay(hours, rate):
    total = 0.0
    for index, worked in enumerate(hours):
        regular, overtime, weekend = classify_day(index, worked)
        total += regular * rate + overtime * rate * 1.5 + weekend * rate * 2
    return round(total, 2)


def payroll(timesheets, rate):
    if rate < 0:
        raise ValueError("hourly rate must not be negative")
    results = []
    for name, hours in timesheets:
        validate_timesheet(name, hours)
        results.append((name.strip(), employee_pay(hours, rate)))
    results.sort(key=lambda entry: entry[0])
    return results


def parse_line(text):
    name, separator, rest = text.partition(":")
    if not separator:
        raise ValueError(f"missing ':' in timesheet line: {text!r}")
    hours = [float(token) for token in rest.replace(",", " ").split()]
    return name, hours


def read_timesheets(lines):
    sheets = []
    for line in lines:
        text = line.strip()
        if text and not text.startswith("#"):
            sheets.append(parse_line(text))
    return sheets


def format_report(results):
    width = max((len(name) for name, _ in results), default=5)
    rows = []
    for name, pay in results:
        rows.append(f"{name:<{width}}  {pay:>10.2f}")
    rows.append(f"{'TOTAL':<{width}}  {sum(pay for _, pay in results):>10.2f}")
    return "\n".join(rows)


def main(argv):
    args = argv[1:]
    if not args:
        print("usage: payroll RATE [timesheet-file ...]", file=sys.stderr)
        return 2
    try:
        rate = float(args[0])
    except ValueError:
        print(f"invalid hourly rate: {args[0]!r}", file=sys.stderr)
        return 2
    lines = []
    if len(args) > 1:
        for path in args[1:]:
            with open(path, encoding="utf-8") as handle:
                lines.extend(handle.readlines())
    else:
        while True:
            line = sys.stdin.readline()
            if not line:
                break
            lines.append(line)
    try:
        results = payroll(read_timesheets(lines), rate)
    except ValueError as exc:
        print(f"payroll error: {exc}", file=sys.stderr)
        return 1
    print(format_report(results))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

