import io
import sys

FIELD_NAMES = ("name", "health", "attack", "defense", "speed")


def validate(character):
    """Check that a combatant tuple has the five expected, sane fields."""
    if len(character) != len(FIELD_NAMES):
        raise ValueError("a combatant needs exactly %d fields" % len(FIELD_NAMES))
    name, health, attack, defense, speed = character
    if not isinstance(name, str) or not name.strip():
        raise ValueError("combatant name must be a non-empty string")
    for label, value in zip(FIELD_NAMES[1:], (health, attack, defense, speed)):
        if not isinstance(value, int) or isinstance(value, bool):
            raise ValueError("%s of %s must be an integer" % (label, name))
        if value < 0:
            raise ValueError("%s of %s must not be negative" % (label, name))
    if health == 0 or attack == 0:
        raise ValueError("%s needs positive health and attack" % name)


def compute_damage(attacker, defender):
    """Damage is attack minus defense, but never less than one point."""
    raw = attacker[2] - defender[3]
    if raw < 1:
        return 1
    return raw


def simulate(hero, monster):
    validate(hero)
    validate(monster)
    if monster[4] > hero[4]:
        attacker, defender = list(monster), list(hero)
    else:
        attacker, defender = list(hero), list(monster)
    while True:
        defender[1] -= compute_damage(attacker, defender)
        if defender[1] <= 0:
            return (attacker[0], attacker[1])
        attacker, defender = defender, attacker


def parse_combatant(spec):
    """Turn 'Name,hp,atk,def,spd' into a combatant tuple."""
    parts = [piece.strip() for piece in spec.split(",")]
    if len(parts) != len(FIELD_NAMES):
        raise ValueError("expected 5 comma-separated fields in %r" % spec)
    stats = []
    for label, text in zip(FIELD_NAMES[1:], parts[1:]):
        try:
            stats.append(int(text))
        except ValueError:
            raise ValueError("%s must be a whole number, got %r" % (label, text))
    return (parts[0], stats[0], stats[1], stats[2], stats[3])


def format_report(hero, monster, winner):
    with io.StringIO() as buf:
        buf.write("=== Battle report ===\n")
        for fighter in (hero, monster):
            buf.write("%-12s hp=%3d atk=%3d def=%3d spd=%3d\n" % fighter)
        buf.write("Winner: %s with %d hp remaining\n" % winner)
        return buf.getvalue()


def main(argv):
    specs = argv[1:]
    if len(specs) != 2:
        specs = ["Hero,30,8,3,6", "Goblin,12,4,1,4"]
    try:
        hero = parse_combatant(specs[0])
        monster = parse_combatant(specs[1])
        winner = simulate(hero, monster)
    except ValueError as error:
        print("error: %s" % error, file=sys.stderr)
        return 1
    print(format_report(hero, monster, winner), end="")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

