def parse_entry(line):
    """Turn a single 'minutes,hints' record into a performance tuple."""
    fields = line.split(",")
    if len(fields) != 2:
        raise ValueError(f"expected 'minutes,hints' but got {line!r}")
    try:
        base = float(fields[0])
        hints = int(fields[1])
    except ValueError:
        raise ValueError(f"non-numeric field in {line!r}")
    if base < 0 or hints < 0:
        raise ValueError(f"negative value in {line!r}")
    return base, hints


def parse_log(text):
    """Read a puzzle log, ignoring blank lines and '#' comments."""
    puzzles = []
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        puzzles.append(parse_entry(line))
    return puzzles


def effective_time(base, hints):
    return base + HINT_PENALTY * hints


def evaluate(puzzles, limit):
    total = 0
    for base, hints in puzzles:
        total += effective_time(base, hints)
    return total <= limit, total


def hints_to_drop(puzzles, limit):
    """How many hints the team would have had to skip to escape."""
    escaped, total = evaluate(puzzles, limit)
    if escaped:
        return 0
    remaining = sum(hints for _, hints in puzzles)
    dropped = 0
    while total > limit and remaining > 0:
        total -= HINT_PENALTY
        remaining -= 1
        dropped += 1
    return dropped


def format_report(puzzles, limit):
    lines = []
    for index, (base, hints) in enumerate(puzzles, start=1):
        spent = effective_time(base, hints)
        lines.append(f"Puzzle {index}: {base:g} min + {hints} hint(s) -> {spent:g} min")
    escaped, total = evaluate(puzzles, limit)
    lines.append(f"Total: {total:g} min (limit {limit:g} min)")
    if escaped:
        lines.append("Result: ESCAPED")
    else:
        needed = hints_to_drop(puzzles, limit)
        if needed:
            lines.append(f"Result: TRAPPED - {needed} fewer hint(s) would have sufficed")
        else:
            lines.append("Result: TRAPPED - too slow even with no hints at all")
