def parse_quantity(text):
    """Convert a textual gram amount into a non-negative integer."""
    try:
        grams = int(text.strip())
    except ValueError:
        raise ValueError("quantity is not a whole number: {!r}".format(text))
    if grams < 0:
        raise ValueError("quantity may not be negative: {!r}".format(text))
    return grams


def parse_stock(lines):
    """Turn lines like 'flour: 1000' into (ingredient, grams) tuples."""
    stock = []
    for line in lines:
        parts = line.split(":", 1)
        if len(parts) != 2:
            raise ValueError("malformed stock line: {!r}".format(line))
        stock.append((parts[0].strip(), parse_quantity(parts[1])))
    return stock


def parse_order(line):
    """Turn 'Ann: flour=200, sugar=50' into ('Ann', [('flour', 200), ...])."""
    parts = line.split(":", 1)
    if len(parts) != 2:
        raise ValueError("malformed order line: {!r}".format(line))
    needs = []
    for chunk in parts[1].split(","):
        item = chunk.split("=", 1)
        if len(item) != 2:
            raise ValueError("malformed requirement: {!r}".format(chunk))
        needs.append((item[0].strip(), parse_quantity(item[1])))
    return parts[0].strip(), needs


def build_inventory(stock):
    """Summarize the stock list into a mutable ingredient -> grams mapping."""
    inventory = {}
    for ingredient, grams in stock:
        inventory[ingredient] = inventory.get(ingredient, 0) + grams
    return inventory


def fulfill(stock, orders):
    inventory = build_inventory(stock)
    fulfilled = []
    for customer, needs in orders:
        required = {}
        for ingredient, grams in needs:
            required[ingredient] = required.get(ingredient, 0) + grams
        possible = True
        for ingredient, grams in required.items():
            if inventory.get(ingredient, 0) < grams:
                possible = False
        if possible:
            for ingredient, grams in required.items():
                inventory[ingredient] -= grams
            fulfilled.append(customer)
    return fulfilled


def format_report(stock, orders, fulfilled):
    """Describe each order's outcome plus the leftover inventory."""
    served = set(fulfilled)
    lines = []
    for customer, needs in orders:
        recipe = ", ".join("{} {}g".format(name, grams) for name, grams in needs)
        if customer in served:
            lines.append("fulfilled {}: {}".format(customer, recipe))
        else:
            lines.append("rejected  {}: {}".format(customer, recipe))
    remaining = build_inventory(stock)
    for customer, needs in orders:
        if customer in served:
            for ingredient, grams in needs:
                remaining[ingredient] -= grams
    for ingredient in sorted(remaining):
        lines.append("left {}: {}g".format(ingredient, remaining[ingredient]))
    return lines


def main():
    stock_lines = ["flour: 1000", "sugar: 400", "butter: 250", "flour: 200"]
    order_lines = [
        "Ann: flour=500, sugar=200",
        "Bob: flour=800, butter=100",
        "Cleo: flour=600, sugar=150, butter=200",
        "Dan: sugar=100",
    ]
    stock = parse_stock(stock_lines)
    orders = [parse_order(line) for line in order_lines]
    fulfilled = fulfill(stock, orders)
