def parse_lineup(text):
    """Turn a block of "name, minutes" lines into a list of band tuples."""
    bands = []
    for line in text.strip().splitlines():
        entry = line.strip()
        if not entry:
            continue
        name, _, minutes = entry.rpartition(",")
        bands.append((name.strip(), int(minutes)))
    return bands


def assign(bands, stages):
    """Place each band on the first stage with enough time left."""
    remaining = list(stages)
    schedule = [[] for _ in stages]
    for name, length in bands:
        index = 0
        while index < len(remaining):
            if remaining[index] >= length:
                remaining[index] -= length
                schedule[index].append(name)
                break
            index += 1
    return schedule


def unscheduled(bands, schedule):
    """Names of the bands that no stage could host."""
    placed = set()
    for acts in schedule:
        for name in acts:
            placed.add(name)
    return [name for name, _ in bands if name not in placed]


