    lengths = dict(bands)
    lines = []
    for number, (capacity, acts) in enumerate(zip(stages, schedule), start=1):
        used = sum(lengths[name] for name in acts)
        lines.append(f"Stage {number}: {capacity} min total, {capacity - used} min free")
        if acts:
            for name in acts:
                lines.append(f"    {name} ({lengths[name]} min)")
        else:
            lines.append("    (stage empty)")
    return "\n".join(lines)


