def parse_answers(text):
    """Turn "5:9, 3:8" into [(5, 9), (3, 8)]."""
    answers = []
    for token in text.split(","):
        weight_text, _, score_text = token.partition(":")
        answers.append((int(weight_text.strip()), int(score_text.strip())))
    return answers


def validate_answers(answers):
    if not answers:
        raise ValueError("no answers recorded")
    for position, (weight, awarded) in enumerate(answers, start=1):
        if weight <= 0:
            raise ValueError(f"question {position} has a non-positive weight {weight}")
        if awarded < 0 or awarded > 10:
            raise ValueError(f"question {position} has an out-of-range score {awarded}")


def weighted_percentage(answers):
    maximum = 0
    achieved = 0
    for weight, awarded in answers:
        maximum += weight * 10
        achieved += weight * awarded
    return achieved / maximum * 100


def score(answers, threshold):
    for _weight, awarded in answers:
        if awarded < 3:
            return False
    return weighted_percentage(answers) >= threshold


def format_percentage(value):
    text = f"{value:.2f}"
    while text.endswith("0"):
        text = text[:-1]
    if text.endswith("."):
        text = text[:-1]
    return text


def build_report(results, threshold):
    width = max(len(name) for name, _percentage, _passed in results)
    lines = [f"Interview results (threshold {format_percentage(threshold)}%)"]
    for name, percentage, passed in results:
        if passed:
            verdict = "PASS"
        else:
            verdict = "FAIL"
        lines.append(f"{name:<{width}}  {format_percentage(percentage):>6}%  {verdict}")
    return lines


