DAILY_GOAL = 10000
DAYS_PER_WEEK = 7

RAW_DATA = """
# team name: seven daily step counts
Trail Blazers: 11200, 9800, 12400, 10050, 8700, 13100, 9900
Desk Warriors: 6200, 7100, 5400, 8800, 7600, 4300, 6900
Stair Masters: 10400, 10100, 10600, 10200, 10800, 9500, 10300
Night Owls: 9000, 10200, 11000, 9700, 12200, 10100
Lunch Loopers: 12000, 12500, 9200, 8800, 13000, 7000, 8900
"""


def validate_steps(name, steps):
    if len(steps) != DAYS_PER_WEEK:
        raise ValueError(f"{name}: {len(steps)} daily entries, expected {DAYS_PER_WEEK}")
    for value in steps:
        if value < 0:
            raise ValueError(f"{name}: negative step count {value}")
    return steps


def consistency(steps):
    achieved = 0
    for value in steps:
        if value >= DAILY_GOAL:
            achieved += 1
    return achieved


def rank(participants, target):
    qualified = []
    for name, steps in participants:
        total = sum(steps)
        if total >= target:
            qualified.append((name, total, consistency(steps)))
    qualified.sort(key=lambda row: (-row[1], -row[2]))
    return qualified


def parse_participants(text):
    records = []
    problems = []
    for raw_line in text.splitlines():
        line = raw_line.strip()
        if not line or line.startswith("#"):
            continue
        name, _, tail = line.partition(":")
        try:
            steps = [int(token) for token in tail.split(",")]
            validate_steps(name.strip(), steps)
        except ValueError as exc:
            problems.append(str(exc))
        else:
            records.append((name.strip(), steps))
    return records, problems


def assign_positions(rows):
    placed = []
    index = 0
    while index < len(rows):
        end = index
        while end < len(rows) and rows[end][1:] == rows[index][1:]:
            end += 1
        for row in rows[index:end]:
            placed.append((index + 1, row))
        index = end
    return placed


def format_report(rows, target):
    lines = [f"Weekly team target: {target} steps"]
    if not rows:
