    if path is None:
        text = sys.stdin.read()
    else:
        with open(path, encoding="utf-8") as handle:
            text = handle.read()
    return text.splitlines()


def parse_menu(lines):
    """Parse a budget line followed by 'name, cost, score' dish lines."""
    index = 0
    while index < len(lines) and not lines[index].strip():
        index += 1
    if index >= len(lines):
        raise ValueError("menu is empty: a budget line is required")
    try:
        budget = float(lines[index].strip())
    except ValueError:
        raise ValueError(f"invalid budget line: {lines[index]!r}")
    dishes = []
    for raw in lines[index + 1:]:
        row = raw.strip()
        if not row:
            continue
        parts = [field.strip() for field in row.split(",")]
        if len(parts) != 3:
            raise ValueError(f"expected 'name, cost, score' but got {row!r}")
        try:
            cost = float(parts[1])
            score = float(parts[2])
        except ValueError:
            raise ValueError(f"cost and score must be numbers in {row!r}")
        dishes.append((parts[0], cost, score))
    return dishes, budget


def select(dishes, budget):
    """Greedily pick the most popular affordable dishes within the budget."""
    if budget < 0:
        raise ValueError("budget must not be negative")
    ranked = sorted(dishes, key=lambda dish: (-dish[2], dish[1]))
    remaining = budget
    chosen = []
    taken = set()
    for name, cost, _score in ranked:
        if name in taken:
            continue
        if cost <= remaining:
            chosen.append(name)
            taken.add(name)
            remaining -= cost
    return chosen


