    rows = []
    total = 0.0
    for name in chosen:
        total += costs[name]
        rows.append(f"  {name:<20}{costs[name]:>9.2f}")
    rows.append(f"  {'TOTAL':<20}{total:>9.2f}")
    return "\n".join(rows)


