def count_free_uppercase(message):
    """Count how many times the word FREE appears in uppercase."""
    count = 0
    for index in range(len(message) - 3):
        if message[index:index + 4] == "FREE":
            count += 1
    return count


def uppercase_ratio(message):
    """Fraction of non-space characters that are uppercase."""
    considered = 0
    uppercase = 0
    for char in message:
        if char == " ":
            continue
        considered += 1
        if char.isupper():
            uppercase += 1
    if considered == 0:
        return 0.0
    return uppercase / considered


def has_exclamation_run(message, length=3):
    """True if the message holds `length` or more exclamation marks in a row."""
    run = 0
    for char in message:
        if char == "!":
            run += 1
            if run >= length:
                return True
        else:
            run = 0
    return False


def classify(message):
    """Return "spam" or "valid" for a single message."""
    if len(message) < 10:
        return "spam"
    if count_free_uppercase(message) > 2:
        return "spam"
    if uppercase_ratio(message) > 0.5:
        return "spam"
    if has_exclamation_run(message):
        return "spam"
    return "valid"


def filter(messages):
    """Classify every message in `messages` as "spam" or "valid"."""
    return [classify(message) for message in messages]


def summarize(labels):
    """Count how many labels fall into each category."""
    totals = {"spam": 0, "valid": 0}
    for label in labels:
        totals[label] += 1
    return totals


def format_report(messages, labels):
    """Build one display line per message, truncating long texts."""
    lines = []
    for message, label in zip(messages, labels):
        shown = message
        if len(shown) > 30:
            shown = shown[:27] + "..."
        lines.append("{:>5}  {}".format(label, shown))
    return lines


def main():
    messages = [
        "Hi Bob",
        "Lunch at noon in the usual place?",
        "Great news!!! Call me back",
        "FREE money FREE prizes FREE trip for you",
        "PLEASE ANSWER ME RIGHT NOW",
    ]
    labels = filter(messages)
    for line in format_report(messages, labels):
        print(line)
    totals = summarize(labels)
    for label in ("spam", "valid"):
        print("{}: {}".format(label, totals[label]))


if __name__ == "__main__":
    main()

