def build_price_table(prices):
    """Turn a list of (material, cost) tuples into a lookup table."""
    table = {}
    for material, value in prices:
        table[material] = int(value)
    return table


def sum_materials(materials, table):
    """Total the cost of the materials, or None if one has no known price."""
    total = 0
    for material in materials:
        try:
            total += table[material]
        except KeyError:
            return None
    return total


def classify(total):
    if total < 15:
        return "budget"
    return "premium"


def cost(blueprints, prices):
    """Price every forgeable blueprint and label it budget or premium."""
    table = build_price_table(prices)
    results = []
    for name, materials in blueprints:
        total = sum_materials(materials, table)
        if total is None:
            continue
        results.append((name, total, classify(total)))
    return results


def format_report(results):
    if not results:
        return "no forgeable blueprints"
    width = max(len(name) for name, _, _ in results)
    lines = []
    for name, total, grade in results:
        lines.append(f"{name.ljust(width)}  {total:>3} gp  {grade}")
    return "\n".join(lines)


def summarize(results):
    tally = {"budget": 0, "premium": 0}
    gold = 0
    for _, total, grade in results:
        tally[grade] += 1
        gold += total
    return tally, gold


