import io


def parse_line(spec):
    """Turn a whitespace separated waiting line into a list of integer weights."""
    weights = []
    for token in spec.split():
        try:
            weights.append(int(token))
        except ValueError:
            raise ValueError(f"{token!r} is not a valid passenger weight") from None
    return weights


def load(passengers, capacity):
    """Group passengers, in order, into elevator trips limited by capacity."""
    if not isinstance(capacity, int) or capacity <= 0:
        raise ValueError("capacity must be a positive integer")
    for weight in passengers:
        if not isinstance(weight, int):
            raise TypeError(f"passenger weight {weight!r} is not an integer")
    trips = []
    current = []
    total = 0
    index = 0
    while index < len(passengers):
        weight = passengers[index]
        if weight > capacity:
            if current:
                trips.append(current)
            trips.append([f"{weight} exceeds capacity {capacity}"])
            current = []
            total = 0
        elif total + weight > capacity:
            trips.append(current)
            current = [weight]
            total = weight
        else:
            current.append(weight)
            total += weight
        index += 1
    if current:
        trips.append(current)
    return trips


def format_trips(trips, capacity):
    """Render the trip plan as a readable multi line report."""
    with io.StringIO() as report:
        for number, trip in enumerate(trips, start=1):
            carried = sum(entry for entry in trip if isinstance(entry, int))
            passengers = ", ".join(str(entry) for entry in trip)
            report.write(f"  Trip {number}: {passengers} -> {carried}/{capacity}\n")
        return report.getvalue()


def main():
    waiting_lines = [
        ("Lobby", 100, "50 80 60"),
        ("Garage", 200, "90 90 30 180 250 20"),
        ("Roof", 150, "70 heavy 40"),
    ]
    for name, capacity, spec in waiting_lines:
        print(f"{name} (capacity {capacity}):")
        try:
            weights = parse_line(spec)
        except ValueError as error:
            print(f"  cannot load this line: {error}")
            continue
        trips = load(weights, capacity)
        print(format_trips(trips, capacity), end="")
        overloaded = 0
        for trip in trips:
            for entry in trip:
                if isinstance(entry, str):
                    overloaded += 1
        if overloaded:
            print(f"  {overloaded} passenger(s) too heavy for this elevator")


if __name__ == "__main__":
    main()

