import math

MAX_VALID_SCORE = 120
PAR = 72
DEFAULT_AVERAGE = 100.0
FLIGHT_SIZE = 4

ROSTER_TEXT = """# Spring league, recent rounds

Alice: 90, 94
Bob: 71, 68, 74
Carla: 131, 145
Dan: 88, 122, 96, DNF
Erin: 101, 99, 104
Frank: 72
Gina: 110, 118, 125
"""


def average_score(scores):
    valid = []
    for score in scores:
        if score <= MAX_VALID_SCORE:
            valid.append(score)
    if not valid:
        return DEFAULT_AVERAGE
    return sum(valid) / len(valid)


def adjust(golfers):
    handicaps = []
    for name, scores in golfers:
        average = average_score(scores)
        if average <= PAR:
            handicap = 0
        else:
            handicap = math.floor(0.9 * (average - PAR))
        handicaps.append((name, handicap))
    return handicaps


def parse_roster(text):
    roster = []
    for line in text.splitlines():
        line = line.strip()
        if ":" not in line:
            continue
        name, raw_scores = line.split(":", 1)
        scores = []
        for token in raw_scores.split(","):
            try:
                scores.append(int(token.strip()))
            except ValueError:
                continue
        roster.append((name.strip(), scores))
    return roster


def flights(entries, size=FLIGHT_SIZE):
    groups = []
    index = 0
    while index < len(entries):
        groups.append(entries[index:index + size])
        index += size
    return groups


def format_report(handicaps):
    ranked = sorted(handicaps, key=lambda entry: (-entry[1], entry[0]))
    lines = []
    for number, group in enumerate(flights(ranked), start=1):
        lines.append("Flight {}".format(number))
        for name, handicap in group:
            lines.append("  {:<10}{:>4}".format(name, handicap))
    return "\n".join(lines)


