def parse_log_line(line):
    """Turn one "member, class" line into a (member, class) tuple."""
    parts = [part.strip() for part in line.split(",")]
    if len(parts) != 2:
        raise ValueError("expected exactly one comma separating member and class")
    member, class_name = parts
    if not member:
        raise ValueError("missing member name")
    if not class_name:
        raise ValueError("missing class name")
    return (member, class_name)


def parse_logs(text):
    """Parse a block of signup lines into logs plus a list of (lineno, error)."""
    logs = []
    problems = []
    for number, raw in enumerate(text.splitlines(), start=1):
        line = raw.strip()
        if not line:
            continue
        try:
            logs.append(parse_log_line(line))
        except ValueError as exc:
            problems.append((number, str(exc)))
    return logs, problems


def attend(logs, capacity):
    """Assign each signup to a class roster or its waitlist, ignoring duplicates."""
    if not isinstance(capacity, int) or isinstance(capacity, bool):
        raise TypeError("capacity must be an integer")
    if capacity < 0:
        raise ValueError("capacity cannot be negative")
    order = []
    enrolled = {}
    waitlisted = {}
    for member, class_name in logs:
        if class_name not in enrolled:
            order.append(class_name)
            enrolled[class_name] = []
            waitlisted[class_name] = []
        if member in enrolled[class_name] or member in waitlisted[class_name]:
            continue
        if len(enrolled[class_name]) < capacity:
            enrolled[class_name].append(member)
        else:
            waitlisted[class_name].append(member)
    return [(name, enrolled[name], waitlisted[name]) for name in order]


def format_report(result, capacity):
    """Render the attend() result as a readable multi-line report."""
    lines = []
    for class_name, roster, waiting in result:
        lines.append("{} ({}/{} seats used)".format(class_name, len(roster), capacity))
        if roster:
            for name in roster:
                lines.append("  enrolled: {}".format(name))
        else:
            lines.append("  enrolled: nobody")
        for position, name in enumerate(waiting, start=1):
            lines.append("  waitlist #{}: {}".format(position, name))
    return "\n".join(lines)


SIGNUP_TEXT = """
Alice, yoga
Bob, yoga
Alice, yoga
Cara, spin
Bob, spin
Dan, spin
Dan
Erin, yoga
"""


def main():
    capacity = 2
    logs, problems = parse_logs(SIGNUP_TEXT)
    for number, message in problems:
        print("skipped line {}: {}".format(number, message))
    result = attend(logs, capacity)
    print(format_report(result, capacity))


if __name__ == "__main__":
    main()

