PENALTY_MINUTES = 5


def _validate_actions(label, actions):
    """Ensure an action list is a list of non-empty strings."""
    if not isinstance(actions, list):
        raise TypeError("{0} must be a list of action strings".format(label))
    for action in actions:
        if not isinstance(action, str):
            raise TypeError("{0} contains a non-string action: {1!r}".format(label, action))
        if not action.strip():
            raise ValueError("{0} contains an empty action".format(label))


def clue(steps, sequence):
    """Score a team's attempt, returning (succeeded, completed_steps, penalty)."""
    _validate_actions("steps", steps)
    _validate_actions("sequence", sequence)
    completed = 0
    penalty = 0
    index = 0
    while index < len(sequence) and completed < len(steps):
        action = sequence[index]
        if action == steps[completed]:
            completed += 1
        else:
            penalty += PENALTY_MINUTES
        index += 1
    return (completed == len(steps), completed, penalty)


def parse_attempt(line):
    """Turn 'Team | step,step | action,action' into (team, steps, sequence)."""
    fields = [field.strip() for field in line.split("|")]
    if len(fields) != 3:
        raise ValueError("expected 'team | steps | sequence', got {0!r}".format(line))
    team = fields[0]
    steps = [action.strip() for action in fields[1].split(",")]
    sequence = [action.strip() for action in fields[2].split(",")]
    return (team, steps, sequence)


def format_result(team, required, result):
    """Build a one-line report for a scored attempt."""
    succeeded, completed, penalty = result
    if succeeded:
        outcome = "escaped"
    else:
        outcome = "trapped"
    return "{0:<8} {1:<8} {2}/{3} steps, {4} penalty minutes".format(
        team, outcome, completed, len(required), penalty)


def score_log(text):
    """Parse and score every attempt line, reporting malformed records."""
    scored = []
    for line in text.strip().splitlines():
        try:
            team, steps, sequence = parse_attempt(line)
        except ValueError as error:
            print("skipping record: {0}".format(error))
            continue
        scored.append((team, steps, clue(steps, sequence)))
    return scored


def main():
    log = """
    Red | pull,twist | push,pull,twist
    Blue | pull,twist,lift | pull,lift,twist,twist,lift
    Green | pull,twist | pull,twist,shove
    Broken | pull,twist
    """
    scored = score_log(log)
    scored.sort(key=lambda entry: (not entry[2][0], -entry[2][1], entry[2][2]))
    print("--- puzzle results ---")
    for team, steps, result in scored:
        print(format_result(team, steps, result))
    winners = [team for team, _, result in scored if result[0]]
    print("{0} of {1} teams solved the puzzle".format(len(winners), len(scored)))


if __name__ == "__main__":
    main()

