    except ValueError:
        raise ValueError("day count is not an integer: %r" % raw_days)
    flag = raw_receipt.lower()
    if flag in TRUE_WORDS:
        receipt = True
    elif flag in FALSE_WORDS:
        receipt = False
    else:
        raise ValueError("receipt flag not recognised: %r" % raw_receipt)
    condition = raw_condition.lower()
    if condition not in VALID_CONDITIONS:
        raise ValueError("condition must be new or used: %r" % raw_condition)
    return (name, days, receipt, condition)


def read_returns(stream):
    records = []
    while True:
        line = stream.readline()
        if not line:
            break
        stripped = line.strip()
        if stripped and not stripped.startswith("#"):
            records.append(parse_return(stripped))
    return records


