    lines = ["%-*s  %s" % (width, name, action) for name, action in results]
    lines.append("-" * (width + 10))
    for action in ("full", "credit", "rejected"):
        lines.append("%-*s  %d" % (width, action, counts[action]))
    return "\n".join(lines)


