import sys


def parse_stock(specs):
    """Turn "name:quantity" strings into (name, quantity) tuples."""
    stock = []
    for spec in specs:
        name, separator, quantity = spec.partition(":")
        if not separator:
            raise ValueError("missing ':' in stock spec %r" % spec)
        try:
            amount = int(quantity)
        except ValueError:
            raise ValueError("bad quantity %r for item %r" % (quantity, name))
        if amount < 0:
            raise ValueError("negative quantity %d for item %r" % (amount, name))
        stock.append((name.strip(), amount))
    return stock


def read_selections(path):
    """Read one selected item name per line, ignoring blank lines."""
    selections = []
    with open(path) as handle:
        while True:
            line = handle.readline()
            if not line:
                break
            item = line.strip()
            if item:
                selections.append(item)
    return selections


def vend(selections, stock):
    remaining = {}
    for name, quantity in stock:
        remaining[name] = remaining.get(name, 0) + quantity
    dispensed = []
    missed = []
    for item in selections:
        if remaining.get(item, 0) > 0:
            remaining[item] -= 1
            dispensed.append(item)
        else:
            missed.append(item)
    return dispensed, missed


def tally(items):
    counts = {}
    for item in items:
        counts[item] = counts.get(item, 0) + 1
    return counts


def format_report(dispensed, missed):
    lines = ["Dispensed: %d" % len(dispensed)]
    for name, count in sorted(tally(dispensed).items()):
        lines.append("  %s x%d" % (name, count))
    lines.append("Missed: %d" % len(missed))
    for name, count in sorted(tally(missed).items()):
        lines.append("  %s x%d" % (name, count))
    if missed:
        lines.append("Restock needed for: " + ", ".join(sorted(set(missed))))
    else:
        lines.append("All selections satisfied.")
    return lines


def main(argv):
    if len(argv) < 3:
        print("usage: %s SELECTIONS_FILE ITEM:QTY [ITEM:QTY ...]" % argv[0],
              file=sys.stderr)
        return 1
    try:
        stock = parse_stock(argv[2:])
        selections = read_selections(argv[1])
    except (OSError, ValueError) as exc:
        print("error: %s" % exc, file=sys.stderr)
        return 2
    dispensed, missed = vend(selections, stock)
    for line in format_report(dispensed, missed):
        print(line)
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

