import sys


def escape(text):
    """Replace the characters that may not appear literally in XML text."""
    result = text
    for char, entity in (("&", "&amp;"), ("<", "&lt;"), (">", "&gt;")):
        result = result.replace(char, entity)
    return result


def format_attributes(attributes):
    """Render an attribute mapping as a string starting with a space."""
    parts = []
    for name in attributes:
        value = attributes[name]
        if not isinstance(value, str):
            raise TypeError("attribute %r must map to a string" % (name,))
        parts.append(' %s="%s"' % (name, escape(value).replace('"', "&quot;")))
    return "".join(parts)


def serialize_element(element):
    """Render a single element dictionary, recursing into its children."""
    tag = element.get("tag")
    if not isinstance(tag, str) or not tag:
        raise ValueError("every element needs a non-empty tag name")
    opening = "<" + tag + format_attributes(element.get("attributes") or {})
    children = element.get("children") or []
    if not children:
        return opening + "/>"
    pieces = [opening + ">"]
    for child in children:
        if isinstance(child, str):
            pieces.append(escape(child))
        else:
            pieces.append(serialize_element(child))
    pieces.append("</" + tag + ">")
    return "".join(pieces)


def serialize(data):
    """Convert a list of element dictionaries into one XML string."""
    if not isinstance(data, list):
        raise TypeError("serialize expects a list of element dictionaries")
    rendered = []
    for element in data:
        rendered.append(serialize_element(element))
    return "".join(rendered)


def count_tags(data):
    """Count how often each tag name occurs in the whole document tree."""
    counts = {}
    stack = list(data)
    while stack:
        node = stack.pop()
        if isinstance(node, str):
            continue
        counts[node["tag"]] = counts.get(node["tag"], 0) + 1
        for child in reversed(node.get("children") or []):
            stack.append(child)
    return counts


def format_report(counts):
    lines = []
    for tag in sorted(counts):
        lines.append("%-10s %d" % (tag, counts[tag]))
    return "\n".join(lines)


def main():
    document = [{
        "tag": "document",
        "attributes": {"lang": "en"},
        "children": [
            {"tag": "title", "children": ["Cats & Dogs"]},
            {"tag": "para", "children": ["text", {"tag": "br"}, "more <text>"]},
            {"tag": "meta", "attributes": {"note": 'a "quoted" word'}},
        ],
    }]
    xml = serialize(document)
    if len(sys.argv) > 1:
        path = sys.argv[1]
        try:
            with open(path, "w", encoding="utf-8") as handle:
                handle.write(xml + "\n")
        except OSError as error:
            print("could not write %s: %s" % (path, error))
        else:
            print("wrote " + path)
    else:
        print(xml)
    print(format_report(count_tags(document)))


if __name__ == "__main__":
    main()

