import sys

SAMPLE = "root\n\tchild one\n\t\tgrandchild\n\tchild two\n\nsecond root\n\tlast child\n"


def count_tabs(line):
    """Return the number of leading tab characters of a line."""
    tabs = 0
    while tabs < len(line) and line[tabs] == "\t":
        tabs += 1
    return tabs


def parse(lines):
    """Build a list of nested (text, children) tuples from tab-indented lines."""
    roots = []
    stack = [roots]
    for raw in lines:
        line = raw.rstrip("\n")
        if not line.strip():
            continue
        depth = count_tabs(line)
        while len(stack) > depth + 1:
            stack.pop()
        if depth >= len(stack):
            raise ValueError("indentation jumps by more than one level: %r" % line)
        children = []
        stack[depth].append((line[depth:], children))
        stack.append(children)
    return roots


def render(tree, depth=0):
    """Yield display lines for a parsed tree, two spaces per level."""
    for text, children in tree:
        yield "  " * depth + text
        for nested in render(children, depth + 1):
            yield nested


def count_nodes(tree):
    total = 0
    for _text, children in tree:
        total += 1 + count_nodes(children)
    return total


def max_depth(tree):
    deepest = 0
    for _text, children in tree:
        candidate = 1 + max_depth(children)
        if candidate > deepest:
            deepest = candidate
    return deepest


def main(argv):
    if len(argv) > 1:
        with open(argv[1], encoding="utf-8") as handle:
            lines = handle.readlines()
    else:
        lines = SAMPLE.splitlines()
    try:
        tree = parse(lines)
    except ValueError as exc:
        print("error: %s" % exc, file=sys.stderr)
        return 1
    for line in render(tree):
        print(line)
    print("--- %d nodes, depth %d" % (count_nodes(tree), max_depth(tree)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

