import sys
from datetime import datetime

SEVERE_LEVELS = {"ERROR", "CRITICAL"}


def parse_line(line):
    """Split one trace into (level, description), or None if malformed."""
    parts = line.strip().split(None, 2)
    if len(parts) < 3:
        return None
    stamp, level, description = parts
    try:
        datetime.fromisoformat(stamp)
    except ValueError:
        return None
    description = " ".join(description.split())
    if not description:
        return None
    return level.upper(), description


def summarize(traces):
    """Count descriptions of error/critical traces, ranked by frequency."""
    counts = {}
    for line in traces:
        event = parse_line(line)
        if event is None:
            continue
        level, description = event
        if level in SEVERE_LEVELS:
            counts[description] = counts.get(description, 0) + 1
    return sorted(counts.items(), key=lambda item: (-item[1], item[0]))


def format_report(ranked):
    """Render the ranked pairs as an aligned table with frequency bars."""
    if not ranked:
        return "no error or critical events found"
    width = 0
    for description, count in ranked:
        if len(description) > width:
            width = len(description)
    lines = []
    for description, count in ranked:
        bar = "#" * count
        lines.append(f"{description.ljust(width)}  {count:>4}  {bar}")
    return "\n".join(lines)


def read_events(stream):
    """Yield non-blank lines from a text stream, one at a time."""
    while True:
        line = stream.readline()
        if not line:
            break
        if line.strip():
            yield line


def main(argv):
    if len(argv) > 1:
        path = argv[1]
        try:
            with open(path, encoding="utf-8") as handle:
                traces = list(read_events(handle))
        except OSError as exc:
            print(f"cannot read {path}: {exc}", file=sys.stderr)
            return 1
    else:
        traces = list(read_events(sys.stdin))
    print(format_report(summarize(traces)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

