import sys

PAIRS = {')': '(', ']': '[', '}': '{'}
OPENERS = set(PAIRS.values())


def validate(sequence):
    """Return the index of the first invalid bracket, or -1 when balanced."""
    stack = []
    for index, char in enumerate(sequence):
        if char in OPENERS:
            stack.append(char)
        elif char in PAIRS:
            if not stack:
                return index
            if stack.pop() != PAIRS[char]:
                return index
    if stack:
