def normalize_email(email):
    return email.strip().lower()


def normalize_phone(phone):
    return "".join(ch for ch in phone if ch.isdigit())


def format_phone(digits):
    if len(digits) == 10:
        return f"({digits[:3]}) {digits[3:6]}-{digits[6:]}"
    return digits


def _entry_from(name, email, phone):
    emails = []
    address = normalize_email(email)
    if address:
        emails.append(address)
    phones = []
    number = normalize_phone(phone)
    if number:
        phones.append(number)
    return {"name": name.strip(), "emails": emails, "phones": phones}


def _is_match(entry, other):
    for address in other["emails"]:
        if address in entry["emails"]:
            return True
    for number in other["phones"]:
        if number in entry["phones"]:
            return True
    return False


def _find_match(merged, entry):
    for index, candidate in enumerate(merged):
        if _is_match(candidate, entry):
            return index
    return None


def _absorb(existing, incoming):
    for address in incoming["emails"]:
        if address not in existing["emails"]:
            existing["emails"].append(address)
    for number in incoming["phones"]:
        if number not in existing["phones"]:
            existing["phones"].append(number)
    if not existing["name"]:
        existing["name"] = incoming["name"]
    return existing


def merge(contacts):
    merged = []
    for name, email, phone in contacts:
        entry = _entry_from(name, email, phone)
        while True:
            index = _find_match(merged, entry)
            if index is None:
                break
            entry = _absorb(merged.pop(index), entry)
        merged.append(entry)
    return [(e["name"], "; ".join(e["emails"]),
             "; ".join(format_phone(n) for n in e["phones"])) for e in merged]


def parse_rows(lines):
    for line in lines:
        line = line.strip()
        if line:
            yield [field.strip() for field in line.split(",")]


def validate_row(row):
    if len(row) != 3:
        raise ValueError(f"expected 3 fields, got {len(row)}")
    name, email, phone = row
    if not name:
        raise ValueError("contact name is required")
    return (name, email, phone)


def main():
    raw = """Ann Lee, ann@ex.com, 555-123-4567
    Anna Lee, ANN@ex.com, 555-987-6543
    Bob Ray, bob@ex.com, 5551234567
    Cara Diaz, cara@ex.com,
    Bad Row, missing-phone
    Dan Cole, dan@ex.com, 555-222-3333
    D. Cole, , 5552223333"""
    contacts = []
    for row in parse_rows(raw.splitlines()):
