import sys


def validate_appointments(appointments):
    for appointment in appointments:
        if len(appointment) != 3:
            raise ValueError(f"expected (name, start, end), got {appointment!r}")
        name, start, end = appointment
        if not isinstance(start, int) or not isinstance(end, int):
            raise ValueError(f"hours of {name!r} must be integers")
        if not 0 <= start < end <= 24:
            raise ValueError(f"hours of {name!r} must satisfy 0 <= start < end <= 24")


def parse_appointments(lines):
    appointments = []
    for number, line in enumerate(lines, start=1):
        text = line.strip()
        if not text:
            continue
        parts = [part.strip() for part in text.split(",")]
        if len(parts) != 3:
            raise ValueError(f"line {number}: expected 'name,start,end'")
        try:
            start = int(parts[1])
            end = int(parts[2])
        except ValueError:
            raise ValueError(f"line {number}: hours must be whole numbers")
        appointments.append((parts[0], start, end))
    validate_appointments(appointments)
    return appointments


def detect(appointments):
    validate_appointments(appointments)
    ordered = sorted(appointments, key=lambda appointment: appointment[1])
    conflicting = []
    for position, (name, start, _end) in enumerate(ordered):
        for previous_name, _previous_start, previous_end in ordered[:position]:
            if start < previous_end:
                for involved in (previous_name, name):
                    if involved not in conflicting:
                        conflicting.append(involved)
    return conflicting


def merge_busy(appointments):
    ordered = sorted(appointments, key=lambda appointment: appointment[1])
    merged = []
    index = 0
    while index < len(ordered):
        start, end = ordered[index][1], ordered[index][2]
        index += 1
        while index < len(ordered) and ordered[index][1] < end:
            end = max(end, ordered[index][2])
            index += 1
        merged.append((start, end))
    return merged


def format_report(appointments, conflicting):
    lines = []
    if conflicting:
        lines.append("Conflicting events:")
        for name, start, end in sorted(appointments, key=lambda item: item[1]):
            if name in conflicting:
                lines.append(f"  {name}: {start:02d}:00-{end:02d}:00")
    else:
        lines.append("No conflicting events.")
    lines.append("Busy blocks:")
    for start, end in merge_busy(appointments):
        lines.append(f"  {start:02d}:00-{end:02d}:00")
    return "\n".join(lines)


def main(argv):
    if len(argv) > 1:
        with open(argv[1], encoding="utf-8") as handle:
