import sys


def _validate_portfolio(portfolio):
    current, targets = portfolio
    for name, value in current:
        if value < 0:
            raise ValueError(f"negative holding for {name}")
    for name, ratio in targets:
        if ratio < 0:
            raise ValueError(f"negative target ratio for {name}")
    if not targets:
        raise ValueError("no target allocation given")


def _settle_cents(adjustments):
    rounded = [(name, round(amount, 2)) for name, amount in adjustments]
    residual = round(sum(amount for _, amount in rounded), 2)
    index = 0
    while abs(residual) >= 0.01 and index < len(rounded):
        name, amount = rounded[index]
        step = -0.01 if residual > 0 else 0.01
        rounded[index] = (name, round(amount + step, 2))
        residual = round(residual + step, 2)
        index += 1
    return rounded


def rebalance(portfolio):
    _validate_portfolio(portfolio)
    current, targets = portfolio
    held = dict(current)
    wanted = dict(targets)
    total = sum(value for _, value in current)
    weight = sum(ratio for _, ratio in targets)
    adjustments = []
    for name, ratio in targets:
        if weight > 0:
            target_value = total * ratio / weight
        else:
            target_value = 0.0
        adjustments.append((name, target_value - held.get(name, 0.0)))
    for name, value in current:
        if name not in wanted:
            adjustments.append((name, -value))
    return _settle_cents(adjustments)


def parse_portfolio(text):
    current, targets = [], []
    for lineno, raw in enumerate(text.splitlines(), 1):
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        parts = [part.strip() for part in line.split(",")]
        if len(parts) != 3:
            raise ValueError(f"line {lineno}: expected 'kind,name,number'")
        kind, name, number = parts
        try:
            amount = float(number)
        except ValueError:
            raise ValueError(f"line {lineno}: {number!r} is not a number")
        if kind == "current":
            current.append((name, amount))
        elif kind == "target":
            targets.append((name, amount))
        else:
            raise ValueError(f"line {lineno}: unknown kind {kind!r}")
    return (current, targets)


def format_report(adjustments):
    lines = []
    for name, amount in adjustments:
        if amount > 0:
            action = "BUY "
        elif amount < 0:
            action = "SELL"
        else:
            action = "HOLD"
        lines.append(f"{action} {name:<10}{abs(amount):12.2f}")
    return "\n".join(lines)


def main(argv):
    if len(argv) > 1:
        with open(argv[1], encoding="utf-8") as handle:
            source = handle.read()
        try:
            portfolio = parse_portfolio(source)
        except ValueError as exc:
            print(f"cannot read {argv[1]}: {exc}", file=sys.stderr)
            return 2
    else:
        portfolio = (
            [("stocks", 6000.0), ("bonds", 2000.0), ("cash", 2000.0)],
            [("stocks", 0.6), ("bonds", 0.3), ("cash", 0.1)],
        )
    try:
        adjustments = rebalance(portfolio)
    except ValueError as exc:
        print(f"invalid portfolio: {exc}", file=sys.stderr)
        return 1
    print(format_report(adjustments))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

