    else:
      action = "HOLD"
    lines.append(f"{action} {name:<10}{abs(amount):12.2f}")
  return "\n".join(lines)


def main(argv):
  if len(argv) > 1:
    with open(argv[1], encoding="utf-8") as handle:
      source = handle.read()
    try:
      portfolio = parse_portfolio(source)
    except ValueError as exc:
