    """Turn lines of 'day, meal type, calories' into a list of tuples."""
    meals = []
    for record in text.splitlines():
        record = record.strip()
        if record:
            fields = [field.strip() for field in record.split(",")]
            if len(fields) != 3:
                raise ValueError("expected 3 fields in %r" % record)
            day, meal, raw = fields
            try:
                calories = int(raw)
            except ValueError:
                raise ValueError("bad calorie count %r" % raw)
            meals.append((day, meal, calories))
    return meals


def daily_totals(meals):
    """Accumulate the calories of every meal into a per-day total."""
    totals = {}
    for day, meal, calories in meals:
        if not isinstance(calories, int):
            raise TypeError("calories for %s/%s must be an int" % (day, meal))
        totals[day] = totals.get(day, 0) + calories
    return totals


