    """Classify each day as high, low or normal by its calorie total."""
    results = []
    for day, total in daily_totals(meals).items():
        excess = total - 2000
        deficit = 1500 - total
        if excess > 0:
            results.append((day, "high"))
        elif deficit > 0:
            results.append((day, "low"))
        else:
            results.append((day, "normal"))
    return results


