import sys


def validate_requests(requests):
    """Check that the incoming workload is a list of non-negative integers."""
    if not isinstance(requests, list):
        raise TypeError("requests must be a list of integers")
    for position, value in enumerate(requests):
        if isinstance(value, bool) or not isinstance(value, int):
            raise TypeError(f"request #{position} is not an integer: {value!r}")
        if value < 0:
            raise ValueError(f"request #{position} is negative: {value}")


def dispatch(requests):
    """Spread the tasks over three servers, keeping the peak load as low as possible."""
    validate_requests(requests)
    load_one = 0
    load_two = 0
    load_three = 0
    pending = sorted(requests, reverse=True)
    while pending:
        task = pending.pop(0)
        if load_one <= load_two and load_one <= load_three:
            load_one += task
        elif load_two <= load_three:
            load_two += task
        else:
            load_three += task
    return (load_one, load_two, load_three)


def parse_requests(text):
    """Turn whitespace or comma separated numbers into a list of integers."""
    values = []
    for token in text.replace(",", " ").split():
        try:
            values.append(int(token))
        except ValueError:
            raise ValueError(f"{token!r} is not a whole number") from None
    return values


def format_report(requests, loads):
    lines = [f"{len(requests)} tasks, total work {sum(requests)}"]
    for number, load in enumerate(loads, start=1):
        lines.append(f"  server {number}: {load}")
    lines.append(f"peak load: {max(loads)}")
    return "\n".join(lines)


def main():
    arguments = sys.argv[1:]
    if arguments:
        with open(arguments[0], encoding="utf-8") as handle:
            text = handle.read()
    else:
        text = sys.stdin.read()
    try:
        requests = parse_requests(text)
        loads = dispatch(requests)
    except (TypeError, ValueError) as error:
        print(f"invalid workload: {error}", file=sys.stderr)
        return 1
    print(format_report(requests, loads))
    return 0


if __name__ == "__main__":
    sys.exit(main())

