WEIGHT_LIMIT = 100
DISCARD_ORDER = ("junk", "consumable")

SAMPLE_MANIFEST = """\
sword,35,gear
bread,5,consumable
rusty can,20,junk
broken cog,15,junk
potion,10,consumable
anvil,60,gear
lantern,many,gear
plate armour,45,gear
"""


def parse_line(line):
    fields = [field.strip() for field in line.split(",")]
    if len(fields) != 3:
        raise ValueError("expected 'name,weight,category', got %r" % line)
    name, raw_weight, category = fields
    weight = int(raw_weight)
    return (name, weight, category)


def validate(items):
    checked = []
    for position, item in enumerate(items):
        if len(item) != 3:
            raise ValueError("item %d must have three fields" % position)
        name, weight, category = item
        if not isinstance(weight, int):
            raise ValueError("weight of %r must be an integer" % name)
        if weight < 0:
            raise ValueError("weight of %r must not be negative" % name)
        checked.append((str(name), weight, str(category).strip().lower()))
    return checked


def free_space(inventory, needed):
    freed = 0
    for category in DISCARD_ORDER:
        index = 0
        while index < len(inventory) and freed < needed:
            if inventory[index][2] == category:
                freed += inventory.pop(index)[1]
            else:
                index += 1
        if freed >= needed:
            break
    return freed


def manage(items):
    inventory = []
    total = 0
    for name, weight, category in validate(items):
        if total + weight > WEIGHT_LIMIT:
            total -= free_space(inventory, total + weight - WEIGHT_LIMIT)
            if total + weight > WEIGHT_LIMIT:
                continue
        inventory.append((name, weight, category))
        total += weight
    return [entry[0] for entry in inventory]


def format_report(items, retained):
    lines = []
    kept = set(retained)
    for name, weight, category in validate(items):
        if name in kept:
            lines.append("kept    %-14s %3d kg  (%s)" % (name, weight, category))
        else:
            lines.append("dropped %-14s %3d kg  (%s)" % (name, weight, category))
    return "\n".join(lines)


def main():
    import sys

    if len(sys.argv) > 1:
        with open(sys.argv[1]) as handle:
            raw_lines = handle.read().splitlines()
    else:
        raw_lines = SAMPLE_MANIFEST.splitlines()
    items = []
    for line in raw_lines:
        if not line.strip():
            continue
        try:
            items.append(parse_line(line))
        except ValueError as error:
            print("ignoring bad entry: %s" % error)
    retained = manage(items)
    print(format_report(items, retained))
    print("carrying %d items, %d kg" % (len(retained), sum(
        weight for name, weight, category in validate(items) if name in set(retained))))


if __name__ == "__main__":
    main()

