import sys


def parse_rooms(text):
    """Turn a textual map (one chamber per line, comma separated links) into lists."""
    rooms = []
    for line in text.splitlines():
        line = line.strip()
        if not line:
            continue
        room = []
        for token in line.split(","):
            token = token.strip()
            if token:
                room.append(int(token))
        rooms.append(room)
    return rooms


def validate_rooms(rooms):
    for index, room in enumerate(rooms):
        if not isinstance(room, list):
            raise TypeError("chamber %d must be described by a list" % index)
        for value in room:
            if value >= len(rooms):
                raise ValueError("chamber %d links to unknown chamber %d" % (index, value))


def reachable_chambers(rooms):
    """Chambers that can be entered at all, ignoring the no-repeat rule."""
    seen = set()
    if rooms:
        stack = [0]
        while stack:
            chamber = stack.pop()
            if chamber not in seen:
                seen.add(chamber)
                for value in rooms[chamber]:
                    if value >= 0:
                        stack.append(value)
    return seen


def explore(rooms):
    validate_rooms(rooms)
    if not rooms:
        return (0, 0)
    best = [0, 0]

    def walk(chamber, visited, total):
        visited.add(chamber)
        total += chamber
        length = len(visited)
        if length > best[0] or (length == best[0] and total > best[1]):
            best[0], best[1] = length, total
        blocked = False
        for value in rooms[chamber]:
            if value < 0:
                blocked = True
        if not blocked:
            for value in rooms[chamber]:
                if value not in visited:
                    walk(value, visited, total)
        visited.remove(chamber)

    walk(0, set(), 0)
    return (best[0], best[1])


def format_report(rooms, length, total):
    lines = ["chambers charted: %d" % len(rooms),
             "longest path: %d" % length,
             "sum collected: %d" % total]
    unreachable = sorted(set(range(len(rooms))) - reachable_chambers(rooms))
    if unreachable:
        lines.append("never entered: " + ", ".join(str(index) for index in unreachable))
    return "\n".join(lines)


def main():
    if len(sys.argv) > 1:
        try:
            with open(sys.argv[1]) as handle:
                rooms = parse_rooms(handle.read())
        except OSError as exc:
            print("cannot read map: %s" % exc)
            return 1
    else:
        rooms = [[2, 3], [], [6], [-1], [], [], [7], [-5]]
    length, total = explore(rooms)
    print(format_report(rooms, length, total))
    return 0


if __name__ == "__main__":
    sys.exit(main())

