import sys


def parse_profile(text):
    """Turn a whitespace/comma separated string into a list of elevations."""
    elevations = []
    for token in text.replace(",", " ").split():
        try:
            height = int(token)
        except ValueError:
            raise ValueError("elevation %r is not an integer" % token)
        if height < 0:
            raise ValueError("elevation %d is negative" % height)
        elevations.append(height)
    return elevations


def fog_column_depths(elevations):
    """Depth of fog resting above each position of the profile.

    The fog drifts downwind, from left to right, so a hollow only holds fog
    when the ridge ahead of it is taller than everything already passed;
    otherwise the fog spills over and escapes.
    """
    size = len(elevations)
    left_peaks = [0] * size
    highest = 0
    for index, height in enumerate(elevations):
        if height > highest:
            highest = height
        left_peaks[index] = highest
    right_peaks = [0] * size
    highest = 0
    index = size - 1
    while index >= 0:
        right_peaks[index] = highest
        if elevations[index] > highest:
            highest = elevations[index]
        index -= 1
    depths = []
    for index, height in enumerate(elevations):
        if right_peaks[index] > left_peaks[index]:
            depths.append(min(left_peaks[index], right_peaks[index]) - height)
        else:
            depths.append(0)
    return depths


def evaluate(elevations):
    """Total volume of fog trapped between the peaks of the terrain."""
    for height in elevations:
        if not isinstance(height, int) or isinstance(height, bool):
            raise TypeError("elevations must be integers, got %r" % (height,))
        if height < 0:
            raise ValueError("elevations must be non negative, got %d" % height)
    return sum(fog_column_depths(elevations))


def format_report(elevations, depths):
    """Render the profile as rows of rock (#) and fog (~), top row first."""
    ceiling = max(elevations) if elevations else 0
    lines = []
    for level in range(ceiling, 0, -1):
        row = ""
        for height, depth in zip(elevations, depths):
            if height >= level:
                row += "#"
            elif height + depth >= level:
                row += "~"
            else:
                row += " "
        lines.append(row)
    lines.append("".join(str(h % 10) for h in elevations))
    return "\n".join(lines)


def main(argv):
    if len(argv) > 1:
        with open(argv[1]) as handle:
            text = handle.read()
    else:
        text = sys.stdin.read()
    try:
        elevations = parse_profile(text)
    except ValueError as error:
