def normalize(component):
    """Lower-case a raw belt entry and collapse its internal whitespace."""
    if not isinstance(component, str):
        raise ValueError("belt entries must be strings, got " + type(component).__name__)
    return " ".join(component.split()).lower()


def is_defective(name):
    words = name.split()
    return bool(words) and words[0] == "broken"


def classify(name):
    """Map a normalized material name onto one of the required part kinds."""
    if name in REQUIRED:
        return name
    if name.endswith("s") and name[:-1] in REQUIRED:
        return name[:-1]
    raise ValueError("unknown material on the belt: " + repr(name))


def is_complete(counts):
    for part, needed in REQUIRED.items():
        if counts[part] < needed:
            return False
    return True


def assemble(components):
    counts = {part: 0 for part in REQUIRED}
    completed = 0
    for raw in components:
        name = normalize(raw)
        if is_defective(name):
            for part in counts:
                counts[part] = 0
            continue
        counts[classify(name)] += 1
        while is_complete(counts):
            for part, needed in REQUIRED.items():
                counts[part] -= needed
            completed += 1
    leftover = []
    for part, amount in counts.items():
        leftover.extend([part] * amount)
    return completed, leftover


