    """Return a pair of upper-case sequence strings, validating its shape."""
    items = list(pair)
    if len(items) != 2:
        raise ValueError("each entry must contain exactly two sequences")
    cleaned = []
    for item in items:
        if not isinstance(item, str):
            raise ValueError("sequences must be strings")
        cleaned.append(item.strip().upper())
    return cleaned[0], cleaned[1]


def longest_common_substring(first, second):
    """Longest contiguous run shared by both strings, earliest one on ties."""
    best = ""
    for start in range(len(first)):
        length = len(best) + 1
        while start + length <= len(first):
            candidate = first[start:start + length]
            if candidate not in second:
                break
            best = candidate
            length += 1
    return best


