import sys


def parse_trace(text):
    """Turn whitespace separated decimal tokens into a list of addresses."""
    accesses = []
    for token in text.split():
        try:
            accesses.append(int(token, 0))
        except ValueError:
            raise ValueError("not a valid address: %r" % token)
    return accesses


def evict(accesses, capacity):
    """Simulate an LRU cache over accesses and return the number of misses."""
    if capacity < 0:
        raise ValueError("capacity must not be negative")
    recency = []
    misses = 0
    for address in accesses:
        if address in recency:
            recency.remove(address)
        else:
            misses += 1
        recency.append(address)
        while len(recency) > capacity:
            recency.pop(0)
    return misses


def miss_ratio(misses, total):
    if total == 0:
        return 0.0
    return misses / total


def choose_capacities(arguments, accesses):
    """Use explicit capacities when given, otherwise sweep up to the working set."""
    if arguments:
        capacities = [int(argument) for argument in arguments]
    else:
        distinct = len(set(accesses))
        if distinct == 0:
            capacities = [1]
        else:
            capacities = list(range(1, distinct + 1))
    return capacities


def format_report(accesses, capacities):
    lines = ["capacity  misses  miss ratio"]
    for capacity in capacities:
        misses = evict(accesses, capacity)
        ratio = miss_ratio(misses, len(accesses))
        lines.append("%8d  %6d  %9.3f" % (capacity, misses, ratio))
    return "\n".join(lines)


def main(argv=None):
