import sys

FIELD_NAMES = ("minute", "hour", "day of month", "month", "day of week")
DEFAULT_LIMITS = (60, 24, 31, 12, 7)


def parse_number(token, limit):
    text = token.strip()
    try:
        value = int(text)
    except ValueError:
        raise ValueError("not a number: %r" % token)
    if value < 0 or value >= limit:
        raise ValueError("value %d outside 0-%d" % (value, limit - 1))
    return value


def parse_field(field, limit):
    if field == "*":
        return list(range(limit))
    values = []
    for part in field.split(","):
        if "-" in part:
            bounds = part.split("-")
            if len(bounds) != 2:
                raise ValueError("malformed range: %r" % part)
            start = parse_number(bounds[0], limit)
            end = parse_number(bounds[1], limit)
            if start > end:
                raise ValueError("descending range: %r" % part)
            values.extend(range(start, end + 1))
        else:
            values.append(parse_number(part, limit))
    return sorted(set(values))


def expand(cron, limits):
    fields = cron.split()
    if len(fields) != 5:
        raise ValueError("expected 5 fields, got %d" % len(fields))
    if len(limits) != 5:
        raise ValueError("expected 5 limits, got %d" % len(limits))
    expanded = []
    for field, limit in zip(fields, limits):
        expanded.append(parse_field(field, limit))
    return expanded


def chunk_values(values, per_line):
    chunks = []
    index = 0
    while index < len(values):
        chunks.append(values[index:index + per_line])
        index += per_line
    return chunks


def format_report(cron, columns):
    lines = ["cron: " + cron]
    for name, values in zip(FIELD_NAMES, columns):
        prefix = "  %-14s" % name
        for chunk in chunk_values(values, 15):
            lines.append(prefix + " ".join(str(value) for value in chunk))
            prefix = " " * 16
    return "\n".join(lines)


