import math
import sys


def parse_color(text):
    """Turn a textual "r,g,b" specification into a validated colour tuple."""
    cleaned = text.strip().strip("()")
    parts = cleaned.split(",")
    if len(parts) != 3:
        raise ValueError(f"expected 3 components, got {len(parts)}")
    components = []
    for part in parts:
        try:
            value = int(part.strip())
        except ValueError:
            raise ValueError(f"non-integer component {part.strip()!r}")
        if not 0 <= value <= 255:
            raise ValueError(f"component {value} outside 0..255")
        components.append(value)
    return tuple(components)


def distance(first, second):
    """Euclidean distance between two RGB triples."""
    total = 0
    for left, right in zip(first, second):
        total += (left - right) ** 2
    return math.sqrt(total)


def group(colors, threshold):
    """Group colours around the first member of each group."""
    if threshold <= 0:
        raise ValueError("threshold must be positive")
    groups = []
    for color in colors:
        index = 0
        placed = False
        while index < len(groups):
            if distance(groups[index][0], color) < threshold:
                groups[index].append(color)
                placed = True
                break
            index += 1
        if not placed:
            groups.append([color])
    return groups


def format_groups(groups):
    lines = []
    for number, members in enumerate(groups, start=1):
        lines.append(f"Group {number} (anchor {members[0]}):")
        for red, green, blue in members:
            lines.append(f"    #{red:02X}{green:02X}{blue:02X}  ({red}, {green}, {blue})")
    return "\n".join(lines)


def load_specs(source):
    if source is None:
        return ["255,0,0", "0,0,255", "245,10,10"]
    specs = []
    with open(source) as handle:
        for line in handle:
            text = line.split("#")[0].strip()
            if text:
                specs.append(text)
    return specs


def main(argv):
    threshold = float(argv[1]) if len(argv) > 1 else 120.0
    source = argv[2] if len(argv) > 2 else None
    colors = []
    for spec in load_specs(source):
        try:
            colors.append(parse_color(spec))
        except ValueError as error:
            print(f"skipping {spec!r}: {error}", file=sys.stderr)
    print(f"threshold = {threshold:g}")
    print(format_groups(group(colors, threshold)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

