import sys

SLOT_COUNT = 5
INITIAL_BLOCKS = 3
VALID_COMMANDS = ("left", "right", "grab", "drop")


def expand_program(text):
    """Split a program string into commands, unrolling 'name*count' repeats."""
    commands = []
    for token in text.replace(",", " ").split():
        if "*" in token:
            name, times = token.split("*", 1)
            try:
                repeat = int(times)
            except ValueError:
                raise ValueError("repeat count is not a number in %r" % token)
            if repeat < 0:
                raise ValueError("negative repeat count in %r" % token)
            while repeat > 0:
                commands.append(name)
                repeat -= 1
        else:
            commands.append(token)
    return commands


def normalize(commands):
    """Lower-case and validate every command, rejecting unknown words."""
    cleaned = []
    for command in commands:
        word = str(command).strip().lower()
        if word not in VALID_COMMANDS:
            raise ValueError("unknown command: %r" % command)
        cleaned.append(word)
    return cleaned


def stack(commands):
    slots = [INITIAL_BLOCKS] * SLOT_COUNT
    position = 0
    holding = False
    for command in normalize(commands):
        if command == "left":
            if position > 0:
                position -= 1
        elif command == "right":
            if position < SLOT_COUNT - 1:
                position += 1
        elif command == "grab":
            if not holding and slots[position] > 0:
                slots[position] -= 1
                holding = True
        else:
            if holding:
                slots[position] += 1
                holding = False
    return slots


def render(slots):
    lines = ["slot  blocks  chart"]
    for index, count in enumerate(slots):
        lines.append("%4d  %6d  %s" % (index, count, "#" * count))
    lines.append("blocks resting in slots: %d" % sum(slots))
    return "\n".join(lines)


