import math
import sys


def validate_brackets(brackets):
    if not brackets:
        raise ValueError("at least one bracket is required")
    previous = None
    for threshold, rate in brackets:
        if threshold < 0:
            raise ValueError("thresholds must not be negative")
        if rate < 0 or rate > 100:
            raise ValueError("rates must be percentages between 0 and 100")
        if previous is not None and threshold <= previous:
            raise ValueError("thresholds must be strictly increasing")
        previous = threshold


def bracket_segments(income, brackets):
    validate_brackets(brackets)
    segments = []
    index = 0
    while index < len(brackets):
        threshold, rate = brackets[index]
        if income <= threshold:
            break
        if index + 1 < len(brackets):
            upper = min(income, brackets[index + 1][0])
        else:
            upper = income
        taxable = upper - threshold
        if taxable > 0:
            segments.append((threshold, upper, rate, taxable * rate / 100.0))
        index += 1
    return segments


def calculate(income, brackets):
    if income < 0:
        raise ValueError("income must not be negative")
    total = 0.0
    for _, _, _, tax in bracket_segments(income, brackets):
        total += tax
    return math.floor(total)


def format_report(income, brackets):
    lines = ["Income: {}".format(income)]
    for lower, upper, rate, tax in bracket_segments(income, brackets):
        lines.append("  {:>7} - {:<7} at {:>3}%  ->  {:.2f}".format(lower, upper, rate, tax))
    lines.append("Total tax owed: {}".format(calculate(income, brackets)))
    return "\n".join(lines)


def main(argv):
    brackets = [(0, 10), (50, 20), (200, 35)]
    out_path = None
    incomes = []
    for arg in argv[1:]:
        if arg.startswith("--out="):
            out_path = arg.split("=", 1)[1]
        else:
            try:
                incomes.append(int(arg))
            except ValueError:
                print("ignoring non-integer income: " + arg, file=sys.stderr)
    if not incomes:
        incomes = [100]
    reports = []
    for income in incomes:
        try:
            reports.append(format_report(income, brackets))
        except ValueError as exc:
            reports.append("cannot compute tax for {}: {}".format(income, exc))
    text = "\n\n".join(reports)
    if out_path:
        with open(out_path, "w") as handle:
            handle.write(text + "\n")
    else:
        print(text)


if __name__ == "__main__":
    main(sys.argv)

