import io
import math


def parse_readings(text):
    """Turn one raw sensor log line into a list of integer readings."""
    readings = []
    for token in text.replace(",", " ").split():
        try:
            readings.append(int(token))
        except ValueError:
            raise ValueError("not an integer reading: {!r}".format(token))
    return readings


def peak_amplitude(readings):
    peak = 0
    for value in readings:
        size = abs(value)
        if size > peak:
            peak = size
    return peak


def significant(readings, threshold):
    kept = []
    for value in readings:
        if abs(value) > threshold:
            kept.append(value)
    return kept


def total_energy(readings, threshold):
    energy = 0
    for value in significant(readings, threshold):
        energy += value * value
    return energy


def dominant_span(readings, threshold):
    """Index range of the contiguous significant block around the peak."""
    peak = peak_amplitude(readings)
    center = 0
    for index, value in enumerate(readings):
        if abs(value) == peak:
            center = index
            break
    left = center
    while left > 0 and abs(readings[left - 1]) > threshold:
        left -= 1
    right = center
    while right < len(readings) - 1 and abs(readings[right + 1]) > threshold:
        right += 1
    return left, right


def evaluate(readings):
    peak = peak_amplitude(readings)
    if peak == 0:
        return 0
    energy = total_energy(readings, peak * 0.1)
    if energy == 0:
        return 0
    return round(2 * math.log10(energy), 1)


def format_report(name, readings):
    with io.StringIO() as out:
        out.write("=== {} ===\n".format(name))
        peak = peak_amplitude(readings)
        if peak == 0:
            out.write("no measurable movement\n")
        else:
            threshold = peak * 0.1
            left, right = dominant_span(readings, threshold)
            out.write("samples      : {}\n".format(len(readings)))
            out.write("peak         : {}\n".format(peak))
            out.write("threshold    : {:.1f}\n".format(threshold))
            out.write("dominant span: {}..{} -> {}\n".format(
                left, right, readings[left:right + 1]))
            out.write("energy       : {}\n".format(total_energy(readings, threshold)))
            out.write("magnitude    : {}\n".format(evaluate(readings)))
        return out.getvalue()


def main():
    logs = [
        ("station A", "2 -3 1 0 4 12000 -9000 5 -2 1"),
        ("station B", "1, 0, -1, 2, 0"),
        ("station C", ""),
        ("station D", "7 4 x9 3"),
    ]
    for name, text in logs:
        try:
            readings = parse_readings(text)
        except ValueError as error:
            print("{}: unusable log ({})".format(name, error))
            continue
        print(format_report(name, readings), end="")


if __name__ == "__main__":
    main()

