import sys
from io import StringIO


def validate(cars):
    """Return the car numbers as a list, rejecting non-integers and duplicates."""
    numbers = []
    for car in cars:
        if isinstance(car, bool) or not isinstance(car, int):
            raise TypeError(f"car numbers must be integers, got {car!r}")
        if car in numbers:
            raise ValueError(f"duplicate car number {car}")
        numbers.append(car)
    return numbers


def choose_siding(sidings, car):
    """Index of the siding whose top car is the smallest value greater than car."""
    best = None
    best_top = None
    empty = None
    for index, siding in enumerate(sidings):
        if not siding:
            if empty is None:
                empty = index
        elif siding[-1] > car:
            if best_top is None or siding[-1] < best_top:
                best = index
                best_top = siding[-1]
    if best is None:
        return empty
    return best


def release_next(sidings, wanted):
    """Index of the siding holding `wanted` at its end, or None."""
    for index, siding in enumerate(sidings):
        if siding and siding[-1] == wanted:
            return index
    return None


def shunt(cars, siding_count=3, log=None):
    """Sort cars onto the outgoing track, recording each move in `log`."""
    incoming = validate(cars)
    order = sorted(incoming)
    sidings = [[] for _ in range(siding_count)]
    outgoing = []
    position = 0
    while position < len(order):
        index = release_next(sidings, order[position])
        if index is not None:
            car = sidings[index].pop()
            outgoing.append(car)
            position += 1
            if log is not None:
                log.append((car, f"siding {index + 1}", "outgoing"))
        elif incoming:
            car = incoming.pop(0)
            index = choose_siding(sidings, car)
            if index is None:
                raise RuntimeError(f"every siding is blocked for car {car}")
            sidings[index].append(car)
            if log is not None:
                log.append((car, "incoming", f"siding {index + 1}"))
        else:
            raise RuntimeError("the yard is deadlocked; more sidings are needed")
    return outgoing


def format_report(cars, outgoing, moves):
    with StringIO() as buf:
        buf.write("incoming: " + " ".join(str(car) for car in cars) + "\n")
        for step, (car, source, destination) in enumerate(moves, 1):
            buf.write(f"{step:3d}. car {car}: {source} -> {destination}\n")
        buf.write("outgoing: " + " ".join(str(car) for car in outgoing) + "\n")
        return buf.getvalue()


def main(argv):
    if len(argv) > 1:
        try:
            cars = [int(argument) for argument in argv[1:]]
        except ValueError:
            print(f"usage: {argv[0]} CAR_NUMBER...", file=sys.stderr)
            return 2
    else:
