    moves = []
    try:
        outgoing = shunt(cars, log=moves)
    except (TypeError, ValueError, RuntimeError) as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 1
    print(format_report(cars, outgoing, moves), end="")
    return 0


if __name__ == "__main__":
