import sys

VOWELS = "aeiouAEIOU"


def extract_vowels(message):
  """Return the vowels of the message, in the order they appear."""
  found = []
  for ch in message:
    if ch in VOWELS:
      found.append(ch)
  return found


def rotate_right(items):
  """Move every item one place to the right, wrapping the last to the front."""
  if not items:
    return []
  return [items[-1]] + items[:-1]


def match_case(vowel, model):
  """Give `vowel` the case of the vowel it replaces."""
  if model.isupper():
    return vowel.upper()
  return vowel.lower()


def encrypt(message):
  if not isinstance(message, str):
    raise TypeError("message must be a string")
  shifted = rotate_right(extract_vowels(message))
  result = []
  position = 0
  for ch in message:
    if ch in VOWELS:
      result.append(match_case(shifted[position], ch))
      position += 1
    else:
      result.append(ch)
  return "".join(result)


def cycle_length(message):
  """How many encryptions are needed before the message reappears."""
  current = encrypt(message)
  steps = 1
  while current != message:
    current = encrypt(current)
    steps += 1
  return steps


def load_messages(path):
  messages = []
  with open(path, encoding="utf-8") as handle:
    for line in handle:
      text = line.rstrip("\n")
      if text:
        messages.append(text)
  return messages


def format_report(messages):
  width = max(len(text) for text in messages)
  lines = []
  for text in messages:
    lines.append(f"{text:<{width}} -> {encrypt(text):<{width}}  (cycle {cycle_length(text)})")
  return "\n".join(lines)


def main():
  if len(sys.argv) > 1:
    try:
      messages = load_messages(sys.argv[1])
    except OSError as exc:
      print(f"cannot read {sys.argv[1]}: {exc}", file=sys.stderr)
      return 1
  else:
    messages = ["hello", "Aardvarks In Orbit", "rhythm"]
  if not messages:
    print("no messages to transform")
    return 0
  print(format_report(messages))
  return 0


if __name__ == "__main__":
  sys.exit(main())

