    """Return a new string with the characters of s in reverse order."""
    if not isinstance(s, str):
        raise TypeError("reverse_string expects a string, got %s" % type(s).__name__)
    characters = []
    for index in range(len(s) - 1, -1, -1):
        characters.append(s[index])
    return "".join(characters)


def reverse_words(sentence):
    """Reverse the order of whitespace-separated words, keeping each word intact."""
    words = sentence.split()
    reversed_words = []
    for word in reversed(words):
        reversed_words.append(word)
    return " ".join(reversed_words)


