    """Report whether s reads the same forwards and backwards."""
    cleaned = []
    for character in s:
        if character.isalnum():
            cleaned.append(character.lower() if ignore_case else character)
    normalized = "".join(cleaned)
    return normalized == reverse_string(normalized)


