def is_prime(n):
    """Return True if the positive integer n is a prime number."""
    if not isinstance(n, int):
        raise TypeError("n must be an integer")
    if n < 1:
        raise ValueError("n must be a positive integer")
    if n < 2:
        return False
    if n < 4:
        return True
    if n % 2 == 0:
        return False
    divisor = 3
    while divisor * divisor <= n:
        if n % divisor == 0:
            return False
        divisor += 2
    return True


def primes_up_to(limit):
    """Return the list of primes <= limit using a sieve of Eratosthenes."""
    if limit < 2:
        return []
    sieve = [True] * (limit + 1)
    sieve[0] = sieve[1] = False
    step = 2
    while step * step <= limit:
        if sieve[step]:
            for multiple in range(step * step, limit + 1, step):
                sieve[multiple] = False
        step += 1
    return [number for number, prime in enumerate(sieve) if prime]


def prime_factors(n):
    """Return the prime factors of n in ascending order, with repetition."""
    if n < 1:
        raise ValueError("n must be a positive integer")
    factors = []
    remainder = n
    candidate = 2
    while candidate * candidate <= remainder:
        while remainder % candidate == 0:
            factors.append(candidate)
            remainder //= candidate
        candidate += 1 if candidate == 2 else 2
    if remainder > 1:
        factors.append(remainder)
    return factors


def describe(n):
    """Build a one-line description of n as prime or as a product of primes."""
    if is_prime(n):
        return "{0} is prime".format(n)
    if n == 1:
        return "1 is neither prime nor composite"
    product = " x ".join(str(factor) for factor in prime_factors(n))
    return "{0} is composite = {1}".format(n, product)


def main():
    for number in (1, 2, 7, 10, 29, 91, 97, 561, 7919):
        print(describe(number))
    limit = 50
    small = primes_up_to(limit)
    print("Primes up to {0}: {1}".format(limit, small))
    twins = [(p, p + 2) for p in small if p + 2 <= limit and is_prime(p + 2)]
    print("Twin prime pairs up to {0}: {1}".format(limit, twins))


if __name__ == "__main__":
    main()

