def validate_operations(operations):
    """Check that every entry looks like ('enqueue', item) or ('dequeue', None)."""
    if not isinstance(operations, (list, tuple)):
        raise TypeError("operations must be a list of tuples")
    for index, entry in enumerate(operations):
        if not isinstance(entry, tuple) or len(entry) != 2:
            raise ValueError("operation %d must be a 2-tuple" % index)
        name, payload = entry
        if name not in ("enqueue", "dequeue"):
            raise ValueError("operation %d has unknown name %r" % (index, name))
        if name == "dequeue" and payload is not None:
            raise ValueError("operation %d: dequeue takes no payload" % index)


def apply_operation(queue, operation):
    """Apply one operation to queue in place and return the removed item, if any."""
    name, payload = operation
    if name == "enqueue":
        queue.append(payload)
        return None
    if queue:
        return queue.pop(0)
    return None


def simulate_queue(operations):
    """Run all operations on an initially empty queue and return its final state."""
    validate_operations(operations)
    queue = []
    for operation in operations:
        apply_operation(queue, operation)
    return queue


def trace_queue(operations):
    """Return a list of (description, queue snapshot) pairs, one per operation."""
    validate_operations(operations)
    queue = []
    steps = []
    for operation in operations:
        removed = apply_operation(queue, operation)
        if operation[0] == "enqueue":
            description = "enqueue %r" % (operation[1],)
        elif removed is None:
            description = "dequeue from empty queue"
        else:
            description = "dequeue %r" % (removed,)
        steps.append((description, list(queue)))
    return steps


def format_report(operations):
    """Build a human readable report of the simulation."""
    lines = []
    for number, (description, snapshot) in enumerate(trace_queue(operations), start=1):
        lines.append("%2d. %-28s -> %s" % (number, description, snapshot))
    lines.append("final queue: %s" % (simulate_queue(operations),))
    return "\n".join(lines)


def main():
    scenarios = [
        [("enqueue", 1), ("enqueue", 2), ("dequeue", None)],
        [("dequeue", None)],
        [("enqueue", "a"), ("dequeue", None), ("enqueue", "b"), ("enqueue", "c")],
    ]
    for position, operations in enumerate(scenarios, start=1):
        print("scenario %d" % position)
        print(format_report(operations))
        print()
    broken = [("enqueue", 1), ("dequeue", 5)]
    try:
        simulate_queue(broken)
    except ValueError as error:
        print("rejected invalid input: %s" % error)


if __name__ == "__main__":
    main()

