    product = 1
    for value in numbers:
        product *= value
    return product


def validate_numbers(numbers):
    """Ensure the input is a list of int/float, returning it unchanged."""
    if not isinstance(numbers, list):
        raise TypeError("numbers must be a list")
    for index, value in enumerate(numbers):
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError("element %d is not a number: %r" % (index, value))
    return numbers


def parse_numbers(text):
    """Parse a comma or space separated string into a list of int/float."""
    tokens = text.replace(",", " ").split()
    numbers = []
    for token in tokens:
        try:
            numbers.append(int(token))
        except ValueError:
            numbers.append(float(token))
    return numbers


def format_product(numbers):
    """Build a readable 'a * b * c = p' line for the given numbers."""
    validate_numbers(numbers)
    if not numbers:
        return "(empty) = 1"
    parts = []
    for value in numbers:
        if isinstance(value, float) and value.is_integer():
            parts.append(str(int(value)))
        else:
            parts.append(str(value))
    return " * ".join(parts) + " = " + str(product_list(numbers))


