def validate(numbers):
    """Return the input as a list of floats, rejecting invalid entries."""
    if not isinstance(numbers, (list, tuple)):
        raise TypeError("numbers must be a list of positive numbers")
    values = []
    for item in numbers:
        if isinstance(item, bool) or not isinstance(item, (int, float)):
            raise TypeError("all entries must be numbers, got %r" % (item,))
        value = float(item)
        if value <= 0.0:
            raise ValueError("all entries must be positive, got %r" % (item,))
        values.append(value)
    if not values:
        raise ValueError("numbers must contain at least one value")
    return values


def harmonic_mean(numbers):
    """Reciprocal of the arithmetic mean of the reciprocals."""
    values = validate(numbers)
    total = 0.0
    for value in values:
        total += 1.0 / value
    return len(values) / total


def arithmetic_mean(numbers):
    values = validate(numbers)
    return sum(values) / len(values)


def geometric_mean(numbers):
    values = validate(numbers)
    product = 1.0
    for value in values:
        product *= value
    return product ** (1.0 / len(values))


def parse_series(text):
    """Turn a comma or space separated string into a list of floats."""
    tokens = text.replace(",", " ").split()
    values = []
    for token in tokens:
        try:
            values.append(float(token))
        except ValueError:
            raise ValueError("cannot read %r as a number" % (token,))
    return values


def describe(numbers):
    """Build a one-line report comparing the three classical means."""
    means = (
        ("harmonic", harmonic_mean(numbers)),
        ("geometric", geometric_mean(numbers)),
        ("arithmetic", arithmetic_mean(numbers)),
    )
    parts = []
    for name, value in means:
        parts.append("%s=%.6f" % (name, value))
    return "%s -> %s" % (numbers, "  ".join(parts))


def main():
    samples = ["1 2 4", "10, 10, 10", "0.5 1.5 3 7.25"]
    for text in samples:
        series = parse_series(text)
        print(describe(series))
    bad_inputs = ["1 0 4", "", "2 -3"]
    for text in bad_inputs:
        series = parse_series(text)
        try:
            print(harmonic_mean(series))
        except ValueError as error:
            print("rejected %r: %s" % (text, error))


if __name__ == "__main__":
    main()

