import random
from collections import Counter


def roll_die(num_sides):
    """Return a random integer from 1 to num_sides inclusive."""
    if not isinstance(num_sides, int) or isinstance(num_sides, bool):
        raise TypeError("num_sides must be an integer")
    if num_sides < 1:
        raise ValueError("num_sides must be at least 1")
    return random.randint(1, num_sides)


def roll_many(num_sides, times):
    """Roll an N-sided die a number of times and return the list of results."""
    if times < 1:
        raise ValueError("times must be at least 1")
    results = []
    for _ in range(times):
        results.append(roll_die(num_sides))
    return results


def tally(results):
    """Count how often each face appeared."""
    counts = Counter()
    for value in results:
        counts[value] += 1
    return counts


def parse_dice_notation(text):
    """Parse notation like '3d6' into (count, sides)."""
    cleaned = text.strip().lower()
    if "d" not in cleaned:
        raise ValueError("notation must contain 'd', e.g. 3d6")
    left, _, right = cleaned.partition("d")
    count = int(left) if left else 1
    sides = int(right)
    return count, sides


def roll_notation(text):
    """Roll the dice described by a notation string and return the rolls."""
    count, sides = parse_dice_notation(text)
    return roll_many(sides, count)


def format_histogram(counts, sides, width=40):
    """Build a text histogram of face frequencies."""
    total = sum(counts.values())
    peak = max(counts.values())
    lines = []
    for face in range(1, sides + 1):
        hits = counts.get(face, 0)
        bar_length = round(width * hits / peak)
        share = 100.0 * hits / total
        lines.append("{:>3} | {:<{w}} {:5.1f}%".format(face, "#" * bar_length, share, w=width))
    return "\n".join(lines)


def main():
    for notation in ("1d6", "1d20", "2d10"):
        rolls = roll_notation(notation)
        joined = ", ".join(str(value) for value in rolls)
        print("{}: {} (sum {})".format(notation, joined, sum(rolls)))

    sides = 6
    trials = 6000
    results = roll_many(sides, trials)
    counts = tally(results)
    print("\nDistribution of {} rolls of a {}-sided die:".format(trials, sides))
    print(format_histogram(counts, sides))

    expected = trials / sides
    worst_face, worst_gap = 1, 0.0
    for face in range(1, sides + 1):
        gap = abs(counts.get(face, 0) - expected)
        if gap > worst_gap:
            worst_face, worst_gap = face, gap
    print("Largest deviation: face {} off by {:.1f} rolls".format(worst_face, worst_gap))


if __name__ == "__main__":
    main()

