CATEGORIES = ((18.5, "Underweight"), (25.0, "Normal weight"), (30.0, "Overweight"), (float("inf"), "Obese"))


def calculate_bmi(weight_kg, height_m):
    """Return the Body Mass Index rounded to two decimal places."""
    if weight_kg <= 0:
        raise ValueError("weight must be a positive number of kilograms")
    if height_m <= 0:
        raise ValueError("height must be a positive number of metres")
    return round(weight_kg / (height_m * height_m), 2)


def classify_bmi(bmi):
    """Map a BMI value onto the standard World Health Organisation bands."""
    for upper_bound, label in CATEGORIES:
        if bmi < upper_bound:
            return label
    raise ValueError("BMI value could not be classified")


def parse_measurements(text):
    """Turn a 'weight height' string into a pair of floats."""
    parts = text.replace(",", " ").split()
    if len(parts) != 2:
        raise ValueError("expected exactly two values: weight and height")
    numbers = []
    for part in parts:
        try:
            numbers.append(float(part))
        except ValueError:
            raise ValueError("%r is not a number" % part)
    weight_kg, height_m = numbers
    if height_m > 3.0:
        height_m = height_m / 100.0
    return weight_kg, height_m


def format_report(weight_kg, height_m):
    """Build a one-line human readable summary for a single person."""
    bmi = calculate_bmi(weight_kg, height_m)
    category = classify_bmi(bmi)
    return "%.1f kg at %.2f m -> BMI %.2f (%s)" % (weight_kg, height_m, bmi, category)


