def normalize_unit(unit):
    """Return the canonical unit name ('m' or 'ft') for a user supplied string."""
    if not isinstance(unit, str):
        raise TypeError("unit must be a string")
    aliases = {
        'm': 'm',
        'meter': 'm',
        'meters': 'm',
        'metre': 'm',
        'metres': 'm',
        'ft': 'ft',
        'foot': 'ft',
        'feet': 'ft',
    }
    cleaned = unit.strip().lower()
    if cleaned not in aliases:
        raise ValueError("unsupported unit: {!r}".format(unit))
    return aliases[cleaned]


FEET_PER_METER = 3.28084


def convert_length(value, from_unit, to_unit):
    """Convert a length between meters and feet and return the result as a float."""
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise TypeError("value must be a number")
    source = normalize_unit(from_unit)
    target = normalize_unit(to_unit)
    amount = float(value)
    if source == target:
        return amount
    if source == 'm':
        return amount * FEET_PER_METER
    return amount / FEET_PER_METER


def format_conversion(value, from_unit, to_unit, digits=4):
    """Produce a human readable line describing one conversion."""
    result = convert_length(value, from_unit, to_unit)
    source = normalize_unit(from_unit)
    target = normalize_unit(to_unit)
    return "{0:g} {1} = {2:g} {3}".format(value, source, round(result, digits), target)


def conversion_table(values, from_unit, to_unit):
    """Convert every value of an iterable, returning (original, result) pairs."""
    rows = []
    for item in values:
        rows.append((item, convert_length(item, from_unit, to_unit)))
    return rows


def main():
    print(format_conversion(10, 'm', 'ft'))
    print(format_conversion(3.28084, 'ft', 'm'))
    for original, converted in conversion_table([1, 2.5, 100], 'meters', 'feet'):
        print("{0:>8g} m -> {1:>10.4f} ft".format(original, converted))


if __name__ == '__main__':
    main()

