def calculate_power(base, exponent):
    if not isinstance(exponent, int):
        raise TypeError("Exponent must be an integer.")

    if exponent < 0:
        # Handle negative exponents
        if base == 0:
            raise ValueError("Cannot raise 0 to a negative exponent.")
        result = 1.0 / calculate_power(base, -exponent)
        return result
    elif exponent == 0:
        return 1
    else:
        # Positive integer exponent calculation
        accumulator = 1
        for _ in range(exponent):
            accumulator *= base
        return accumulator

def main():
    # Example usage of the function
    print(f"2 to the power of 3 is: {calculate_power(2, 3)}")
    print(f"5 to the power of 0 is: {calculate_power(5, 0)}")
    print(f"10 to the power of 1 is: {calculate_power(10, 1)}")
    print(f"2.5 to the power of 2 is: {calculate_power(2.5, 2)}")
    print(f"3 to the power of -2 is: {calculate_power(3, -2)}")
    print(f"-2 to the power of 3 is: {calculate_power(-2, 3)}")

if __name__ == "__main__":
