def update_inventory(inventory, item_name, quantity_change):
    """Apply a quantity change to an item, clamping the result at zero."""
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dictionary")
    if not isinstance(item_name, str) or not item_name:
        raise ValueError("item_name must be a non-empty string")
    if not isinstance(quantity_change, int) or isinstance(quantity_change, bool):
        raise TypeError("quantity_change must be an integer")
    new_quantity = inventory.get(item_name, 0) + quantity_change
    if new_quantity < 0:
        new_quantity = 0
    inventory[item_name] = new_quantity
    return inventory

def apply_transactions(inventory, transactions):
    """Run a sequence of (item_name, quantity_change) pairs against inventory."""
    for item_name, quantity_change in transactions:
        update_inventory(inventory, item_name, quantity_change)
    return inventory

def parse_transaction(line):
    """Turn a line like 'apple +5' or 'banana -10' into a transaction tuple."""
    parts = line.split()
    if len(parts) != 2:
        raise ValueError("expected '<item> <change>', got: %r" % line)
    name, raw_change = parts
    try:
        change = int(raw_change)
    except ValueError:
        raise ValueError("invalid quantity change: %r" % raw_change)
    return name, change

def read_transactions(lines):
    """Parse non-empty, non-comment lines into transaction tuples."""
    transactions = []
    for line in lines:
        stripped = line.strip()
        if stripped and not stripped.startswith("#"):
            transactions.append(parse_transaction(stripped))
    return transactions

def out_of_stock(inventory):
    """Names of items whose quantity has fallen to zero, alphabetically."""
    return sorted(name for name, qty in inventory.items() if qty == 0)

def format_report(inventory):
    """Build an aligned text report of the inventory plus a total line."""
    if not inventory:
        return "inventory is empty"
    width = max(len(name) for name in inventory)
    rows = []
    for name in sorted(inventory):
        rows.append("%-*s %5d" % (width, name, inventory[name]))
    rows.append("%-*s %5d" % (width, "TOTAL", sum(inventory.values())))
    return "\n".join(rows)

def main():
    inventory = {"apple": 10, "banana": 5, "cherry": 0}
    log = [
        "# morning deliveries",
        "apple +5",
        "banana -10",
        "cherry +12",
        "",
        "durian -3",
    ]
    apply_transactions(inventory, read_transactions(log))
    print(format_report(inventory))
    missing = out_of_stock(inventory)
    if missing:
        print("reorder: " + ", ".join(missing))

if __name__ == "__main__":
    main()

