ABSOLUTE_ZERO_C = -273.15

def to_celsius(value, unit_from):
    if unit_from == 'C':
        return float(value)
    if unit_from == 'F':
        return (float(value) - 32.0) * 5.0 / 9.0
    return float(value) + ABSOLUTE_ZERO_C

def from_celsius(celsius, unit_to):
    if unit_to == 'C':
        return celsius
    if unit_to == 'F':
        return celsius * 9.0 / 5.0 + 32.0
    return celsius - ABSOLUTE_ZERO_C

def convert_temperature(value, unit_from, unit_to):
    celsius = to_celsius(value, unit_from)
    return from_celsius(celsius, unit_to)

def is_below_absolute_zero(value, unit_from):
    return to_celsius(value, unit_from) < ABSOLUTE_ZERO_C

def format_temperature(value, unit, decimals=2):
    rounded = round(float(value), decimals)
    if unit == 'K':
        return "{0:.{1}f} K".format(rounded, decimals)
    return "{0:.{1}f} \u00b0{2}".format(rounded, decimals, unit)

def conversion_table(value, unit_from):
    table = {}
    for unit in ('C', 'F', 'K'):
        table[unit] = convert_temperature(value, unit_from, unit)
    return table

def describe(value, unit_from):
    if is_below_absolute_zero(value, unit_from):
        return "{0} is below absolute zero".format(format_temperature(value, unit_from))
    table = conversion_table(value, unit_from)
    parts = []
    for unit in ('C', 'F', 'K'):
        parts.append(format_temperature(table[unit], unit))
    return " = ".join(parts)

def parse_reading(text):
    cleaned = text.strip().replace('\u00b0', ' ')
    pieces = cleaned.split()
    if len(pieces) != 2:
        raise ValueError("expected a number followed by a unit: {0!r}".format(text))
    number, unit = pieces
    unit = unit.upper()
    if unit not in ('C', 'F', 'K'):
        raise ValueError("unknown unit: {0!r}".format(pieces[1]))
    return float(number), unit

def main():
    readings = ["0 C", "273.15 K", "98.6 F", "-500 F", "100 \u00b0C", "oops"]
    for text in readings:
        try:
            value, unit = parse_reading(text)
        except ValueError as error:
            print("skipping {0!r}: {1}".format(text, error))
            continue
        print(describe(value, unit))
    print("0 C in F:", convert_temperature(0, 'C', 'F'))
    print("273.15 K in C:", convert_temperature(273.15, 'K', 'C'))

if __name__ == '__main__':
    main()

