def dominant_type(groups):
    """Return the type name with the most members, or None when empty."""
    best = None
    best_size = 0
    for name, members in groups.items():
        if len(members) > best_size:
            best = name
            best_size = len(members)
    return best


def format_groups(groups, max_shown=3):
    """Build report lines listing each type, its count and sample members."""
    lines = []
    for name, members in groups.items():
        sample = [repr(value) for value in members[:max_shown]]
        if len(members) > max_shown:
            sample.append("...")
        lines.append("{:>8} x{:<3} {}".format(name, len(members), ", ".join(sample)))
    return lines


def flatten_nested(items):
    """Expand nested lists and tuples one level deep into a flat list."""
    flat = []
    for item in items:
        if isinstance(item, (list, tuple)):
            for inner in item:
                flat.append(inner)
        else:
            flat.append(item)
    return flat


