def find_divisors(n):
  """Return all positive divisors of n in ascending order."""
  if not isinstance(n, int) or isinstance(n, bool):
    raise TypeError("n must be an integer")
  if n < 1:
    raise ValueError("n must be a positive integer")
  small = []
  large = []
  step = 1
  while step * step <= n:
    if n % step == 0:
      small.append(step)
      partner = n // step
      if partner != step:
        large.append(partner)
    step += 1
  large.reverse()
  return small + large


def proper_divisors(n):
  """Return the divisors of n excluding n itself."""
  divisors = find_divisors(n)
  return divisors[:-1]


def classify(n):
  """Label n as perfect, abundant or deficient from its proper divisors."""
  total = sum(proper_divisors(n))
  if total == n:
    return "perfect"
  if total > n:
    return "abundant"
  return "deficient"


def is_prime(n):
  """A number is prime when it has exactly two divisors."""
  return len(find_divisors(n)) == 2


def divisor_pairs(n):
