import random
import string

MIN_LENGTH = 4
CATEGORIES = dict(uppercase=string.ascii_uppercase, lowercase=string.ascii_lowercase, digits=string.digits)
ROW = "%-16s %-8s %s"


def generate_password(length):
    """Return a random password of `length` chars mixing case and digits."""
    if not isinstance(length, int) or isinstance(length, bool):
        raise TypeError("length must be an integer")
    if length < MIN_LENGTH:
        raise ValueError("length must be at least %d" % MIN_LENGTH)
    chars = []
    for pool in CATEGORIES.values():
        chars.append(random.choice(pool))
    alphabet = "".join(CATEGORIES.values())
    while len(chars) < length:
        chars.append(random.choice(alphabet))
    random.shuffle(chars)
    return "".join(chars)


def classify(char):
    """Return the name of the category a character belongs to."""
    for name, pool in CATEGORIES.items():
        if char in pool:
            return name
    return "other"


def composition(password):
    """Count how many characters of each category the password holds."""
    counts = dict.fromkeys(CATEGORIES, 0)
    counts["other"] = 0
    for char in password:
        counts[classify(char)] += 1
    return counts


def strength(password):
    """Rate a password as weak, fair or strong."""
    counts = composition(password)
    variety = 0
    for name in CATEGORIES:
        if counts[name] > 0:
            variety += 1
    if len(password) >= 12 and variety == 3:
        return "strong"
    if len(password) >= 8 and variety >= 2:
        return "fair"
    return "weak"


def report(lengths):
    """Build report lines for one generated password per requested length."""
    lines = []
    for length in lengths:
        password = generate_password(length)
        counts = composition(password)
        parts = []
        for name in CATEGORIES:
            parts.append("%s=%d" % (name, counts[name]))
        lines.append(ROW % (password, strength(password), " ".join(parts)))
    return lines


def main():
    print(ROW % ("PASSWORD", "RATING", "COMPOSITION"))
    for line in report([4, 8, 12, 16]):
        print(line)


if __name__ == "__main__":
    main()

