    numbers.append(float(token))
  return numbers


def describe_series(numbers):
  """Build a short report of a series and its sample standard deviation."""
  values = validate_numbers(numbers)
  lines = ["n = %d" % len(values)]
  if values:
    lines.append("mean = %g" % (sum(values) / len(values)))
    lines.append("min = %g, max = %g" % (min(values), max(values)))
  std_dev = calculate_sample_std_dev(values)
  if len(values) < 2:
    lines.append("sample std dev = 0.0 (needs at least two values)")
  else:
    lines.append("sample std dev = %r" % std_dev)
  return "\n".join(lines)


