import datetime
from datetime import date, timedelta


def get_next_business_day(day):
    """Return the next Monday-Friday date strictly after `day`."""
    if not isinstance(day, date):
        raise TypeError("day must be a datetime.date instance")
    candidate = day + timedelta(days=1)
    while candidate.weekday() >= 5:
        candidate += timedelta(days=1)
    return candidate


def business_days_between(start, end):
    """Count business days strictly after `start` and up to `end`."""
    if end < start:
        raise ValueError("end must not precede start")
    count = 0
    cursor = start
    while cursor < end:
        cursor = get_next_business_day(cursor)
        if cursor <= end:
            count += 1
    return count


def add_business_days(day, number):
    """Advance `day` by `number` business days."""
    if number < 0:
        raise ValueError("number must be non-negative")
    result = day
    for _ in range(number):
        result = get_next_business_day(result)
    return result


def parse_date(text):
    """Parse an ISO date string, rejecting anything malformed."""
    try:
        return datetime.datetime.strptime(text.strip(), "%Y-%m-%d").date()
    except ValueError:
        raise ValueError("expected a date formatted as YYYY-MM-DD: %r" % text)


def describe(day):
    """Format a date together with its weekday name."""
    return "%s (%s)" % (day.isoformat(), day.strftime("%A"))


def report(texts):
    """Build a report of the next business day for each supplied date string."""
    lines = []
    for text in texts:
        try:
            day = parse_date(text)
        except ValueError as exc:
            lines.append("skipping: %s" % exc)
            continue
        nxt = get_next_business_day(day)
        gap = (nxt - day).days
        lines.append("%s -> %s, %d day(s) later" % (describe(day), describe(nxt), gap))
    return lines


def main():
    samples = ["2023-10-26", "2023-10-27", "2023-10-28", "2023-10-29", "not-a-date"]
    for line in report(samples):
        print(line)
    friday = parse_date("2023-10-27")
    week_later = add_business_days(friday, 5)
    print("Five business days after %s is %s" % (describe(friday), describe(week_later)))
    print("Business days in between: %d" % business_days_between(friday, week_later))


if __name__ == "__main__":
    main()

