def validate_interval(interval):
    if not isinstance(interval, (tuple, list)) or len(interval) != 2:
        raise ValueError("an interval must be a pair of numbers")
    start, end = interval
    for value in (start, end):
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError("interval bounds must be numbers")
    if start > end:
        raise ValueError("start_time must not exceed end_time")
    return start, end


def check_interval_overlap(interval1, interval2):
    start1, end1 = validate_interval(interval1)
    start2, end2 = validate_interval(interval2)
    return start1 <= end2 and start2 <= end1


def overlap_length(interval1, interval2):
    if not check_interval_overlap(interval1, interval2):
        return 0
    start = max(interval1[0], interval2[0])
    end = min(interval1[1], interval2[1])
    return end - start


def find_overlapping_pairs(intervals):
    pairs = []
    for i in range(len(intervals)):
        for j in range(i + 1, len(intervals)):
            if check_interval_overlap(intervals[i], intervals[j]):
                pairs.append((i, j))
    return pairs


def merge_intervals(intervals):
    ordered = sorted(validate_interval(item) for item in intervals)
    merged = []
    for start, end in ordered:
        if merged and start <= merged[-1][1]:
            last_start, last_end = merged[-1]
            merged[-1] = (last_start, max(last_end, end))
        else:
            merged.append((start, end))
    return merged


def format_interval(interval):
    start, end = interval
    return "[{0:g}, {1:g}]".format(start, end)


def describe_pair(interval1, interval2):
    text = "{0} vs {1}: ".format(format_interval(interval1), format_interval(interval2))
    if check_interval_overlap(interval1, interval2):
        shared = overlap_length(interval1, interval2)
        if shared == 0:
            return text + "touch at a single point"
        return text + "overlap by {0:g}".format(shared)
    return text + "no overlap"


def main():
    samples = [((1, 5), (3, 7)), ((1, 5), (6, 10)), ((0, 2), (2, 4))]
    for first, second in samples:
        print(describe_pair(first, second))
    schedule = [(9, 10.5), (10, 11), (13, 14), (13.5, 15), (16, 17)]
    print("schedule:", " ".join(format_interval(item) for item in schedule))
    for i, j in find_overlapping_pairs(schedule):
        print("conflict between slot {0} and slot {1}".format(i, j))
    print("merged:", " ".join(format_interval(item) for item in merge_intervals(schedule)))


if __name__ == "__main__":
    main()

