from datetime import date, datetime


def parse_date(date_str):
    """Return a date object for a 'YYYY-MM-DD' string, raising ValueError otherwise."""
    if not isinstance(date_str, str):
        raise ValueError("date must be given as a 'YYYY-MM-DD' string")
    return datetime.strptime(date_str, "%Y-%m-%d").date()


def record_expense(expenses, description, amount, date_str):
    """Append a new expense dictionary to the expenses list."""
    description = description.strip()
    if not description:
        raise ValueError("description must not be empty")
    amount = float(amount)
    if amount < 0:
        raise ValueError("amount must not be negative")
    parse_date(date_str)
    expenses.append({
        "description": description,
        "amount": amount,
        "date": date_str,
    })


def total_amount(expenses):
    """Sum the amounts of all recorded expenses."""
    total = 0.0
    for expense in expenses:
        total += expense["amount"]
    return total


def totals_by_month(expenses):
    """Map 'YYYY-MM' keys to the total spent in that month."""
    months = {}
    for expense in expenses:
        key = expense["date"][:7]
        months[key] = months.get(key, 0.0) + expense["amount"]
    return months


def expenses_in_range(expenses, start_str, end_str):
    """Return the expenses whose date falls between two inclusive bounds."""
    start = parse_date(start_str)
    end = parse_date(end_str)
    if start > end:
        raise ValueError("start date must not be after end date")
    selected = []
    for expense in expenses:
        when = parse_date(expense["date"])
        if start <= when <= end:
            selected.append(expense)
    return selected


def format_report(expenses):
    """Build a human readable report of expenses, sorted by date."""
    lines = []
    for expense in sorted(expenses, key=lambda item: item["date"]):
        lines.append("{date}  {description:<12} {amount:>9.2f}".format(**expense))
    for month in sorted(totals_by_month(expenses)):
        lines.append("subtotal {0}: {1:.2f}".format(month, totals_by_month(expenses)[month]))
    lines.append("TOTAL: {0:.2f}".format(total_amount(expenses)))
    return "\n".join(lines)


def main():
    expenses = []
    record_expense(expenses, "Rent", 1000.0, "2023-10-01")
    record_expense(expenses, "Groceries", 50.0, "2023-10-25")
    record_expense(expenses, "Dinner", 25.50, "2023-10-26")
    record_expense(expenses, "Bus pass", 42.0, "2023-11-02")
    print(format_report(expenses))
    october = expenses_in_range(expenses, "2023-10-01", "2023-10-31")
    print("October entries: {0}".format(len(october)))
    today = date.today().isoformat()
    upcoming = expenses_in_range(expenses, today, "2099-12-31")
    if upcoming:
        print("Warning: {0} expense(s) dated in the future".format(len(upcoming)))


if __name__ == "__main__":
    main()

