import sys


def is_valid_us_zip_code(value):
    """Return True if value is a string of exactly 5 digits."""
    if not isinstance(value, str):
        return False
    if len(value) != 5:
        return False
    for char in value:
        if char not in '0123456789':
            return False
    return True


def normalize_zip_code(raw):
    """Strip surrounding whitespace and drop a ZIP+4 suffix, if present."""
    text = raw.strip()
    if '-' in text:
        text = text.split('-', 1)[0].strip()
    return text


def describe(raw):
    """Explain why a candidate zip code is accepted or rejected."""
    candidate = normalize_zip_code(raw)
    if is_valid_us_zip_code(candidate):
        return 'valid'
    if candidate == '':
        return 'empty input'
    digits = [char for char in candidate if char.isdigit()]
    if len(digits) != len(candidate):
        return 'contains non-digit characters'
    if len(candidate) < 5:
        return 'too short (%d digits)' % len(candidate)
    return 'too long (%d digits)' % len(candidate)


def validate_all(candidates):
    """Pair every candidate with its normalized form and validity."""
    results = []
    for raw in candidates:
        candidate = normalize_zip_code(raw)
        results.append((raw, candidate, is_valid_us_zip_code(candidate)))
    return results


def format_report(results):
    """Build an aligned, human-readable report of the validation results."""
    width = 0
    for raw, _candidate, _ok in results:
        if len(repr(raw)) > width:
            width = len(repr(raw))
    lines = []
    for raw, candidate, ok in results:
        if ok:
            mark = 'OK '
        else:
            mark = 'BAD'
        detail = describe(raw)
        shown = candidate or '-'
        lines.append('%s %-*s -> %s (%s)' % (mark, width, repr(raw), shown, detail))
    valid_count = sum(1 for _raw, _candidate, ok in results if ok)
    summary = '%d of %d candidates are valid US zip codes'
    lines.append(summary % (valid_count, len(results)))
    return '\n'.join(lines)


def main(argv):
    candidates = argv[1:]
    if not candidates:
        candidates = ['90210', '1234', ' 02134 ', '10001-1234', 'ABCDE', '123456']
    results = validate_all(candidates)
    print(format_report(results))
    for _raw, _candidate, ok in results:
        if not ok:
            return 1
    return 0


if __name__ == '__main__':
    sys.exit(main(sys.argv))

