import math

def is_point_in_circle(px, py, cx, cy, radius):
    """Return True if (px, py) lies inside or on the circle (cx, cy, radius)."""
    if radius < 0:
        raise ValueError("radius must be non-negative")
    dx = px - cx
    dy = py - cy
    return dx * dx + dy * dy <= radius * radius


def distance_to_center(px, py, cx, cy):
    """Euclidean distance from the point to the circle's center."""
    return math.hypot(px - cx, py - cy)


def classify_point(px, py, cx, cy, radius):
    """Classify a point as 'inside', 'boundary' or 'outside' the circle."""
    dist = distance_to_center(px, py, cx, cy)
    if math.isclose(dist, radius, rel_tol=1e-9, abs_tol=1e-12):
        return "boundary"
    if dist < radius:
        return "inside"
    return "outside"


def filter_points_in_circle(points, cx, cy, radius):
    """Keep only the points that are inside or on the circle."""
    kept = []
    for px, py in points:
        if is_point_in_circle(px, py, cx, cy, radius):
            kept.append((px, py))
    return kept


def format_report_line(px, py, cx, cy, radius):
    """Build one human-readable line describing the point's position."""
    kind = classify_point(px, py, cx, cy, radius)
    dist = distance_to_center(px, py, cx, cy)
    return "({:g}, {:g}) -> {:<8} distance = {:.3f}".format(px, py, kind, dist)


def report(points, cx, cy, radius):
    """Print a report for every point, then a summary of the hits."""
    header = "Circle center ({:g}, {:g}), radius {:g}".format(cx, cy, radius)
    print(header)
    print("-" * len(header))
    for px, py in points:
        print(format_report_line(px, py, cx, cy, radius))
    inside = filter_points_in_circle(points, cx, cy, radius)
    print("-" * len(header))
    print("{} of {} point(s) inside or on the boundary".format(len(inside), len(points)))
    if inside:
        furthest = max(inside, key=lambda p: distance_to_center(p[0], p[1], cx, cy))
        print("Furthest accepted point: ({:g}, {:g})".format(*furthest))


def main():
    samples = [(1, 1), (3, 3), (2, 0), (0, -2), (-1.5, 1.2), (0, 0)]
    report(samples, 0, 0, 2)
    print()
    report([(5, 5), (4, 1), (1, 1)], 4, 4, 3)
    print()
    try:
        is_point_in_circle(0, 0, 0, 0, -1)
    except ValueError as exc:
        print("Rejected invalid circle:", exc)


if __name__ == "__main__":
    main()

