def enqueue(queue, item):
    """Append item to the end of queue."""
    queue.append(item)


def dequeue(queue):
    """Remove and return the first item of queue, or None if empty."""
    if not queue:
        return None
    return queue.pop(0)


def peek(queue):
    """Return the first item without removing it, or None if empty."""
    if not queue:
        return None
    return queue[0]


def format_queue(queue):
    """Render the queue as front-to-back arrow notation."""
    if not queue:
        return "<empty>"
    return " -> ".join(str(item) for item in queue)


def parse_command(line):
    """Turn a text command into a (name, argument) pair."""
    parts = line.split(maxsplit=1)
    if not parts:
        raise ValueError("empty command")
    name = parts[0].lower()
    if name == "enqueue":
        if len(parts) < 2:
            raise ValueError("enqueue requires an item")
        return name, parts[1].strip()
    if name in ("dequeue", "peek", "show"):
        return name, None
    raise ValueError("unknown command: " + parts[0])


def run_commands(queue, lines):
    """Apply each command to queue and collect a report line for each."""
    report = []
    for line in lines:
        try:
            name, argument = parse_command(line)
        except ValueError as error:
            report.append("error: {}".format(error))
            continue
        if name == "enqueue":
            enqueue(queue, argument)
            report.append("enqueued {}".format(argument))
        elif name == "dequeue":
            item = dequeue(queue)
            if item is None:
                report.append("dequeued nothing (queue was empty)")
            else:
                report.append("dequeued {}".format(item))
        elif name == "peek":
            report.append("front is {}".format(peek(queue)))
        else:
            report.append("queue: {}".format(format_queue(queue)))
    return report


def main():
    script = [
        "dequeue",
        "enqueue apples",
        "enqueue bread",
        "show",
        "peek",
        "dequeue",
        "show",
        "sort by price",
    ]
    queue = []
    for message in run_commands(queue, script):
        print(message)
    print("final queue:", format_queue(queue))


if __name__ == "__main__":
    main()

