def calculate_triangle_perimeter(side1, side2, side3):
  """Return the perimeter of a triangle with the three given side lengths."""
  for name, value in (("side1", side1), ("side2", side2), ("side3", side3)):
    if not isinstance(value, (int, float)) or isinstance(value, bool):
      raise TypeError("{} must be a number, got {!r}".format(name, value))
    if value <= 0:
      raise ValueError("{} must be positive, got {}".format(name, value))
  sides = sorted((side1, side2, side3))
  if sides[0] + sides[1] <= sides[2]:
    raise ValueError("sides {} do not form a triangle".format(tuple(sides)))
  return side1 + side2 + side3


def classify_triangle(side1, side2, side3):
  """Return 'equilateral', 'isosceles' or 'scalene' for the given sides."""
  a, b, c = sorted((side1, side2, side3))
  if a == b == c:
    return "equilateral"
  if a == b or b == c:
