def count_lines_in_text(text):
    """Return the number of lines in text, where lines are separated by '\\n'."""
    if not isinstance(text, str):
        raise TypeError("count_lines_in_text expects a string")
    if text == "":
        return 0
    count = text.count("\n")
    if not text.endswith("\n"):
        count += 1
    return count


def split_lines(text):
    """Split text into its lines without keeping the line terminators."""
    lines = text.split("\n")
    if lines and lines[-1] == "":
        lines.pop()
    return lines


def count_non_empty_lines(text):
    """Count the lines that contain at least one non-whitespace character."""
    total = 0
    for line in split_lines(text):
        if line.strip():
            total += 1
    return total


def longest_line(text):
    """Return the longest line of text, or an empty string when there is none."""
    best = ""
    for line in split_lines(text):
        if len(line) > len(best):
            best = line
    return best


def format_report(name, text):
    """Build a short human readable summary of the line statistics of text."""
    total = count_lines_in_text(text)
    filled = count_non_empty_lines(text)
    parts = ["{}: {} line(s), {} non-empty".format(name, total, filled)]
    if total > 0:
        longest = longest_line(text)
        parts.append("  longest ({} chars): {!r}".format(len(longest), longest))
    return "\n".join(parts)


