def is_leap_year(year):
    """Return True when the given Gregorian year is a leap year."""
    if not isinstance(year, int) or isinstance(year, bool):
        raise TypeError("year must be an integer")
    if year % 400 == 0:
        return True
    if year % 100 == 0:
        return False
    return year % 4 == 0


MONTH_NAMES = (
    "January", "February", "March", "April", "May", "June",
    "July", "August", "September", "October", "November", "December",
)

MONTH_LENGTHS = (31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31)


def days_in_month(year, month):
    """Return the number of days in the given month of the given year."""
    if month < 1 or month > 12:
        raise ValueError("month must be between 1 and 12")
    if month == 2 and is_leap_year(year):
        return 29
    return MONTH_LENGTHS[month - 1]


def days_in_year(year):
    """Return 366 for leap years and 365 otherwise."""
    total = 0
    for month in range(1, 13):
        total += days_in_month(year, month)
    return total


def leap_years_between(start, end):
    """Return the sorted list of leap years in the inclusive range."""
    if start > end:
        start, end = end, start
    return [year for year in range(start, end + 1) if is_leap_year(year)]


def next_leap_year(year):
    """Return the first leap year strictly greater than the given year."""
    candidate = year + 1
    while not is_leap_year(candidate):
        candidate += 1
    return candidate


def describe_year(year):
    """Build a one-line human readable summary of a year."""
    kind = "a leap year" if is_leap_year(year) else "a common year"
    february = days_in_month(year, 2)
    return "{0} is {1}: {2} days, February has {3}.".format(
        year, kind, days_in_year(year), february
    )


def main():
    for year in (2000, 1900, 2024):
        print(describe_year(year))
    decade = leap_years_between(2000, 2009)
    print("Leap years from 2000 to 2009:", ", ".join(str(y) for y in decade))
    for year in (1896, 2023):
        print("The leap year after {0} is {1}.".format(year, next_leap_year(year)))
    print("Month lengths in 2024:")
    for month in range(1, 13):
        name = MONTH_NAMES[month - 1]
        print("    {0:<9} {1}".format(name, days_in_month(2024, month)))


if __name__ == "__main__":
    main()

