import re
from datetime import date

DATE_PATTERN = re.compile(r"^\d{4}-\d{2}-\d{2}$")


def parse_date(date_str):
    """Return a date object for 'YYYY-MM-DD', raising ValueError if malformed."""
    if not DATE_PATTERN.match(date_str):
        raise ValueError("date must look like 'YYYY-MM-DD', got %r" % (date_str,))
    year, month, day = (int(part) for part in date_str.split("-"))
    return date(year, month, day)


def add_calendar_event(calendar, date_str, event_description):
    """Append event_description to the list of events stored under date_str."""
    parse_date(date_str)
    description = event_description.strip()
    if not description:
        raise ValueError("event description must not be empty")
    if date_str not in calendar:
        calendar[date_str] = []
    calendar[date_str].append(description)


def remove_calendar_event(calendar, date_str, event_description):
    """Remove one matching event; drop the date entirely when it becomes empty."""
    events = calendar.get(date_str)
    if events is None or event_description not in events:
        return False
    events.remove(event_description)
    if not events:
        del calendar[date_str]
    return True


def events_between(calendar, start_str, end_str):
    """Yield (date_str, events) pairs within the inclusive range, in date order."""
    start = parse_date(start_str)
    end = parse_date(end_str)
    if start > end:
        start, end = end, start
    for date_str in sorted(calendar):
        if start <= parse_date(date_str) <= end:
            yield date_str, calendar[date_str]


def format_calendar(calendar):
    """Build a human readable agenda for the whole calendar."""
    lines = []
    for date_str in sorted(calendar):
        day = parse_date(date_str)
        lines.append("%s (%s)" % (date_str, day.strftime("%A")))
        for index, description in enumerate(calendar[date_str], start=1):
            lines.append("  %d. %s" % (index, description))
    if not lines:
