def calculate_hamming_distance(s1, s2):
    """Return the number of positions where s1 and s2 differ."""
    if len(s1) != len(s2):
        raise ValueError("strings must have equal length")
    distance = 0
    for a, b in zip(s1, s2):
        if a != b:
            distance += 1
    return distance


def mismatch_positions(s1, s2):
    """Return the indices at which s1 and s2 hold different characters."""
    if len(s1) != len(s2):
        raise ValueError("strings must have equal length")
    positions = []
    for index, (a, b) in enumerate(zip(s1, s2)):
        if a != b:
            positions.append(index)
    return positions


def similarity_ratio(s1, s2):
    """Return the fraction of positions that match, or 1.0 for empty strings."""
    length = len(s1)
    if length == 0:
        return 1.0
    return (length - calculate_hamming_distance(s1, s2)) / length


def mismatch_marker(s1, s2):
    """Build a caret line marking the differing columns."""
    marks = [" "] * len(s1)
    for index in mismatch_positions(s1, s2):
        marks[index] = "^"
    return "".join(marks)


def format_report(s1, s2):
    """Produce a multi-line human readable comparison of two strings."""
    lines = [s1, s2, mismatch_marker(s1, s2)]
    distance = calculate_hamming_distance(s1, s2)
    lines.append("distance: {0}".format(distance))
    if distance == 0:
        lines.append("the strings are identical")
    else:
        spots = ", ".join(str(p) for p in mismatch_positions(s1, s2))
        lines.append("differing positions: " + spots)
    lines.append("similarity: {0:.1%}".format(similarity_ratio(s1, s2)))
    return "\n".join(lines)


def main():
    pairs = [
        ("karolin", "kathrin"),
        ("python", "python"),
        ("GAGCCTACTAACGGGAT", "CATCGTAATGACGGCCT"),
        ("abc", "abcd"),
    ]
    for s1, s2 in pairs:
        try:
            print(format_report(s1, s2))
        except ValueError as error:
            print("cannot compare {0!r} and {1!r}: {2}".format(s1, s2, error))
        print("-" * 40)


if __name__ == "__main__":
    main()

