def character_frequency(text):
    """Count occurrences of each character in text, ignoring case and whitespace."""
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    counts = {}
    for char in text:
        if char.isspace():
            continue
        key = char.lower()
        if key in counts:
            counts[key] += 1
        else:
            counts[key] = 1
    return counts


def most_common(counts, limit=3):
    """Return up to `limit` (character, count) pairs, highest count first."""
    ordered = sorted(counts.items(), key=lambda pair: (-pair[1], pair[0]))
    return ordered[:limit]


def repeated_characters(counts):
    """Return the characters that appear more than once, in alphabetical order."""
    repeated = []
    for char in sorted(counts):
        if counts[char] > 1:
            repeated.append(char)
    return repeated


def format_report(text):
    """Build a multi-line human readable report about the characters in text."""
    counts = character_frequency(text)
    lines = ["Text: {!r}".format(text)]
    if not counts:
        lines.append("  (no countable characters)")
        return "\n".join(lines)
    total = sum(counts.values())
    lines.append("  counted characters: {} ({} distinct)".format(total, len(counts)))
    for char, count in most_common(counts):
        share = 100.0 * count / total
        lines.append("  {!r}: {} ({:.1f}%)".format(char, count, share))
    repeated = repeated_characters(counts)
    if repeated:
        lines.append("  repeated: " + ", ".join(repeated))
    else:
        lines.append("  repeated: none")
    return "\n".join(lines)


def main():
    samples = ["Hello World", "Python", "Mississippi River", "   "]
    for sample in samples:
        print(format_report(sample))
        print()
    grand_total = {}
    for sample in samples:
        for char, count in character_frequency(sample).items():
            grand_total[char] = grand_total.get(char, 0) + count
    print("Combined frequencies over all samples:")
    for char in sorted(grand_total):
        print("  {}: {}".format(char, grand_total[char]))


if __name__ == "__main__":
    main()

