def fibonacci_sequence(n):
    """Return a list with the first 'n' numbers of the Fibonacci sequence."""
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("n must be an integer")
    if n < 0:
        raise ValueError("n must be non-negative")
    sequence = []
    current, following = 0, 1
    for _ in range(n):
        sequence.append(current)
        current, following = following, current + following
    return sequence


def is_fibonacci(value):
    """Return True if 'value' appears in the Fibonacci sequence."""
    if value < 0:
        return False
    current, following = 0, 1
    while current < value:
        current, following = following, current + following
    return current == value


def golden_ratios(sequence):
    """Return the ratios between consecutive non-zero Fibonacci numbers."""
    ratios = []
    for index in range(1, len(sequence)):
        previous = sequence[index - 1]
        if previous != 0:
            ratios.append(sequence[index] / previous)
    return ratios


def format_sequence(sequence, per_line=8):
    """Render a sequence as right-aligned columns, 'per_line' numbers per row."""
    if not sequence:
        return "(empty)"
    width = max(len(str(number)) for number in sequence)
    lines = []
    for start in range(0, len(sequence), per_line):
        chunk = sequence[start:start + per_line]
        lines.append(" ".join(str(number).rjust(width) for number in chunk))
    return "\n".join(lines)


def report(n):
    """Build a short textual report about the first 'n' Fibonacci numbers."""
    sequence = fibonacci_sequence(n)
    lines = ["First {} Fibonacci number(s):".format(n), format_sequence(sequence)]
    lines.append("Sum: {}".format(sum(sequence)))
    ratios = golden_ratios(sequence)
    if ratios:
        lines.append("Last ratio: {:.6f}".format(ratios[-1]))
    return "\n".join(lines)


def main():
    for count in (1, 5, 20):
        print(report(count))
        print()
    candidates = [4, 8, 13, 21, 50, 144]
    for candidate in candidates:
        if is_fibonacci(candidate):
            print("{} is a Fibonacci number".format(candidate))
        else:
            print("{} is not a Fibonacci number".format(candidate))
    try:
        fibonacci_sequence(-3)
    except ValueError as error:
        print("Rejected negative input:", error)


if __name__ == "__main__":
    main()

