def validate(nums):
    """Raise ValueError unless nums holds n-1 distinct integers from 1..n."""
    if not nums:
        raise ValueError("at least one number is required")
    expected_max = len(nums) + 1
    seen = set()
    for value in nums:
        if not isinstance(value, int):
            raise ValueError("not an integer: {!r}".format(value))
        if value < 1 or value > expected_max:
            raise ValueError("{} is outside the range 1..{}".format(value, expected_max))
        if value in seen:
            raise ValueError("duplicated value: {}".format(value))
        seen.add(value)
    return expected_max


def find_missing_number(nums):
    """Return the single number of 1..n that is absent from nums."""
    n = validate(nums)
    complete_sum = n * (n + 1) // 2
    return complete_sum - sum(nums)


def parse_line(line):
    """Turn a line such as '1, 2, 4, 5' or '[1 2 4 5]' into a list of ints."""
    cleaned = line.strip().strip("[]()")
    if not cleaned:
        return []
    tokens = cleaned.replace(",", " ").split()
    numbers = []
    for token in tokens:
        try:
            numbers.append(int(token))
        except ValueError:
            raise ValueError("not a number: {!r}".format(token))
    return numbers


def format_report(nums, missing):
    listing = ", ".join(str(value) for value in nums)
    return "[{}] -> missing {}".format(listing, missing)


def process(lines):
    """Map each non-empty input line to a report or an error message."""
    reports = []
    for number, line in enumerate(lines, start=1):
        try:
            nums = parse_line(line)
            if not nums:
                continue
            reports.append(format_report(nums, find_missing_number(nums)))
        except ValueError as error:
            reports.append("line {}: error: {}".format(number, error))
    return reports


def main():
    import sys

    lines = sys.stdin.read().splitlines()
    reports = process(lines)
    if not reports:
        print("no input: give one list of numbers per line")
        return 1
    for report in reports:
        print(report)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

