from collections import Counter


def first_non_repeating_char(s):
    """Return the first character of s that occurs exactly once, else ''."""
    if not isinstance(s, str):
        raise TypeError("expected a string, got %s" % type(s).__name__)
    counts = Counter(s)
    for ch in s:
        if counts[ch] == 1:
            return ch
    return ""


def all_unique_chars(s):
    """Return the characters of s that occur exactly once, in order."""
    counts = Counter(s)
    unique = []
    for ch in s:
        if counts[ch] == 1:
            unique.append(ch)
    return unique


def index_of_first_unique(s):
    """Return the position of the first non-repeating character, or -1."""
    target = first_non_repeating_char(s)
    if target == "":
        return -1
    return s.index(target)


def describe(s):
    """Build a one-line human readable report for a single input string."""
    first = first_non_repeating_char(s)
    position = index_of_first_unique(s)
    unique = all_unique_chars(s)
    if first == "":
        verdict = "no non-repeating character"
    else:
        verdict = "first unique %r at index %d" % (first, position)
    if unique:
        tail = "all unique: " + "".join(unique)
    else:
        tail = "all unique: (none)"
    return "%-14r -> %-34s | %s" % (s, verdict, tail)


def summarize(strings):
    """Report every string and count how many of them have a unique char."""
    lines = []
    found = 0
    for s in strings:
        lines.append(describe(s))
        if first_non_repeating_char(s) != "":
            found += 1
    summary = "%d of %d strings contain a non-repeating character"
    lines.append(summary % (found, len(strings)))
    return lines


