    stack.push(1)
    stack.push(2)
    print("popped:", stack.pop())
    print("popped:", stack.pop())
    try:
        stack.pop()
    except IndexError as error:
        print("empty stack:", error)
    for line in report(["3 4 +", "5 1 2 + 4 * -", "2 0 /", "1 2"]):
        print(line)


if __name__ == "__main__":
