def normalize(interval):
    """Return the interval as an ordered (low, high) pair of numbers."""
    if not isinstance(interval, (tuple, list)) or len(interval) != 2:
        raise ValueError("an interval must be a pair of numbers")
    low, high = interval
    for value in (low, high):
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise ValueError("interval bounds must be numbers")
    if low > high:
        return (high, low)
    return (low, high)


def interval_intersection(interval1, interval2):
    """Intersect two closed intervals, or return None if they are disjoint."""
    a, b = normalize(interval1)
    c, d = normalize(interval2)
    start = max(a, c)
    end = min(b, d)
    if start > end:
        return None
    return (start, end)


def format_interval(interval):
    """Render an interval (or None) for display."""
    if interval is None:
        return "empty"
    start, end = interval
    if start == end:
        return "{{{0}}}".format(start)
    return "[{0}, {1}]".format(start, end)


def intersect_all(intervals):
    """Intersect a whole sequence of closed intervals left to right."""
    if not intervals:
        raise ValueError("need at least one interval to intersect")
    result = normalize(intervals[0])
    for interval in intervals[1:]:
        result = interval_intersection(result, interval)
        if result is None:
            return None
    return result


def report(pairs):
    """Print one line per pair describing the intersection."""
    for first, second in pairs:
        try:
            outcome = interval_intersection(first, second)
        except ValueError as error:
            print("{0} x {1} -> invalid ({2})".format(first, second, error))
            continue
        print("{0} x {1} -> {2}".format(
            format_interval(normalize(first)),
            format_interval(normalize(second)),
            format_interval(outcome),
        ))


def main():
    pairs = [
        ((1, 5), (3, 7)),
        ((1, 2), (3, 4)),
        ((0, 10), (2, 4)),
        ((5, 1), (1, 1)),
        ((1, 3), (3, 9)),
        ((1, 3), "oops"),
    ]
    report(pairs)
    chains = [
        [(0, 10), (2, 8), (4, 6)],
        [(0, 10), (2, 8), (11, 12)],
    ]
    for chain in chains:
        combined = intersect_all(chain)
        labels = " n ".join(format_interval(normalize(item)) for item in chain)
        print("{0} = {1}".format(labels, format_interval(combined)))


if __name__ == "__main__":
    main()

