class ListNode:
    """A node in a singly linked list."""

    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next


def build_list(values):
    """Build a linked list from an iterable of values and return its head."""
    head = None
    tail = None
    for value in values:
        node = ListNode(value)
        if head is None:
            head = node
        else:
            tail.next = node
        tail = node
    return head


def to_list(head):
    """Collect the values of a linked list into a Python list."""
    values = []
    node = head
    while node is not None:
        values.append(node.val)
        node = node.next
    return values


def format_list(head):
    """Render a linked list as '1->2->3', or 'None' when empty."""
    values = to_list(head)
    if not values:
        return "None"
    return "->".join(str(value) for value in values)


def remove_nth_from_end(head, n):
    """Remove the nth node from the end of the list and return the new head."""
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("n must be an integer")
    if n < 1:
        raise ValueError("n must be at least 1")
    sentinel = ListNode(0, head)
    lead = sentinel
    for _ in range(n):
        if lead.next is None:
            raise ValueError("n is larger than the length of the list")
        lead = lead.next
    trail = sentinel
    while lead.next is not None:
        lead = lead.next
        trail = trail.next
    trail.next = trail.next.next
    return sentinel.next


def main():
    cases = [([1, 2, 3, 4, 5], 2), ([1], 1), ([7, 8], 2), ([3, 1, 4, 1, 5], 5)]
    for values, n in cases:
        head = build_list(values)
        before = format_list(head)
        head = remove_nth_from_end(head, n)
        print("{0:<12} n={1} -> {2}".format(before, n, format_list(head)))
    for values, n in [([1, 2], 5), ([], 1), ([4, 5, 6], 0)]:
        try:
            remove_nth_from_end(build_list(values), n)
        except ValueError as error:
            print("{0} n={1} rejected: {2}".format(values, n, error))


if __name__ == "__main__":
    main()

