def validate(nums):
    """Return the input as a list, raising ValueError on invalid data."""
    if not isinstance(nums, (list, tuple)):
        raise ValueError("nums must be a list or tuple of integers")
    items = list(nums)
    for value in items:
        if not isinstance(value, int) or isinstance(value, bool):
            raise ValueError("all elements must be plain integers: %r" % (value,))
    if len(set(items)) != len(items):
        raise ValueError("all elements must be distinct")
    return items


def generate_subsets(nums):
    """Return every subset of the distinct integers in nums."""
    items = validate(nums)
    subsets = [[]]
    for value in items:
        grown = []
        for subset in subsets:
            grown.append(subset + [value])
        subsets.extend(grown)
    return subsets


def group_by_size(subsets):
    """Map each subset size to the subsets of that size."""
    groups = {}
    for subset in subsets:
        size = len(subset)
        if size not in groups:
            groups[size] = []
        groups[size].append(subset)
    return groups


def format_subset(subset):
    if not subset:
        return "{}"
    return "{" + ", ".join(str(value) for value in subset) + "}"


