def power_iterative(base, exponent):
    """Return base ** exponent for a non-negative integer exponent, iteratively."""
    if not isinstance(exponent, int) or isinstance(exponent, bool):
        raise TypeError("exponent must be an integer")
    if exponent < 0:
        raise ValueError("exponent must be non-negative")
    result = 1
    factor = base
    remaining = exponent
    while remaining > 0:
        if remaining % 2 == 1:
            result *= factor
        factor *= factor
        remaining //= 2
    return result


def power_table(bases, exponents):
    """Build a list of (base, exponent, value) triples for every combination."""
    rows = []
    for base in bases:
        for exponent in exponents:
            rows.append((base, exponent, power_iterative(base, exponent)))
    return rows


def format_rows(rows):
    """Render power rows as aligned text lines."""
    width = 0
    for base, exponent, value in rows:
        text = "{0} ** {1}".format(base, exponent)
        if len(text) > width:
            width = len(text)
    lines = []
    for base, exponent, value in rows:
        text = "{0} ** {1}".format(base, exponent)
        lines.append("{0} = {1}".format(text.ljust(width), value))
    return lines


def parse_request(text):
    """Parse a 'base^exponent' request into a pair of integers."""
    parts = text.split("^")
    if len(parts) != 2:
        raise ValueError("expected the form base^exponent, got {0!r}".format(text))
    numbers = []
    for part in parts:
        stripped = part.strip()
        try:
            numbers.append(int(stripped))
        except ValueError:
            raise ValueError("{0!r} is not an integer".format(stripped))
    return numbers[0], numbers[1]


def main():
    bases = [2, 5, 10]
    exponents = [0, 1, 3]
    for line in format_rows(power_table(bases, exponents)):
        print(line)

    requests = ["3^4", "7 ^ 2", "2^-1", "9"]
    for request in requests:
        try:
            base, exponent = parse_request(request)
            value = power_iterative(base, exponent)
        except ValueError as error:
            print("{0}: error: {1}".format(request, error))
        else:
            print("{0}: {1}".format(request, value))


if __name__ == "__main__":
    main()

