import re


def is_valid_email(email_str: str) -> bool:
    """Return True when email_str looks like a common email address."""
    if not isinstance(email_str, str):
        return False
    candidate = email_str.strip()
    if not candidate or ".." in candidate:
        return False
    return EMAIL_PATTERN.match(candidate) is not None


EMAIL_PATTERN = re.compile(
    r"^[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*\.[A-Za-z]{2,}$"
)


def domain_of(email_str: str) -> str:
    """Return the lowercased domain part, or an empty string if invalid."""
    if not is_valid_email(email_str):
        return ""
    return email_str.strip().rsplit("@", 1)[1].lower()


def partition_addresses(addresses):
    """Split an iterable of addresses into (valid, invalid) lists."""
    valid = []
    invalid = []
    for address in addresses:
        if is_valid_email(address):
            valid.append(address.strip())
        else:
            invalid.append(address)
    return valid, invalid


def count_by_domain(addresses):
    """Map each domain found among the valid addresses to its frequency."""
    counts = {}
    for address in addresses:
        domain = domain_of(address)
        if domain:
            counts[domain] = counts.get(domain, 0) + 1
    return counts


def format_report(addresses):
    """Build a human readable validation report for the given addresses."""
    valid, invalid = partition_addresses(addresses)
    lines = ["Checked {0} address(es)".format(len(addresses))]
    for address in valid:
        lines.append("  OK      {0}".format(address))
    for address in invalid:
        shown = address if isinstance(address, str) else repr(address)
        lines.append("  REJECT  {0}".format(shown or "<empty>"))
    counts = count_by_domain(valid)
    if counts:
        lines.append("Domains:")
        for domain in sorted(counts):
            lines.append("  {0}: {1}".format(domain, counts[domain]))
    else:
        lines.append("Domains: none")
    return "\n".join(lines)


def main():
    samples = [
        "test@example.com",
        "invalid-email",
        "first.last+tag@mail.example.co.uk",
        "user@example.com",
        "  spaced@example.com  ",
        "no@domain",
        "double..dot@example.com",
        "@example.com",
    ]
    print(format_report(samples))


if __name__ == "__main__":
    main()

